std::vector<std::wstring> fomModuleNames(
    std::vector<std::filesystem::path> const& paths) {
  std::vector<std::wstring> result;
  result.reserve(paths.size());
  for (auto const& path : paths) {
    result.push_back(path.wstring());
  }
  return result;
}

void handles(
    Session& session,
    Options const& options,
    rti::ObjectClassHandle& objectClass,
    rti::AttributeHandle& attribute,
    rti::InteractionClassHandle& interactionClass,
    rti::ParameterHandle& parameter) {
  auto& rtiAmbassador = session.rtiAmbassador();
  objectClass = rtiAmbassador.getObjectClassHandle(options.objectClassName);
  attribute = rtiAmbassador.getAttributeHandle(objectClass, options.attributeName);
  interactionClass = rtiAmbassador.getInteractionClassHandle(options.interactionClassName);
  parameter = rtiAmbassador.getParameterHandle(interactionClass, options.parameterName);
  require(objectClass.isValid(), "Object class lookup returned an invalid handle");
  require(attribute.isValid(), "Attribute lookup returned an invalid handle");
  require(interactionClass.isValid(), "Interaction class lookup returned an invalid handle");
  require(parameter.isValid(), "Parameter lookup returned an invalid handle");
}

struct ModelRegionalInteractionHandles {
  rti::InteractionClassHandle interactionClass;
  rti::ParameterHandle parameter;
  rti::DimensionHandle firstDimension;
  rti::DimensionHandle secondDimension;
  rti::DimensionHandle unrelatedDimension;
};

ModelRegionalInteractionHandles modelRegionalInteractionHandles(
    Session& session,
    Options const& options) {
  require(
      options.ddmDimensionNames.size() >= 2U,
      "model regional interaction testing requires two adapter-supplied interaction dimensions");
  auto& rtiAmbassador = session.rtiAmbassador();
  ModelRegionalInteractionHandles result;
  result.interactionClass = rtiAmbassador.getInteractionClassHandle(
      options.customRegionalInteractionClassName);
  result.parameter = rtiAmbassador.getParameterHandle(
      result.interactionClass,
      options.customRegionalParameterName);
  result.firstDimension = rtiAmbassador.getDimensionHandle(
      options.ddmDimensionNames.at(0));
  result.secondDimension = rtiAmbassador.getDimensionHandle(
      options.ddmDimensionNames.at(1));
  result.unrelatedDimension = rtiAmbassador.getDimensionHandle(
      options.fomDimensionName);
  require(
      result.interactionClass.isValid() && result.parameter.isValid(),
      "model regional interaction lookup returned an invalid class or parameter handle");
  require(
      result.firstDimension.isValid() && result.secondDimension.isValid() &&
          result.unrelatedDimension.isValid(),
      "model regional interaction lookup returned an invalid dimension handle");
  require(
      result.firstDimension != result.secondDimension &&
          result.firstDimension != result.unrelatedDimension &&
          result.secondDimension != result.unrelatedDimension,
      "model regional interaction adapter supplied duplicate dimensions");
  auto const availableDimensions =
      rtiAmbassador.getAvailableDimensionsForInteractionClass(result.interactionClass);
  require(
      availableDimensions.count(result.firstDimension) == 1U &&
          availableDimensions.count(result.secondDimension) == 1U &&
          availableDimensions.count(result.unrelatedDimension) == 0U,
      "model regional interaction FOM did not separate available and unrelated dimensions");
  return result;
}

DdmHandles ddmHandles(Session& session, Options const& options) {
  DdmHandles result;
  handles(
      session,
      options,
      result.objectClass,
      result.attribute,
      result.interactionClass,
      result.parameter);
  require(options.ddmDimensionNames.size() >= 2U,
          "DDM scenarios require two adapter-supplied dimension names");
  auto& rtiAmbassador = session.rtiAmbassador();
  result.firstDimension = rtiAmbassador.getDimensionHandle(
      options.ddmDimensionNames.at(0));
  result.secondDimension = rtiAmbassador.getDimensionHandle(
      options.ddmDimensionNames.at(1));
  require(result.firstDimension.isValid() && result.secondDimension.isValid(),
          "DDM dimension lookup returned an invalid handle");
  require(result.firstDimension != result.secondDimension,
          "DDM adapter supplied duplicate dimension names");
  return result;
}


struct MultiAttributeDdmHandles {
  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle firstAttribute;
  rti::AttributeHandle secondAttribute;
  rti::DimensionHandle firstDimension;
  rti::DimensionHandle secondDimension;
};

MultiAttributeDdmHandles multiAttributeDdmHandles(
    Session& session,
    Options const& options) {
  MultiAttributeDdmHandles result;
  auto& rtiAmbassador = session.rtiAmbassador();
  result.objectClass = rtiAmbassador.getObjectClassHandle(
      options.multiAttributeObjectClassName);
  result.firstAttribute = rtiAmbassador.getAttributeHandle(
      result.objectClass,
      options.multiAttributeFirstName);
  result.secondAttribute = rtiAmbassador.getAttributeHandle(
      result.objectClass,
      options.multiAttributeSecondName);
  require(result.objectClass.isValid(),
          "multi-attribute DDM object-class lookup returned an invalid handle");
  require(result.firstAttribute.isValid() && result.secondAttribute.isValid(),
          "multi-attribute DDM attribute lookup returned an invalid handle");
  require(result.firstAttribute != result.secondAttribute,
          "multi-attribute DDM adapter supplied duplicate attribute names");
  require(options.ddmDimensionNames.size() >= 2U,
          "multi-attribute DDM requires two adapter-supplied dimension names");
  result.firstDimension = rtiAmbassador.getDimensionHandle(
      options.ddmDimensionNames.at(0));
  result.secondDimension = rtiAmbassador.getDimensionHandle(
      options.ddmDimensionNames.at(1));
  require(result.firstDimension.isValid() && result.secondDimension.isValid(),
          "multi-attribute DDM dimension lookup returned an invalid handle");
  require(result.firstDimension != result.secondDimension,
          "multi-attribute DDM adapter supplied duplicate dimension names");
  return result;
}

struct ThreeDimensionalDdmHandles {
  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  std::vector<rti::DimensionHandle> dimensions;
};

ThreeDimensionalDdmHandles threeDimensionalDdmHandles(
    Session& session,
    Options const& options) {
  require(
      options.threeDimensionalDimensionNames.size() >= 3U,
      "three-dimensional DDM requires three adapter-supplied dimension names");
  ThreeDimensionalDdmHandles result;
  auto& rtiAmbassador = session.rtiAmbassador();
  result.objectClass = rtiAmbassador.getObjectClassHandle(
      options.threeDimensionalObjectClassName);
  result.attribute = rtiAmbassador.getAttributeHandle(
      result.objectClass,
      options.threeDimensionalAttributeName);
  require(result.objectClass.isValid(),
          "three-dimensional DDM object-class lookup returned an invalid handle");
  require(result.attribute.isValid(),
          "three-dimensional DDM attribute lookup returned an invalid handle");
  for (std::size_t index = 0U; index != 3U; ++index) {
    auto const dimension = rtiAmbassador.getDimensionHandle(
        options.threeDimensionalDimensionNames.at(index));
    require(dimension.isValid(),
            "three-dimensional DDM dimension lookup returned an invalid handle");
    require(
        std::find(result.dimensions.begin(), result.dimensions.end(), dimension) ==
            result.dimensions.end(),
        "three-dimensional DDM adapter supplied duplicate dimension names");
    result.dimensions.push_back(dimension);
  }
  return result;
}

void verifyDdmClassDimensions(
    Session& session,
    Options const& options,
    DdmHandles const& handles,
    std::string const& description) {
  auto& rtiAmbassador = session.rtiAmbassador();
  auto const objectDimensions =
      rtiAmbassador.getAvailableDimensionsForObjectClass(handles.objectClass);
  auto const interactionDimensions =
      rtiAmbassador.getAvailableDimensionsForInteractionClass(handles.interactionClass);
  require(
      objectDimensions.count(handles.firstDimension) == 1U &&
          objectDimensions.count(handles.secondDimension) == 1U,
      description + " object-class dimensions omitted an adapter-supplied dimension");
  require(
      interactionDimensions.count(handles.firstDimension) == 1U &&
          interactionDimensions.count(handles.secondDimension) == 1U,
      description + " interaction-class dimensions omitted an adapter-supplied dimension");
  require(
      rtiAmbassador.getDimensionName(handles.firstDimension) ==
              options.ddmDimensionNames.at(0) &&
          rtiAmbassador.getDimensionName(handles.secondDimension) ==
              options.ddmDimensionNames.at(1),
      description + " dimension-name lookup returned the wrong name");
  require(
      rtiAmbassador.getDimensionUpperBound(handles.firstDimension) >= 4U &&
          rtiAmbassador.getDimensionUpperBound(handles.secondDimension) >= 4U,
      description + " adapter-supplied dimensions have insufficient range");
}

rti::RegionHandle createDdmRegion(
    Session& session,
    DdmHandles const& handles,
    unsigned long firstLower,
    unsigned long firstUpper,
    unsigned long secondLower,
    unsigned long secondUpper) {
  auto& rtiAmbassador = session.rtiAmbassador();
  auto const region = rtiAmbassador.createRegion(
      rti::DimensionHandleSet{handles.firstDimension, handles.secondDimension});
  require(region.isValid(), "DDM region creation returned an invalid handle");
  rtiAmbassador.setRangeBounds(
      region,
      handles.firstDimension,
      rti::RangeBounds(firstLower, firstUpper));
  rtiAmbassador.setRangeBounds(
      region,
      handles.secondDimension,
      rti::RangeBounds(secondLower, secondUpper));
  rtiAmbassador.commitRegionModifications(rti::RegionHandleSet{region});
  return region;
}

rti::RegionHandle createDdmRegionForDimensions(
    Session& session,
    rti::DimensionHandle const& firstDimension,
    rti::DimensionHandle const& secondDimension,
    unsigned long firstLower,
    unsigned long firstUpper,
    unsigned long secondLower,
    unsigned long secondUpper) {
  auto& rtiAmbassador = session.rtiAmbassador();
  auto const region = rtiAmbassador.createRegion(
      rti::DimensionHandleSet{firstDimension, secondDimension});
  require(region.isValid(),
          "multi-attribute DDM region creation returned an invalid handle");
  rtiAmbassador.setRangeBounds(
      region,
      firstDimension,
      rti::RangeBounds(firstLower, firstUpper));
  rtiAmbassador.setRangeBounds(
      region,
      secondDimension,
      rti::RangeBounds(secondLower, secondUpper));
  rtiAmbassador.commitRegionModifications(rti::RegionHandleSet{region});
  return region;
}

rti::RegionHandle createDdmRegionForDimensions(
    Session& session,
    rti::DimensionHandle const& firstDimension,
    rti::DimensionHandle const& secondDimension,
    rti::DimensionHandle const& thirdDimension,
    unsigned long firstLower,
    unsigned long firstUpper,
    unsigned long secondLower,
    unsigned long secondUpper,
    unsigned long thirdLower,
    unsigned long thirdUpper) {
  auto& rtiAmbassador = session.rtiAmbassador();
  auto const region = rtiAmbassador.createRegion(
      rti::DimensionHandleSet{
          firstDimension,
          secondDimension,
          thirdDimension});
  require(region.isValid(),
          "three-dimensional DDM region creation returned an invalid handle");
  rtiAmbassador.setRangeBounds(
      region,
      firstDimension,
      rti::RangeBounds(firstLower, firstUpper));
  rtiAmbassador.setRangeBounds(
      region,
      secondDimension,
      rti::RangeBounds(secondLower, secondUpper));
  rtiAmbassador.setRangeBounds(
      region,
      thirdDimension,
      rti::RangeBounds(thirdLower, thirdUpper));
  rtiAmbassador.commitRegionModifications(rti::RegionHandleSet{region});
  return region;
}

void verifyDdmObjectClassDimensions(
    Session& session,
    Options const& options,
    rti::ObjectClassHandle const& objectClass,
    rti::DimensionHandle const& firstDimension,
    rti::DimensionHandle const& secondDimension,
    std::string const& description) {
  auto& rtiAmbassador = session.rtiAmbassador();
  auto const objectDimensions =
      rtiAmbassador.getAvailableDimensionsForObjectClass(objectClass);
  require(
      objectDimensions.count(firstDimension) == 1U &&
          objectDimensions.count(secondDimension) == 1U,
      description + " object-class dimensions omitted an adapter-supplied dimension");
  require(
      rtiAmbassador.getDimensionName(firstDimension) ==
              options.ddmDimensionNames.at(0) &&
          rtiAmbassador.getDimensionName(secondDimension) ==
              options.ddmDimensionNames.at(1),
      description + " dimension-name lookup returned the wrong name");
  require(
      rtiAmbassador.getDimensionUpperBound(firstDimension) >= 8U &&
          rtiAmbassador.getDimensionUpperBound(secondDimension) >= 8U,
      description + " adapter-supplied dimensions have insufficient range");
}

void verifyThreeDimensionalObjectClassDimensions(
    Session& session,
    Options const& options,
    ThreeDimensionalDdmHandles const& handles,
    std::string const& description) {
  require(
      options.threeDimensionalDimensionNames.size() >= 3U &&
          handles.dimensions.size() == 3U,
      description + " did not resolve three adapter-supplied dimensions");
  auto& rtiAmbassador = session.rtiAmbassador();
  auto const objectDimensions =
      rtiAmbassador.getAvailableDimensionsForObjectClass(handles.objectClass);
  rti::DimensionHandleSet expectedDimensions{
      handles.dimensions.at(0),
      handles.dimensions.at(1),
      handles.dimensions.at(2)};
  require(
      objectDimensions == expectedDimensions,
      description + " object class did not expose exactly the adapter dimensions");
  for (std::size_t index = 0U; index != handles.dimensions.size(); ++index) {
    auto const& dimension = handles.dimensions.at(index);
    require(
        rtiAmbassador.getDimensionName(dimension) ==
            options.threeDimensionalDimensionNames.at(index),
        description + " dimension-name lookup returned the wrong name");
    require(
        rtiAmbassador.getDimensionUpperBound(dimension) >= 8U,
        description + " adapter-supplied dimensions have insufficient range");
  }
}


void enableTimestampedRoles(
    Session& regulator,
    Session& constrained,
    TimeContext const& regulatorTime,
    TimeContext const& constrainedTime,
    Options const& options,
    std::string const& description) {
  require(
      regulatorTime.factory->getName() == constrainedTime.factory->getName(),
      description + " members selected different logical-time factories");
  constrained.rtiAmbassador().enableTimeConstrained();
  waitFor(
      constrained,
      [&] { return constrained.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      description + " time-constrained callback");
  regulator.rtiAmbassador().enableTimeRegulation(*regulatorTime.epsilon);
  waitFor(
      regulator,
      [&] { return regulator.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      description + " time-regulation callback");
}

void scenarioFactoryDiscovery(Options const&, rti::CallbackModel) {
  rti::RTIambassadorFactory factory;
  auto ambassador = factory.createRTIambassador();
  require(
      static_cast<bool>(ambassador),
      "RTIambassadorFactory returned no standard RTIambassador");

  rti::HLAinteger32BE value{0x1234abcd};
  auto const encoded = value.encode();
  require(
      encoded.size() == 4U,
      "The standard C++ encoder did not produce the expected four-octet value");
  rti::HLAinteger32BE decoded;
  decoded.decode(encoded);
  require(
      decoded.get() == 0x1234abcd,
      "The standard C++ encoder did not round-trip through the discovered API");
}

