void scenarioLogicalTimeDataElementsContract(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "logical-time data-element testing requires an adapter-supplied logical-time implementation");
  Session session(options, model, "logical-time-data-elements");
  session.connect();
  auto const federation = federationName(
      options,
      "logical-time-data-elements-contract");
  session.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  session.join(options.ownerFederateName, options.federateType, federation);
  auto const time = makeTimeContext(session);
  verifyLogicalTimeDataElements(session, time);
  session.resign(rti::NO_ACTION);
  session.rtiAmbassador().destroyFederationExecution(federation);
  session.disconnect();
}

