void scenarioResignDeleteObjects(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "resign-delete-owner");
  Session member(options, model, "resign-delete-member");
  auto const federation = federationName(options, "resign-delete-objects");
  connectAndJoin(owner, member, options, federation, options.fom);

  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  rti::InteractionClassHandle interactionClass;
  rti::ParameterHandle parameter;
  handles(owner, options, objectClass, attribute, interactionClass, parameter);
  rti::AttributeHandleSet attributes;
  attributes.insert(attribute);
  owner.rtiAmbassador().publishObjectClassAttributes(objectClass, attributes);
  member.rtiAmbassador().subscribeObjectClassAttributes(objectClass, attributes);

  auto const object = owner.rtiAmbassador().registerObjectInstance(objectClass);
  require(object.isValid(), "Resign-delete registration returned an invalid handle");
  auto const name = owner.rtiAmbassador().getObjectInstanceName(object);
  require(!name.empty(), "Resign-delete registration returned an empty name");
  waitFor(member, [&] { return member.recorder().discovery().present; }, options,
          "resign-delete object discovery");
  auto const discovery = member.recorder().discovery();
  require(discovery.object == object, "Resign-delete discovery returned the wrong object");
  require(discovery.objectClass == objectClass,
          "Resign-delete discovery returned the wrong object class");
  require(discovery.name == name, "Resign-delete discovery returned the wrong object name");

  requireException(
      [&] { owner.resign(rti::NO_ACTION); },
      L"FederateOwnsAttributes",
      "resigning without deleting a delete-privileged object");

  member.recorder().clearRemovals();
  owner.resign(rti::DELETE_OBJECTS);
  waitFor(member,
          [&] {
            return member.recorder().hasRemoval(
                object, {}, owner.federateHandle());
          },
          options,
          "resign-delete object removal");
  auto const removals = member.recorder().removals();
  require(removals.size() == 1U,
          "resign-delete delivered a duplicate object removal callback");
  require(removals.front().object == object && removals.front().tag.empty() &&
              removals.front().producer == owner.federateHandle(),
          "resign-delete returned the wrong removal metadata");
  requireException(
      [&] { static_cast<void>(member.rtiAmbassador().getObjectInstanceHandle(name)); },
      L"ObjectInstanceNotKnown",
      "looking up an object after resign-time deletion");

  member.resign(rti::NO_ACTION);
}

