void scenarioDivestitureIfWantedMixedAcquirers(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.multiAttributeFom.empty(),
      "Divestiture If Wanted testing requires an adapter-supplied multi-attribute FOM");

  Session owner(options, model, "divestiture-if-wanted-owner");
  Session firstRequester(options, model, "divestiture-if-wanted-first");
  Session secondRequester(options, model, "divestiture-if-wanted-second");
  auto const federation = federationName(
      options,
      "divestiture-if-wanted-mixed-acquirers");
  owner.connect();
  firstRequester.connect();
  secondRequester.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-if-wanted-owner",
      options.federateType,
      federation);
  firstRequester.join(
      options.memberFederateName + L"-if-wanted-first",
      options.federateType,
      federation);
  secondRequester.join(
      options.memberFederateName + L"-if-wanted-second",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const firstClass = firstRequester.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const secondClass = secondRequester.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const ownerFirst = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeFirstName);
  auto const ownerSecond = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeSecondName);
  auto const firstAttribute = firstRequester.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.multiAttributeFirstName);
  auto const secondAttribute = secondRequester.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.multiAttributeSecondName);
  require(
      ownerClass.isValid() && firstClass.isValid() && secondClass.isValid(),
      "Divestiture If Wanted object-class lookup returned an invalid handle");
  require(
      ownerFirst.isValid() && ownerSecond.isValid() && firstAttribute.isValid() &&
          secondAttribute.isValid(),
      "Divestiture If Wanted attribute lookup returned an invalid handle");
  require(
      ownerFirst != ownerSecond,
      "Divestiture If Wanted adapter supplied duplicate attribute names");

  rti::AttributeHandleSet const ownerAttributes{ownerFirst, ownerSecond};
  rti::AttributeHandleSet const firstAttributes{firstAttribute};
  rti::AttributeHandleSet const secondAttributes{secondAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  firstRequester.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondRequester.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);
  firstRequester.rtiAmbassador().subscribeObjectClassAttributes(
      firstClass,
      firstAttributes,
      true,
      L"");
  secondRequester.rtiAmbassador().subscribeObjectClassAttributes(
      secondClass,
      secondAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Divestiture If Wanted registration returned an invalid object handle");
  waitFor(
      firstRequester,
      [&] { return firstRequester.recorder().hasDiscovery(object); },
      options,
      "Divestiture If Wanted first-requester discovery");
  waitFor(
      secondRequester,
      [&] { return secondRequester.recorder().hasDiscovery(object); },
      options,
      "Divestiture If Wanted second-requester discovery");

  firstRequester.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondRequester.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Divestiture If Wanted owner did not initially own both attributes");

  rti::VariableLengthData const emptyTag;
  rti::AttributeHandleSet divestedAttributes{ownerFirst};
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerAttributes,
      emptyTag,
      divestedAttributes);
  require(
      divestedAttributes.empty(),
      "Divestiture If Wanted returned attributes without pending acquirers");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Divestiture If Wanted changed ownership without pending acquirers");

  owner.recorder().clearOwnershipRecords();
  firstRequester.recorder().clearOwnershipRecords();
  secondRequester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const firstAcquisitionTagBytes{0xa1U, 0x25U};
  std::vector<std::uint8_t> const secondAcquisitionTagBytes{0xa2U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0xd1U, 0x25U};
  rti::VariableLengthData const firstAcquisitionTag(
      firstAcquisitionTagBytes.data(),
      firstAcquisitionTagBytes.size());
  rti::VariableLengthData const secondAcquisitionTag(
      secondAcquisitionTagBytes.data(),
      secondAcquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  firstRequester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      firstAttributes,
      firstAcquisitionTag);
  if (model == rti::HLA_EVOKED) {
    secondRequester.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
        object,
        secondAttributes,
        secondAcquisitionTag);
  } else {
    // Immediate delivery reports If Available as unavailable before the owner
    // can divest. Use a regular pending acquisition to keep this service test
    // at the same pending-transfer boundary under both callback models.
    secondRequester.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        secondAttributes,
        secondAcquisitionTag);
  }

  // A synchronous provider may already have reported a release or unavailable
  // callback. Clear those records so the post-divestiture assertions detect only
  // stale callbacks that survive the ownership transfer.
  owner.recorder().clearOwnershipRecords();
  firstRequester.recorder().clearOwnershipRecords();
  secondRequester.recorder().clearOwnershipRecords();
  divestedAttributes = rti::AttributeHandleSet{ownerFirst};
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerAttributes,
      divestitureTag,
      divestedAttributes);
  require(
      divestedAttributes == ownerAttributes,
      "Divestiture If Wanted did not transfer exactly the pending attributes");
  require(
      !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Divestiture If Wanted left an attribute with the former owner");
  require(
      firstRequester.rtiAmbassador().isAttributeOwnedByFederate(
          object,
          firstAttribute) &&
          secondRequester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              secondAttribute),
      "Divestiture If Wanted did not transfer each requested attribute");

  waitFor(
      firstRequester,
      [&] { return firstRequester.recorder().ownershipAcquisition().has_value(); },
      options,
      "Divestiture If Wanted first acquisition notification");
  waitFor(
      secondRequester,
      [&] { return secondRequester.recorder().ownershipAcquisition().has_value(); },
      options,
      "Divestiture If Wanted second acquisition notification");
  auto const firstAcquisition = firstRequester.recorder().ownershipAcquisition();
  auto const secondAcquisition = secondRequester.recorder().ownershipAcquisition();
  require(
      firstAcquisition->object == object &&
          firstAcquisition->attributes == firstAttributes &&
          firstAcquisition->tag == divestitureTagBytes,
      "Divestiture If Wanted first notification returned the wrong object, attributes, or tag");
  require(
      secondAcquisition->object == object &&
          secondAcquisition->attributes == secondAttributes &&
          secondAcquisition->tag == divestitureTagBytes,
      "Divestiture If Wanted second notification returned the wrong object, attributes, or tag");

  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  require(
      !owner.recorder().ownershipReleaseRequest().has_value(),
      "Divestiture If Wanted delivered a stale owner-release callback");

  firstRequester.rtiAmbassador().unpublishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondRequester.rtiAmbassador().unpublishObjectClassAttributes(
      secondClass,
      secondAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  firstRequester.resign(rti::NO_ACTION);
  secondRequester.resign(rti::NO_ACTION);
  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  firstRequester.disconnect();
  secondRequester.disconnect();
  owner.disconnect();
}

void scenarioDivestitureIfWantedMixedAcquirersContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioDivestitureIfWantedMixedAcquirers(options, model);
}

void scenarioNegotiatedDivestiturePartialAcquisitionCancellation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.multiAttributeFom.empty(),
      "Partial negotiated divestiture testing requires an adapter-supplied multi-attribute FOM");

  Session owner(options, model, "negotiated-partial-cancel-owner");
  Session requester(options, model, "negotiated-partial-cancel-requester");
  auto const federation = federationName(
      options,
      "negotiated-divestiture-partial-acquisition-cancellation");
  owner.connect();
  requester.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-negotiated-partial-owner",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-negotiated-partial-requester",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const ownerFirst = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeFirstName);
  auto const ownerSecond = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeSecondName);
  auto const requesterFirst = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.multiAttributeFirstName);
  auto const requesterSecond = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.multiAttributeSecondName);
  require(
      ownerClass.isValid() && requesterClass.isValid(),
      "Partial negotiated divestiture object-class lookup returned an invalid handle");
  require(
      ownerFirst.isValid() && ownerSecond.isValid() && requesterFirst.isValid() &&
          requesterSecond.isValid(),
      "Partial negotiated divestiture attribute lookup returned an invalid handle");
  require(
      ownerFirst != ownerSecond,
      "Partial negotiated divestiture adapter supplied duplicate attribute names");

  rti::AttributeHandleSet const ownerAttributes{ownerFirst, ownerSecond};
  rti::AttributeHandleSet const requesterAttributes{requesterFirst, requesterSecond};
  rti::AttributeHandleSet const ownerCancelledAttributes{ownerFirst};
  rti::AttributeHandleSet const ownerRetainedAttributes{ownerSecond};
  rti::AttributeHandleSet const requesterCancelledAttributes{requesterFirst};
  rti::AttributeHandleSet const requesterRetainedAttributes{requesterSecond};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Partial negotiated divestiture registration returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "partial negotiated divestiture discovery");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Partial negotiated divestiture owner did not initially own both attributes");

  std::vector<std::uint8_t> const acquisitionTagBytes{0xc3U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0xd3U, 0x25U};
  std::vector<std::uint8_t> const confirmationTagBytes{0xe3U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());
  rti::VariableLengthData const confirmationTag(
      confirmationTagBytes.data(),
      confirmationTagBytes.size());

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Partial negotiated divestiture changed ownership before cancellation");

  requester.rtiAmbassador().cancelAttributeOwnershipAcquisition(
      object,
      requesterCancelledAttributes);
  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisitionCancellation().has_value(); },
      options,
      "partial negotiated acquisition cancellation confirmation");
  auto const cancellation = requester.recorder().ownershipAcquisitionCancellation();
  require(
      cancellation->object == object &&
          cancellation->attributes == requesterCancelledAttributes,
      "Partial negotiated acquisition cancellation returned the wrong attribute set");
  require(
      !requester.recorder().ownershipAcquisition().has_value(),
      "Partial negotiated acquisition notified the requester before confirmation");

  if (model == rti::HLA_EVOKED) {
    waitFor(
        owner,
        [&] { return owner.recorder().divestitureConfirmation().has_value(); },
        options,
        "partial negotiated divestiture confirmation");
    auto const confirmation = owner.recorder().divestitureConfirmation();
    require(
        confirmation->object == object &&
            confirmation->attributes == ownerRetainedAttributes &&
            confirmation->tag == acquisitionTagBytes,
        "Partial negotiated divestiture confirmation did not retain the uncanceled attribute");
  } else {
    require(
        owner.recorder().divestitureConfirmation().has_value(),
        "Immediate negotiated divestiture did not report its confirmation request");
  }

  owner.rtiAmbassador().confirmDivestiture(
      object,
      ownerRetainedAttributes,
      confirmationTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Partial negotiated divestiture transferred the canceled attribute");
  require(
      !requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterFirst) &&
          requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterSecond),
      "Partial negotiated divestiture did not transfer exactly the retained attribute");

  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisition().has_value(); },
      options,
      "partial negotiated acquisition notification");
  auto const acquisition = requester.recorder().ownershipAcquisition();
  require(
      acquisition->object == object &&
          acquisition->attributes == requesterRetainedAttributes &&
          acquisition->tag == confirmationTagBytes,
      "Partial negotiated acquisition notification returned the wrong attribute set or tag");

  owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
      object,
      ownerCancelledAttributes);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst),
      "Partial negotiated cancellation did not retain the canceled attribute");

  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterClass,
      requesterRetainedAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedDivestiturePartialAcquisitionCancellationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioNegotiatedDivestiturePartialAcquisitionCancellation(options, model);
}


void scenarioNegotiatedDivestitureCancellation(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "negotiated-divestiture-owner");
  Session requester(options, model, "negotiated-divestiture-requester");
  auto const federation = federationName(options, "negotiated-divestiture-cancellation");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Negotiated divestiture cancellation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(),
          "Negotiated divestiture cancellation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "negotiated divestiture cancellation discovery");

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> acquisitionTagBytes{0x49U, 0xa7U, 0x11U};
  std::vector<std::uint8_t> divestitureTagBytes{0x52U, 0xa7U, 0x11U};
  rti::VariableLengthData acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  waitFor(
      owner,
      [&] { return owner.recorder().divestitureConfirmation().has_value(); },
      options,
      "negotiated divestiture confirmation request");
  auto const confirmation = owner.recorder().divestitureConfirmation();
  require(
      confirmation->object == object && confirmation->attributes == ownerAttributes &&
          confirmation->tag == acquisitionTagBytes,
      "negotiated divestiture confirmation did not preserve the acquisition request");
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().ownershipReleaseRequest().has_value(),
        "negotiated divestiture delivered an ordinary release request before cancellation");
  }

  owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes);
  waitFor(
      owner,
      [&] { return owner.recorder().ownershipReleaseRequest().has_value(); },
      options,
      "ordinary release request after negotiated divestiture cancellation");
  auto const releaseRequest = owner.recorder().ownershipReleaseRequest();
  require(
      releaseRequest->object == object && releaseRequest->attributes == ownerAttributes &&
          releaseRequest->tag == acquisitionTagBytes,
      "canceled negotiated divestiture did not restore the ordinary release request");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterAttribute),
      "canceled negotiated divestiture changed ownership");

  requester.rtiAmbassador().cancelAttributeOwnershipAcquisition(
      object,
      requesterAttributes);
  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisitionCancellation().has_value(); },
      options,
      "ownership acquisition cancellation after negotiated divestiture cancellation");
  auto const cancellation = requester.recorder().ownershipAcquisitionCancellation();
  require(
      cancellation->object == object && cancellation->attributes == requesterAttributes,
      "ownership acquisition cancellation returned the wrong object or attributes");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterAttribute),
      "ownership acquisition cancellation changed ownership");

  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.resign(rti::DELETE_OBJECTS);
  requester.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedDivestitureCancellationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioNegotiatedDivestitureCancellation(options, model);
}

void scenarioNegotiatedDivestiturePreDeliveryCancellation(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "negotiated-pre-delivery-owner");
  Session requester(options, model, "negotiated-pre-delivery-requester");
  auto const federation = federationName(
      options,
      "negotiated-divestiture-pre-delivery-cancellation");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Pre-delivery negotiated cancellation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Pre-delivery negotiated cancellation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "pre-delivery negotiated cancellation discovery");
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> acquisitionTagBytes{0xc2U, 0x25U};
  std::vector<std::uint8_t> divestitureTagBytes{0xd2U, 0x25U};
  rti::VariableLengthData acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "evoked negotiated divestiture crossed the callback boundary before cancellation");
  }

  requester.rtiAmbassador().cancelAttributeOwnershipAcquisition(
      object,
      requesterAttributes);
  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisitionCancellation().has_value(); },
      options,
      "pre-delivery ownership acquisition cancellation");
  auto const cancellation = requester.recorder().ownershipAcquisitionCancellation();
  require(
      cancellation->object == object && cancellation->attributes == requesterAttributes,
      "pre-delivery ownership cancellation returned the wrong object or attributes");

  if (model == rti::HLA_EVOKED) {
    for (int pass = 0; pass != 8; ++pass) {
      owner.pump();
    }
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "pre-delivery acquisition cancellation delivered stale owner callbacks");
    owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
        object,
        ownerAttributes);
  }

  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "pre-delivery negotiated cancellation changed ownership");

  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.resign(rti::DELETE_OBJECTS);
  requester.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedWillingToAcquireContinuation(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "negotiated-continuation-owner");
  Session firstCandidate(options, model, "negotiated-continuation-first");
  Session secondCandidate(options, model, "negotiated-continuation-second");
  auto const federation = federationName(
      options,
      "negotiated-willing-to-acquire-continuation");

  owner.connect();
  firstCandidate.connect();
  secondCandidate.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-wta-continuation-owner",
      options.federateType,
      federation);
  firstCandidate.join(
      options.memberFederateName + L"-wta-continuation-first",
      options.federateType,
      federation);
  secondCandidate.join(
      options.memberFederateName + L"-wta-continuation-second",
      options.federateType,
      federation);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const firstClass = firstCandidate.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const firstAttribute = firstCandidate.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.attributeName);
  auto const secondClass = secondCandidate.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const secondAttribute = secondCandidate.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && firstClass.isValid() &&
          firstAttribute.isValid() && secondClass.isValid() &&
          secondAttribute.isValid(),
      "Willing-to-acquire continuation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const firstAttributes{firstAttribute};
  rti::AttributeHandleSet const secondAttributes{secondAttribute};
  firstCandidate.rtiAmbassador().subscribeObjectClassAttributes(
      firstClass,
      firstAttributes,
      true,
      L"");
  secondCandidate.rtiAmbassador().subscribeObjectClassAttributes(
      secondClass,
      secondAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Willing-to-acquire continuation returned an invalid object handle");
  waitFor(
      firstCandidate,
      [&] { return firstCandidate.recorder().hasDiscovery(object); },
      options,
      "Willing-to-acquire continuation first-candidate discovery");
  waitFor(
      secondCandidate,
      [&] { return secondCandidate.recorder().hasDiscovery(object); },
      options,
      "Willing-to-acquire continuation second-candidate discovery");
  firstCandidate.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondCandidate.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);

  owner.recorder().clearOwnershipRecords();
  firstCandidate.recorder().clearOwnershipRecords();
  secondCandidate.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const firstWillingTagBytes{0x81U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const firstRegularTagBytes{0x85U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const secondWillingTagBytes{0x82U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0x83U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const confirmationTagBytes{0x84U, 0xA7U, 0x25U};
  rti::VariableLengthData const firstWillingTag(
      firstWillingTagBytes.data(),
      firstWillingTagBytes.size());
  rti::VariableLengthData const firstRegularTag(
      firstRegularTagBytes.data(),
      firstRegularTagBytes.size());
  rti::VariableLengthData const secondWillingTag(
      secondWillingTagBytes.data(),
      secondWillingTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());
  rti::VariableLengthData const confirmationTag(
      confirmationTagBytes.data(),
      confirmationTagBytes.size());

  auto cancelFirstCandidate = [&] {
    firstCandidate.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        firstAttributes,
        firstRegularTag);
    firstCandidate.rtiAmbassador().cancelAttributeOwnershipAcquisition(
        object,
        firstAttributes);
    waitFor(
        firstCandidate,
        [&] {
          return firstCandidate.recorder().ownershipAcquisitionCancellation().has_value();
        },
        options,
        "Willing-to-acquire first-candidate cancellation");
    auto const cancellation = firstCandidate.recorder().ownershipAcquisitionCancellation();
    require(
        cancellation->object == object && cancellation->attributes == firstAttributes,
        "Willing-to-acquire cancellation returned the wrong object or attributes");
    require(
        !firstCandidate.recorder().ownershipAcquisition().has_value(),
        "Canceled Willing-to-Acquire candidate received an acquisition notification");
  };

  // Evoked delivery retains both Willing-to-Acquire reservations until the
  // owner-side negotiated-divestiture callback is delivered. Immediate
  // delivery reports the unavailable state at the If Available boundary, so
  // it verifies the same continuation through a regular pending acquisition
  // after canceling the first candidate.
  if (model == rti::HLA_IMMEDIATE) {
    cancelFirstCandidate();
    firstCandidate.recorder().clearOwnershipRecords();
    owner.recorder().clearOwnershipRecords();
    secondCandidate.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        secondAttributes,
        secondWillingTag);
  } else {
    firstCandidate.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
        object,
        firstAttributes,
        firstWillingTag);
    secondCandidate.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
        object,
        secondAttributes,
        secondWillingTag);
  }
  require(
      !firstCandidate.recorder().ownershipAcquisition().has_value() &&
          !secondCandidate.recorder().ownershipAcquisition().has_value(),
      "Willing-to-acquire reservation transferred ownership before divestiture");

  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !firstCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              firstAttribute) &&
          !secondCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              secondAttribute),
      "Negotiated Willing-to-Acquire divestiture changed ownership before confirmation");
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "Evoked negotiated continuation crossed the callback boundary before cancellation");
    cancelFirstCandidate();
  }

  waitFor(
      owner,
      [&] { return owner.recorder().divestitureConfirmation().has_value(); },
      options,
      "Willing-to-acquire continuation divestiture confirmation");
  auto const confirmation = owner.recorder().divestitureConfirmation();
  require(
      confirmation->object == object && confirmation->attributes == ownerAttributes &&
          confirmation->tag == secondWillingTagBytes,
      "Continuation confirmation did not select the second Willing-to-Acquire tag");
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().ownershipReleaseRequest().has_value() &&
            !secondCandidate.recorder().ownershipAcquisition().has_value(),
        "Stale first-candidate work produced an owner release or early acquisition callback");
  }

  owner.rtiAmbassador().confirmDivestiture(
      object,
      ownerAttributes,
      confirmationTag);
  require(
      !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !firstCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              firstAttribute) &&
          secondCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              secondAttribute),
      "Negotiated continuation confirmation did not transfer ownership to the second candidate");
  waitFor(
      secondCandidate,
      [&] { return secondCandidate.recorder().ownershipAcquisition().has_value(); },
      options,
      "Willing-to-acquire continuation acquisition notification");
  auto const acquisition = secondCandidate.recorder().ownershipAcquisition();
  require(
      acquisition->object == object && acquisition->attributes == secondAttributes &&
          acquisition->tag == confirmationTagBytes,
      "Continuation acquisition notification returned the wrong object, attributes, or tag");

  firstCandidate.rtiAmbassador().unpublishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondCandidate.rtiAmbassador().unpublishObjectClassAttributes(
      secondClass,
      secondAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  firstCandidate.resign(rti::NO_ACTION);
  secondCandidate.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  firstCandidate.disconnect();
  secondCandidate.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedDivestiturePreDeliveryCancellationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioNegotiatedDivestiturePreDeliveryCancellation(options, model);
}

void scenarioResignPendingAcquisitionRejection(
    Options const& options,
    rti::CallbackModel model) {
  Session pending(options, model, "pending-acquisition");
  Session currentOwner(options, model, "current-owner");
  auto const federation = federationName(options, "resign-pending-acquisition-rejection");
  connectAndJoin(pending, currentOwner, options, federation, options.fom);

  rti::ObjectClassHandle pendingClass;
  rti::AttributeHandle pendingAttribute;
  rti::InteractionClassHandle pendingInteraction;
  rti::ParameterHandle pendingParameter;
  handles(
      pending,
      options,
      pendingClass,
      pendingAttribute,
      pendingInteraction,
      pendingParameter);
  auto const ownerClass = currentOwner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = currentOwner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  require(
      pendingClass.isValid() && pendingAttribute.isValid() && ownerClass.isValid() &&
          ownerAttribute.isValid(),
      "pending-acquisition resignation lookup returned an invalid handle");

  rti::AttributeHandleSet const pendingAttributes{pendingAttribute};
  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  pending.rtiAmbassador().subscribeObjectClassAttributes(
      pendingClass,
      pendingAttributes,
      true,
      L"");
  currentOwner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = currentOwner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(),
          "pending-acquisition resignation returned an invalid object handle");
  waitFor(
      pending,
      [&] { return pending.recorder().hasDiscovery(object); },
      options,
      "pending-acquisition resignation discovery");

  pending.rtiAmbassador().publishObjectClassAttributes(pendingClass, pendingAttributes);
  pending.recorder().clearOwnershipRecords();
  currentOwner.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> acquisitionTagBytes{0xd2U, 0x25U};
  rti::VariableLengthData acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  pending.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      pendingAttributes,
      acquisitionTag);

  requireException(
      [&] { pending.resign(rti::UNCONDITIONALLY_DIVEST_ATTRIBUTES); },
      L"OwnershipAcquisitionPending",
      "unconditional resignation with a pending ownership acquisition");
  require(
      pending.rtiAmbassador().getFederateHandle(options.ownerFederateName).isValid(),
      "pending-acquisition federate left the execution after rejected resignation");

  pending.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  for (int pass = 0; pass != 8; ++pass) {
    currentOwner.pump();
  }
  if (model == rti::HLA_EVOKED) {
    require(
        !currentOwner.recorder().ownershipReleaseRequest().has_value(),
        "canceling the pending acquisition delivered a stale owner-release callback");
  }

  currentOwner.resign(rti::DELETE_OBJECTS);
  currentOwner.rtiAmbassador().destroyFederationExecution(federation);
  pending.disconnect();
  currentOwner.disconnect();
}

void scenarioResignPendingAcquisitionRejectionContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignPendingAcquisitionRejection(options, model);
}

void scenarioResignCancelPendingAcquisition(
    Options const& options,
    rti::CallbackModel model) {
  Session requester(options, model, "resign-cancel-requester");
  Session owner(options, model, "resign-cancel-owner");
  auto const federation = federationName(options, "resign-cancel-pending-acquisition");
  connectAndJoin(requester, owner, options, federation, options.fom);

  rti::ObjectClassHandle requesterClass;
  rti::AttributeHandle requesterAttribute;
  rti::InteractionClassHandle requesterInteraction;
  rti::ParameterHandle requesterParameter;
  handles(
      requester,
      options,
      requesterClass,
      requesterAttribute,
      requesterInteraction,
      requesterParameter);
  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  require(
      requesterClass.isValid() && requesterAttribute.isValid() && ownerClass.isValid() &&
          ownerAttribute.isValid(),
      "resign cancellation lookup returned an invalid handle");

  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "resign cancellation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "resign cancellation discovery");

  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.recorder().clearOwnershipRecords();
  owner.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const acquisitionTagBytes{0xd8U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "pending acquisition changed ownership before resignation cancellation");

  // Clear any immediate callback before exercising the cancellation boundary. The
  // cancellation must prevent an evoked callback that was still queued, while an
  // immediate provider may already have delivered the request synchronously.
  owner.recorder().clearOwnershipRecords();
  requester.resign(rti::CANCEL_PENDING_OWNERSHIP_ACQUISITIONS);
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  require(
      !owner.recorder().ownershipReleaseRequest().has_value(),
      "canceling pending acquisition delivered a stale owner-release callback");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
      "canceling pending acquisition changed the current owner");

  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioResignCancelPendingAcquisitionContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignCancelPendingAcquisition(options, model);
}

void scenarioResignCancelIfAvailablePending(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "resign-cancel-if-available-owner");
  Session requester(options, model, "resign-cancel-if-available-requester");
  auto const federation = federationName(
      options,
      "resign-cancel-if-available-pending");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "If Available resignation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "If Available resignation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "If Available resignation discovery");

  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const acquisitionTagBytes{0xe5U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  requester.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object,
      requesterAttributes,
      acquisitionTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "If Available acquisition changed ownership before resignation cancellation");

  // Immediate delivery may report the unavailable result before the request is
  // canceled. Clear that already-delivered record so the post-resignation pump
  // specifically checks for stale callback delivery.
  requester.recorder().clearOwnershipRecords();
  requester.resign(rti::CANCEL_PENDING_OWNERSHIP_ACQUISITIONS);
  for (int pass = 0; pass != 8; ++pass) {
    requester.pump();
  }
  require(
      !requester.recorder().ownershipUnavailable().has_value() &&
          !requester.recorder().ownershipAcquisition().has_value(),
      "canceling pending If Available acquisition delivered a stale callback");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
      "canceling pending If Available acquisition changed the current owner");

  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioResignCancelIfAvailablePendingContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignCancelIfAvailablePending(options, model);
}

void scenarioResignCancelNegotiatedPending(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "resign-cancel-negotiated-owner");
  Session requester(options, model, "resign-cancel-negotiated-requester");
  auto const federation = federationName(
      options,
      "resign-cancel-negotiated-pending");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Negotiated resignation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Negotiated resignation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "negotiated resignation discovery");

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const acquisitionTagBytes{0xe6U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0xe7U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "evoked negotiated resignation crossed the callback boundary before resignation");
  }
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "negotiated resignation changed ownership before cancellation");

  // Immediate delivery may already have reported the negotiated request. Clear
  // that state so the post-resignation pump specifically checks for stale owner
  // callbacks after the requester has left the federation.
  owner.recorder().clearOwnershipRecords();
  requester.resign(rti::CANCEL_PENDING_OWNERSHIP_ACQUISITIONS);
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  require(
      !owner.recorder().divestitureConfirmation().has_value() &&
          !owner.recorder().ownershipReleaseRequest().has_value(),
      "canceling pending negotiated acquisition delivered a stale owner callback");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
      "canceling pending negotiated acquisition changed the current owner");

  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioResignCancelNegotiatedPendingContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignCancelNegotiatedPending(options, model);
}







void scenarioAutoProvide(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.autoProvideFom.empty(),
      "Auto Provide testing requires an adapter-supplied Auto Provide FOM");
  Session owner(options, model, "owner");
  Session requester(options, model, "requester");
  auto const federation = federationName(options, "auto-provide");
  connectAndJoin(owner, requester, options, federation, options.autoProvideFom);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.autoProvideObjectClassName);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.autoProvideObjectClassName);
  auto const ownerFirst = owner.rtiAmbassador().getAttributeHandle(
      ownerClass, options.autoProvideFirstAttributeName);
  auto const ownerSecond = owner.rtiAmbassador().getAttributeHandle(
      ownerClass, options.autoProvideSecondAttributeName);
  auto const requesterFirst = requester.rtiAmbassador().getAttributeHandle(
      requesterClass, options.autoProvideFirstAttributeName);
  auto const requesterSecond = requester.rtiAmbassador().getAttributeHandle(
      requesterClass, options.autoProvideSecondAttributeName);
  require(
      ownerClass.isValid() && requesterClass.isValid() && ownerFirst.isValid() &&
          ownerSecond.isValid() && requesterFirst.isValid() && requesterSecond.isValid(),
      "Auto Provide handle lookup returned an invalid handle");
  require(
      owner.rtiAmbassador().getAutoProvideSwitch() &&
          requester.rtiAmbassador().getAutoProvideSwitch(),
      "Auto Provide FOM did not enable the standard Auto Provide switch");

  rti::AttributeHandleSet ownerAttributes{ownerFirst, ownerSecond};
  rti::AttributeHandleSet requesterAttributes{requesterFirst, requesterSecond};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass, requesterAttributes, true, L"");
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Auto Provide registration returned an invalid object handle");

  waitFor(
      owner,
      requester,
      [&] {
        return owner.recorder().providedUpdates().size() >= 1U &&
            requester.recorder().discovery().present;
      },
      options,
      "Auto Provide discovery and solicitation");
  auto const providedUpdates = owner.recorder().providedUpdates();
  require(
      providedUpdates.size() == 1U,
      "Auto Provide solicited more than one provider callback");
  auto const& provided = providedUpdates.front();
  require(
      provided.object == object && provided.attributes == ownerAttributes &&
          provided.tag.empty(),
      "Auto Provide callback returned the wrong object, attributes, or tag");
  auto const discovery = requester.recorder().discovery();
  require(
      discovery.object == object && discovery.objectClass == requesterClass,
      "Auto Provide discovery returned the wrong object or object class");

  requester.rtiAmbassador().unsubscribeObjectClassAttributes(
      requesterClass, requesterAttributes);
  requester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioAutoProvideContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioAutoProvide(options, model);
}




void scenarioAttributeScopeAdvisories(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session member(options, model, "member");
  auto const federation = federationName(options, "attribute-scope-advisories");
  connectAndJoin(owner, member, options, federation, options.ddmFom);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const memberHandles = ddmHandles(member, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "attribute scope advisories");
  verifyDdmClassDimensions(member, options, memberHandles, "attribute scope advisories member");

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  rti::AttributeHandleSet const memberAttributes{memberHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);

  auto const sourceRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 1UL, 5UL);
  auto const alternateSourceRegion =
      createDdmRegion(owner, ownerHandles, 7UL, 9UL, 7UL, 9UL);
  auto const memberRegion = createDdmRegion(member, memberHandles, 2UL, 6UL, 2UL, 6UL);

  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
      ownerAttributes,
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const alternateSourcePair{{
      ownerAttributes,
      rti::RegionHandleSet{alternateSourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const memberPair{{
      memberAttributes,
      rti::RegionHandleSet{memberRegion},
  }};

  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(false);
  require(!member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not turn off");
  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(true);
  require(member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not turn on");
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");

  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass, sourcePair);
  require(object.isValid(), "attribute scope advisory registration returned an invalid object");
  waitFor(member,
          [&] { return member.recorder().hasDiscovery(object); },
          options,
          "attribute scope advisory discovery");

  auto drainMember = [&] {
    if (model == rti::HLA_EVOKED) {
      while (member.evokeMultipleCallbacks(0.0, 0.0)) {
      }
    }
  };
  auto requireSingleScopeReport = [&](std::vector<ScopeAdvisoryRecord> const& reports,
                                      std::string const& description) {
    require(reports.size() == 1U, description + " returned an unexpected callback count");
    require(reports.front().object == object &&
                reports.front().attributes == memberAttributes,
            description + " returned the wrong object or attributes");
  };

  // Registration may establish the initial in-scope state. Drain and clear
  // that initial state so the transitions below each have one explicit cause.
  drainMember();
  member.recorder().clearScopeAdvisories();

  // Moving the registered object's source region out of overlap produces one
  // grouped Out Of Scope callback for the subscribed attribute.
  owner.rtiAmbassador().associateRegionsForUpdates(object, alternateSourcePair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "attribute out-of-scope advisory");
  requireSingleScopeReport(
      member.recorder().attributesOutOfScope(),
      "attribute out-of-scope advisory");
  require(member.recorder().attributesInScope().empty(),
          "source-region reassociation also produced an unexpected in-scope advisory");
  member.recorder().clearScopeAdvisories();

  // Restoring source-region overlap produces the inverse transition.
  owner.rtiAmbassador().associateRegionsForUpdates(object, sourcePair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, alternateSourcePair);
  waitFor(member,
          [&] { return !member.recorder().attributesInScope().empty(); },
          options,
          "attribute in-scope advisory");
  requireSingleScopeReport(member.recorder().attributesInScope(),
                           "attribute in-scope advisory");
  require(member.recorder().attributesOutOfScope().empty(),
          "source-region reassociation also produced an unexpected out-of-scope advisory");
  member.recorder().clearScopeAdvisories();

  // Removing and restoring the regional subscription are independently
  // observable scope transitions for an already-known object.
  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "regional subscription out-of-scope advisory");
  requireSingleScopeReport(member.recorder().attributesOutOfScope(),
                           "regional subscription out-of-scope advisory");
  member.recorder().clearScopeAdvisories();
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");
  waitFor(member,
          [&] { return !member.recorder().attributesInScope().empty(); },
          options,
          "regional subscription in-scope advisory");
  requireSingleScopeReport(member.recorder().attributesInScope(),
                           "regional subscription in-scope advisory");
  member.recorder().clearScopeAdvisories();
  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "second regional subscription out-of-scope advisory");
  requireSingleScopeReport(member.recorder().attributesOutOfScope(),
                           "second regional subscription out-of-scope advisory");
  member.recorder().clearScopeAdvisories();

  // The per-federate switch suppresses both directions. Re-enabling it makes
  // a fresh subscription transition observable again.
  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(false);
  require(!member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not remain disabled");
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");
  drainMember();
  require(member.recorder().attributesInScope().empty() &&
              member.recorder().attributesOutOfScope().empty(),
          "disabled attribute scope advisory switch did not suppress an in-scope transition");
  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  drainMember();
  require(member.recorder().attributesInScope().empty() &&
              member.recorder().attributesOutOfScope().empty(),
          "disabled attribute scope advisory switch did not suppress an out-of-scope transition");
  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(true);
  require(member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not restore its enabled state");
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");

  // In evoked mode, make the queued In callback stale before servicing it.
  // The current committed region is then disjoint, so only the valid Out
  // transition may be delivered. Immediate mode observes both synchronously.
  if (model == rti::HLA_IMMEDIATE) {
    requireSingleScopeReport(member.recorder().attributesInScope(),
                             "re-enabled regional subscription in-scope advisory");
    member.recorder().clearScopeAdvisories();
  }
  member.rtiAmbassador().setRangeBounds(
      memberRegion,
      memberHandles.firstDimension,
      rti::RangeBounds(7UL, 9UL));
  member.rtiAmbassador().setRangeBounds(
      memberRegion,
      memberHandles.secondDimension,
      rti::RangeBounds(7UL, 9UL));
  member.rtiAmbassador().commitRegionModifications(rti::RegionHandleSet{memberRegion});
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "region-change out-of-scope advisory");
  requireSingleScopeReport(member.recorder().attributesOutOfScope(),
                           "region-change out-of-scope advisory");
  if (model == rti::HLA_EVOKED) {
    require(member.recorder().attributesInScope().empty(),
            "evoked delivery did not suppress the stale in-scope advisory");
  }

  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);
  owner.rtiAmbassador().deleteRegion(sourceRegion);
  owner.rtiAmbassador().deleteRegion(alternateSourceRegion);
  member.rtiAmbassador().deleteRegion(memberRegion);

  owner.resign(rti::DELETE_OBJECTS);
  member.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  member.disconnect();
}

void scenarioAttributeScopeAdvisoriesContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioAttributeScopeAdvisories(options, model);
}

void scenarioRegionalDeclarationRelevanceAdvisories(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional declaration-relevance testing requires an adapter-supplied DDM FOM");

  Session publisher(options, model, "regional-relevance-publisher");
  Session subscriber(options, model, "regional-relevance-subscriber");
  auto const federation = federationName(options, "regional-declaration-relevance");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "regional declaration-relevance publisher");
  verifyDdmClassDimensions(
      subscriber,
      options,
      subscriberHandles,
      "regional declaration-relevance subscriber");

  publisher.rtiAmbassador().setObjectClassRelevanceAdvisorySwitch(true);
  publisher.rtiAmbassador().setInteractionRelevanceAdvisorySwitch(true);
  require(
      publisher.rtiAmbassador().getObjectClassRelevanceAdvisorySwitch() &&
          publisher.rtiAmbassador().getInteractionRelevanceAdvisorySwitch(),
      "regional declaration-relevance advisory switches did not enable");
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);

  auto const objectRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const objectSubscription{{
      rti::AttributeHandleSet{subscriberHandles.attribute},
      rti::RegionHandleSet{objectRegion},
  }};

  publisher.recorder().clearAdvisories();
  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      objectSubscription,
      false);
  require(
      publisher.recorder().registrationStarts().empty(),
      "passive regional object subscription changed registration relevance");

  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      objectSubscription,
      true);
  waitFor(
      publisher,
      [&] { return publisher.recorder().registrationStarts().size() >= 1U; },
      options,
      "regional object start-registration advisory");
  require(
      publisher.recorder().registrationStarts().size() == 1U &&
          publisher.recorder().registrationStarts().front() ==
              publisherHandles.objectClass,
      "active regional object subscription returned the wrong start-registration advisory");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      objectSubscription);
  waitFor(
      publisher,
      [&] { return publisher.recorder().registrationStops().size() >= 1U; },
      options,
      "regional object stop-registration advisory");
  require(
      publisher.recorder().registrationStops().size() == 1U &&
          publisher.recorder().registrationStops().front() ==
              publisherHandles.objectClass,
      "regional object unsubscription returned the wrong stop-registration advisory");

  publisher.recorder().clearAdvisories();
  auto const interactionRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const interactionRegionSet = rti::RegionHandleSet{interactionRegion};
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      interactionRegionSet,
      false);
  require(
      publisher.recorder().interactionsOn().empty(),
      "passive regional interaction subscription changed interaction relevance");

  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      interactionRegionSet,
      true);
  waitFor(
      publisher,
      [&] { return publisher.recorder().interactionsOn().size() >= 1U; },
      options,
      "regional interaction turn-on advisory");
  require(
      publisher.recorder().interactionsOn().size() == 1U &&
          publisher.recorder().interactionsOn().front() ==
              publisherHandles.interactionClass,
      "active regional interaction subscription returned the wrong turn-on advisory");

  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      interactionRegionSet);
  waitFor(
      publisher,
      [&] { return publisher.recorder().interactionsOff().size() >= 1U; },
      options,
      "regional interaction turn-off advisory");
  require(
      publisher.recorder().interactionsOff().size() == 1U &&
          publisher.recorder().interactionsOff().front() ==
              publisherHandles.interactionClass,
      "regional interaction unsubscription returned the wrong turn-off advisory");

  subscriber.rtiAmbassador().deleteRegion(interactionRegion);
  subscriber.rtiAmbassador().deleteRegion(objectRegion);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});
  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  subscriber.disconnect();
}

void scenarioRegionalDeclarationRelevanceAdvisoriesContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalDeclarationRelevanceAdvisories(options, model);
}

void scenarioRegionalInteractionRouting(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session overlap(options, model, "member");
  Session disjoint(options, model, "passive");
  auto const federation = federationName(options, "regional-interaction-routing");
  connectAndJoin(owner, overlap, options, federation, options.ddmFom);
  disjoint.connect();
  disjoint.join(
      options.memberFederateName + L"-regional-interaction-disjoint",
      options.federateType,
      federation);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const overlapHandles = ddmHandles(overlap, options);
  auto const disjointHandles = ddmHandles(disjoint, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "regional interaction routing");

  owner.rtiAmbassador().publishInteractionClass(ownerHandles.interactionClass);
  auto const sourceRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 1UL, 5UL);
  auto const overlapRegion =
      createDdmRegion(overlap, overlapHandles, 2UL, 6UL, 2UL, 6UL);
  auto const disjointRegion =
      createDdmRegion(disjoint, disjointHandles, 7UL, 9UL, 7UL, 9UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const overlapRegionSet = rti::RegionHandleSet{overlapRegion};
  auto const disjointRegionSet = rti::RegionHandleSet{disjointRegion};

  auto verifyTransportation = [&](Session& receiver,
                                  rti::TransportationTypeHandle const& transportation,
                                  std::string const& description) {
    require(transportation.isValid(), description + " returned an invalid transportation handle");
    if (options.requireCustomTransportation) {
      require(
          receiver.rtiAmbassador().getTransportationTypeName(transportation) ==
              options.fomCustomTransportationName,
          description + " changed the adapter-declared custom transport");
    }
  };
  overlap.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  disjoint.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  overlap.rtiAmbassador().subscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet, true);
  disjoint.rtiAmbassador().subscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet, true);

  std::vector<std::uint8_t> firstValue{0x61U, 0x62U, 0x63U};
  std::vector<std::uint8_t> firstTag{0x49U, 0x31U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(firstValue.data(), firstValue.size()));
  rti::VariableLengthData firstUserTag(firstTag.data(), firstTag.size());
  owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      firstParameters,
      sourceRegionSet,
      firstUserTag);
  waitFor(
      overlap,
      [&] { return overlap.recorder().interaction().present; },
      options,
      "regional ordinary interaction delivery");
  auto const firstInteraction = overlap.recorder().interaction();
  require(firstInteraction.interaction == overlapHandles.interactionClass &&
              firstInteraction.parameters.size() == 1U &&
              firstInteraction.parameters.count(overlapHandles.parameter) == 1U,
          "regional interaction returned the wrong class or parameter set");
  require(copyBytes(firstInteraction.parameters.at(overlapHandles.parameter)) == firstValue,
          "regional interaction returned the wrong parameter value");
  require(firstInteraction.tag == firstTag &&
              firstInteraction.producer == owner.federateHandle() &&
              firstInteraction.transportation.isValid(),
          "regional interaction did not preserve ordinary metadata");
  verifyTransportation(
      overlap,
      firstInteraction.transportation,
      "regional interaction");
  require(firstInteraction.regions.has_value() &&
              firstInteraction.regions->size() == 1U &&
              firstInteraction.regions->count(sourceRegion) == 1U,
          "regional interaction did not convey the source region designator set");
  for (int pass = 0; pass != 8; ++pass) {
    disjoint.pump();
  }
  require(!disjoint.recorder().interaction().present,
          "disjoint regional interaction subscription received the interaction");

  overlap.recorder().clearInteraction();
  overlap.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet);
  owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      firstParameters,
      sourceRegionSet,
      firstUserTag);
  for (int pass = 0; pass != 8; ++pass) {
    overlap.pump();
  }
  require(!overlap.recorder().interaction().present,
          "unsubscribed regional interaction receiver received a message");

  overlap.rtiAmbassador().subscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet, true);
  std::vector<std::uint8_t> secondValue{0x71U, 0x72U};
  std::vector<std::uint8_t> secondTag{0x49U, 0x32U};
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(secondValue.data(), secondValue.size()));
  rti::VariableLengthData secondUserTag(secondTag.data(), secondTag.size());
  owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      secondParameters,
      sourceRegionSet,
      secondUserTag);
  waitFor(
      overlap,
      [&] { return overlap.recorder().interaction().present; },
      options,
      "regional interaction delivery after resubscription");
  auto const secondInteraction = overlap.recorder().interaction();
  require(copyBytes(secondInteraction.parameters.at(overlapHandles.parameter)) == secondValue &&
              secondInteraction.tag == secondTag,
          "regional interaction resubscription returned stale data");
  verifyTransportation(
      overlap,
      secondInteraction.transportation,
      "regional interaction resubscription");

  overlap.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet);
  disjoint.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet);
  owner.rtiAmbassador().unpublishInteractionClass(ownerHandles.interactionClass);
  owner.rtiAmbassador().deleteRegion(sourceRegion);
  overlap.rtiAmbassador().deleteRegion(overlapRegion);
  disjoint.rtiAmbassador().deleteRegion(disjointRegion);

  owner.resign(rti::NO_ACTION);
  overlap.resign(rti::NO_ACTION);
  disjoint.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  overlap.disconnect();
  disjoint.disconnect();
}

void scenarioRegionalInteractionRoutingContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalInteractionRouting(options, model);
}

void scenarioDefaultRegionInteractionRouting(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Default-region interaction routing requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "default-region-interaction-publisher");
  Session regional(options, model, "default-region-interaction-regional");
  Session mixed(options, model, "default-region-interaction-mixed");
  auto const federation = federationName(options, "default-region-interaction-routing");
  connectAndJoin(publisher, regional, options, federation, options.ddmFom);
  mixed.connect();
  mixed.join(
      options.memberFederateName + L"-default-region-interaction-mixed",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const regionalHandles = ddmHandles(regional, options);
  auto const mixedHandles = ddmHandles(mixed, options);
  require(
      publisherHandles.interactionClass == regionalHandles.interactionClass &&
          publisherHandles.interactionClass == mixedHandles.interactionClass &&
          publisherHandles.parameter == regionalHandles.parameter &&
          publisherHandles.parameter == mixedHandles.parameter,
      "default-region interaction members resolved different declaration handles");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const regionalRegion = createDdmRegion(
      regional,
      regionalHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const mixedRegion = createDdmRegion(
      mixed,
      mixedHandles,
      2UL,
      3UL,
      2UL,
      3UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const regionalRegionSet = rti::RegionHandleSet{regionalRegion};
  auto const mixedRegionSet = rti::RegionHandleSet{mixedRegion};

  regional.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  mixed.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  regional.rtiAmbassador().subscribeInteractionClassWithRegions(
      regionalHandles.interactionClass,
      regionalRegionSet,
      true);
  mixed.rtiAmbassador().subscribeInteractionClass(
      mixedHandles.interactionClass,
      true);
  mixed.rtiAmbassador().subscribeInteractionClassWithRegions(
      mixedHandles.interactionClass,
      mixedRegionSet,
      true);

  std::vector<std::uint8_t> firstValue{0xd1U, 0x04U};
  std::vector<std::uint8_t> firstTag{0x01U, 0x02U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(firstValue.data(), firstValue.size()));
  rti::VariableLengthData firstUserTag(firstTag.data(), firstTag.size());

  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      firstUserTag);
  waitFor(
      regional,
      [&] { return regional.recorder().interactions().size() >= 1U; },
      options,
      "default-region interaction overlap delivery");
  auto const firstRegionalInteractions = regional.recorder().interactions();
  require(
      firstRegionalInteractions.size() == 1U,
      "default-region interaction overlap delivered a duplicate callback");
  auto const& firstRegional = firstRegionalInteractions.front();
  require(
      firstRegional.interaction == regionalHandles.interactionClass &&
          firstRegional.parameters.size() == 1U &&
          firstRegional.parameters.count(regionalHandles.parameter) == 1U &&
          copyBytes(firstRegional.parameters.at(regionalHandles.parameter)) == firstValue &&
          firstRegional.tag == firstTag &&
          firstRegional.producer == publisher.federateHandle() &&
          firstRegional.transportation.isValid(),
      "default-region interaction overlap changed ordinary delivery metadata");
  require(
      firstRegional.regions.has_value() &&
          firstRegional.regions->size() == 1U &&
          firstRegional.regions->count(sourceRegion) == 1U,
      "default-region interaction overlap did not convey the source region");
  for (int pass = 0; pass != 8; ++pass) {
    mixed.pump();
  }
  require(
      mixed.recorder().interactions().empty(),
      "disjoint explicit regional interaction subscription received a message");

  mixed.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      mixedHandles.interactionClass,
      mixedRegionSet);
  std::vector<std::uint8_t> secondValue{0x71U, 0x72U};
  std::vector<std::uint8_t> secondTag{0x03U, 0x04U};
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(secondValue.data(), secondValue.size()));
  rti::VariableLengthData secondUserTag(secondTag.data(), secondTag.size());
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      secondParameters,
      sourceRegionSet,
      secondUserTag);
  waitFor(
      regional,
      mixed,
      [&] {
        return regional.recorder().interactions().size() >= 2U &&
            mixed.recorder().interactions().size() >= 1U;
      },
      options,
      "default-region interaction restoration after regional unsubscription");
  auto const secondRegionalInteractions = regional.recorder().interactions();
  auto const secondMixedInteractions = mixed.recorder().interactions();
  require(
      secondRegionalInteractions.size() == 2U &&
          secondMixedInteractions.size() == 1U,
      "default-region interaction restoration delivered an unexpected callback count");
  auto const& secondMixed = secondMixedInteractions.front();
  require(
      secondMixed.interaction == mixedHandles.interactionClass &&
          secondMixed.parameters.size() == 1U &&
          secondMixed.parameters.count(mixedHandles.parameter) == 1U &&
          copyBytes(secondMixed.parameters.at(mixedHandles.parameter)) == secondValue &&
          secondMixed.tag == secondTag &&
          secondMixed.producer == publisher.federateHandle() &&
          secondMixed.transportation.isValid(),
      "default-region interaction restoration changed ordinary delivery metadata");

  mixed.rtiAmbassador().subscribeInteractionClassWithRegions(
      mixedHandles.interactionClass,
      mixedRegionSet,
      true);
  std::vector<std::uint8_t> thirdValue{0x05U, 0x06U};
  std::vector<std::uint8_t> thirdTag{0x07U, 0x08U};
  rti::ParameterHandleValueMap thirdParameters;
  thirdParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(thirdValue.data(), thirdValue.size()));
  rti::VariableLengthData thirdUserTag(thirdTag.data(), thirdTag.size());
  publisher.rtiAmbassador().sendInteraction(
      publisherHandles.interactionClass,
      thirdParameters,
      thirdUserTag);
  waitFor(
      regional,
      mixed,
      [&] {
        return regional.recorder().interactions().size() >= 3U &&
            mixed.recorder().interactions().size() >= 2U;
      },
      options,
      "default-region interaction ordinary send delivery");
  auto const thirdRegionalInteractions = regional.recorder().interactions();
  auto const thirdMixedInteractions = mixed.recorder().interactions();
  require(
      thirdRegionalInteractions.size() == 3U && thirdMixedInteractions.size() == 2U,
      "default-region interaction ordinary send delivered an unexpected callback count");
  auto const& thirdRegional = thirdRegionalInteractions.back();
  auto const& thirdMixed = thirdMixedInteractions.back();
  require(
      copyBytes(thirdRegional.parameters.at(regionalHandles.parameter)) == thirdValue &&
          thirdRegional.tag == thirdTag &&
          copyBytes(thirdMixed.parameters.at(mixedHandles.parameter)) == thirdValue &&
          thirdMixed.tag == thirdTag,
      "default-region interaction ordinary send changed payload or tag");
  require(
      thirdRegional.regions.has_value() && thirdRegional.regions->empty() &&
          thirdMixed.regions.has_value() && thirdMixed.regions->empty(),
      "default-region interaction ordinary send did not convey an empty source region");

  mixed.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      mixedHandles.interactionClass,
      mixedRegionSet);
  mixed.rtiAmbassador().unsubscribeInteractionClass(mixedHandles.interactionClass);
  regional.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      regionalHandles.interactionClass,
      regionalRegionSet);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  regional.rtiAmbassador().deleteRegion(regionalRegion);
  mixed.rtiAmbassador().deleteRegion(mixedRegion);
  mixed.resign(rti::NO_ACTION);
  regional.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  mixed.disconnect();
  regional.disconnect();
  publisher.disconnect();
}

void scenarioDefaultRegionInteractionRoutingContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioDefaultRegionInteractionRouting(options, model);
}

void scenarioZeroDimensionalRegionalInteraction(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Zero-dimensional regional interaction requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "zero-dimensional-regional-interaction-publisher");
  Session subscriber(options, model, "zero-dimensional-regional-interaction-subscriber");
  auto const federation = federationName(
      options,
      "zero-dimensional-regional-interaction");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "zero-dimensional regional interaction");
  require(
      publisherHandles.interactionClass == subscriberHandles.interactionClass &&
          publisherHandles.parameter == subscriberHandles.parameter,
      "zero-dimensional interaction members resolved different declaration handles");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  subscriber.rtiAmbassador().subscribeInteractionClass(
      subscriberHandles.interactionClass,
      true);

  std::vector<std::uint8_t> ordinaryValue{0x2aU, 0x15U};
  std::vector<std::uint8_t> ordinaryTag{0x7aU, 0x64U, 0x6dU};
  rti::ParameterHandleValueMap ordinaryParameters;
  ordinaryParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(ordinaryValue.data(), ordinaryValue.size()));
  rti::VariableLengthData ordinaryUserTag(
      ordinaryTag.data(),
      ordinaryTag.size());

  publisher.rtiAmbassador().sendInteraction(
      publisherHandles.interactionClass,
      ordinaryParameters,
      ordinaryUserTag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interactions().size() >= 1U; },
      options,
      "zero-dimensional interaction ordinary baseline");
  auto const ordinaryInteractions = subscriber.recorder().interactions();
  require(
      ordinaryInteractions.size() == 1U,
      "ordinary interaction baseline delivered a duplicate callback");
  auto const& ordinary = ordinaryInteractions.front();
  require(
      ordinary.interaction == subscriberHandles.interactionClass &&
          ordinary.parameters.size() == 1U &&
          ordinary.parameters.count(subscriberHandles.parameter) == 1U &&
          copyBytes(ordinary.parameters.at(subscriberHandles.parameter)) == ordinaryValue &&
          ordinary.tag == ordinaryTag &&
          ordinary.producer == publisher.federateHandle() &&
          ordinary.transportation.isValid() &&
          !ordinary.regions.has_value(),
      "ordinary interaction baseline changed delivery metadata");

  auto const zeroRegion = publisher.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{});
  require(
      zeroRegion.isValid(),
      "zero-dimensional interaction region creation returned an invalid handle");
  require(
      publisher.rtiAmbassador().getDimensionHandleSet(zeroRegion).empty(),
      "zero-dimensional interaction region reported unexpected dimensions");
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{zeroRegion});
  require(
      publisher.rtiAmbassador().getDimensionHandleSet(zeroRegion).empty(),
      "zero-dimensional interaction region changed dimensions after commit");

  subscriber.recorder().clearInteraction();
  std::vector<std::uint8_t> explicitValue{0x2aU, 0x15U};
  std::vector<std::uint8_t> explicitTag{0x7aU, 0x64U, 0x6dU};
  rti::ParameterHandleValueMap explicitParameters;
  explicitParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(explicitValue.data(), explicitValue.size()));
  rti::VariableLengthData explicitUserTag(
      explicitTag.data(),
      explicitTag.size());
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      explicitParameters,
      rti::RegionHandleSet{zeroRegion},
      explicitUserTag);
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      subscriber.recorder().interactions().empty(),
      "explicit zero-dimensional interaction realization overlapped the default region");

  publisher.rtiAmbassador().deleteRegion(zeroRegion);
  subscriber.rtiAmbassador().unsubscribeInteractionClass(
      subscriberHandles.interactionClass);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  subscriber.disconnect();
  publisher.disconnect();
}

void scenarioZeroDimensionalRegionalInteractionContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioZeroDimensionalRegionalInteraction(options, model);
}

void scenarioMultiRegionInteractionRouting(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Multi-region interaction routing requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session first(options, model, "member");
  Session second(options, model, "member");
  Session combined(options, model, "member");
  Session disjoint(options, model, "member");
  auto const federation = federationName(
      options,
      "multi-region-interaction-routing");
  connectAndJoin(publisher, first, options, federation, options.ddmFom);
  second.connect();
  second.join(
      options.memberFederateName + L"-multi-region-interaction-second",
      options.federateType,
      federation);
  combined.connect();
  combined.join(
      options.memberFederateName + L"-multi-region-interaction-combined",
      options.federateType,
      federation);
  disjoint.connect();
  disjoint.join(
      options.memberFederateName + L"-multi-region-interaction-disjoint",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const firstHandles = ddmHandles(first, options);
  auto const secondHandles = ddmHandles(second, options);
  auto const combinedHandles = ddmHandles(combined, options);
  auto const disjointHandles = ddmHandles(disjoint, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "multi-region interaction routing");
  require(
      publisherHandles.interactionClass == firstHandles.interactionClass &&
          publisherHandles.interactionClass == secondHandles.interactionClass &&
          publisherHandles.interactionClass == combinedHandles.interactionClass &&
          publisherHandles.interactionClass == disjointHandles.interactionClass &&
          publisherHandles.parameter == firstHandles.parameter &&
          publisherHandles.parameter == secondHandles.parameter &&
          publisherHandles.parameter == combinedHandles.parameter &&
          publisherHandles.parameter == disjointHandles.parameter,
      "multi-region interaction members resolved different declaration handles");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  auto const sourceFirst = createDdmRegion(
      publisher,
      publisherHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const sourceSecond = createDdmRegion(
      publisher,
      publisherHandles,
      5UL,
      7UL,
      5UL,
      7UL);
  auto const firstRegion = createDdmRegion(
      first,
      firstHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const secondRegion = createDdmRegion(
      second,
      secondHandles,
      5UL,
      7UL,
      5UL,
      7UL);
  auto const combinedFirstRegion = createDdmRegion(
      combined,
      combinedHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const combinedSecondRegion = createDdmRegion(
      combined,
      combinedHandles,
      5UL,
      7UL,
      5UL,
      7UL);
  auto const disjointRegion = createDdmRegion(
      disjoint,
      disjointHandles,
      8UL,
      9UL,
      8UL,
      9UL);

  rti::RegionHandleSet const bothSources{sourceFirst, sourceSecond};
  rti::RegionHandleSet const firstSource{sourceFirst};
  rti::RegionHandleSet const secondSource{sourceSecond};
  rti::RegionHandleSet const firstSubscription{firstRegion};
  rti::RegionHandleSet const secondSubscription{secondRegion};
  rti::RegionHandleSet const combinedSubscription{
      combinedFirstRegion,
      combinedSecondRegion};
  rti::RegionHandleSet const disjointSubscription{disjointRegion};

  first.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  second.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  combined.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  disjoint.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  first.rtiAmbassador().subscribeInteractionClassWithRegions(
      firstHandles.interactionClass,
      firstSubscription,
      true);
  second.rtiAmbassador().subscribeInteractionClassWithRegions(
      secondHandles.interactionClass,
      secondSubscription,
      true);
  combined.rtiAmbassador().subscribeInteractionClassWithRegions(
      combinedHandles.interactionClass,
      combinedSubscription,
      true);
  disjoint.rtiAmbassador().subscribeInteractionClassWithRegions(
      disjointHandles.interactionClass,
      disjointSubscription,
      true);

  auto const recipients = std::vector<Session*>{
      &first,
      &second,
      &combined,
      &disjoint};
  auto send = [&](rti::RegionHandleSet const& regions,
                  std::vector<std::uint8_t> const& value,
                  std::vector<std::uint8_t> const& tag) {
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherHandles.parameter,
        rti::VariableLengthData(value.data(), value.size()));
    rti::VariableLengthData userTag(tag.data(), tag.size());
    publisher.rtiAmbassador().sendInteractionWithRegions(
        publisherHandles.interactionClass,
        parameters,
        regions,
        userTag);
  };
  auto verify = [&](Session& receiver,
                    DdmHandles const& receiverHandles,
                    std::size_t index,
                    std::vector<std::uint8_t> const& value,
                    std::vector<std::uint8_t> const& tag,
                    rti::RegionHandleSet const& regions,
                    std::string const& description) {
    auto const records = receiver.recorder().interactions();
    require(
        records.size() > index,
        description + " did not produce the expected callback");
    auto const& record = records.at(index);
    require(
        record.interaction == receiverHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(receiverHandles.parameter) == 1U &&
            copyBytes(record.parameters.at(receiverHandles.parameter)) == value &&
            record.tag == tag &&
            record.producer == publisher.federateHandle() &&
            record.transportation.isValid(),
        description + " changed interaction delivery metadata");
    require(
        record.regions.has_value() && record.regions->size() == regions.size(),
        description + " did not convey the complete source-region set");
    for (auto const& region : regions) {
      require(
          record.regions->count(region) == 1U,
          description + " omitted a sent source region");
    }
  };

  std::vector<std::uint8_t> bothValue{0x61U, 0x62U, 0x63U};
  std::vector<std::uint8_t> bothTag{0x49U, 0x31U};
  send(bothSources, bothValue, bothTag);
  waitForSessions(
      recipients,
      [&] {
        return first.recorder().interactions().size() == 1U &&
            second.recorder().interactions().size() == 1U &&
            combined.recorder().interactions().size() == 1U &&
            disjoint.recorder().interactions().empty();
      },
      options,
      "multi-region interaction union delivery");
  verify(
      first,
      firstHandles,
      0U,
      bothValue,
      bothTag,
      bothSources,
      "first multi-region interaction");
  verify(
      second,
      secondHandles,
      0U,
      bothValue,
      bothTag,
      bothSources,
      "second multi-region interaction");
  verify(
      combined,
      combinedHandles,
      0U,
      bothValue,
      bothTag,
      bothSources,
      "combined multi-region interaction");

  std::vector<std::uint8_t> secondValue{0x71U, 0x72U};
  std::vector<std::uint8_t> secondTag{0x49U, 0x32U};
  send(secondSource, secondValue, secondTag);
  waitForSessions(
      recipients,
      [&] {
        return first.recorder().interactions().size() == 1U &&
            second.recorder().interactions().size() == 2U &&
            combined.recorder().interactions().size() == 2U &&
            disjoint.recorder().interactions().empty();
      },
      options,
      "multi-region interaction second-source delivery");
  verify(
      second,
      secondHandles,
      1U,
      secondValue,
      secondTag,
      secondSource,
      "second-source multi-region interaction");
  verify(
      combined,
      combinedHandles,
      1U,
      secondValue,
      secondTag,
      secondSource,
      "combined second-source interaction");

  std::vector<std::uint8_t> firstValue{0x81U, 0x82U};
  std::vector<std::uint8_t> firstTag{0x49U, 0x33U};
  send(firstSource, firstValue, firstTag);
  waitForSessions(
      recipients,
      [&] {
        return first.recorder().interactions().size() == 2U &&
            second.recorder().interactions().size() == 2U &&
            combined.recorder().interactions().size() == 3U &&
            disjoint.recorder().interactions().empty();
      },
      options,
      "multi-region interaction first-source delivery");
  verify(
      first,
      firstHandles,
      1U,
      firstValue,
      firstTag,
      firstSource,
      "first-source multi-region interaction");
  verify(
      combined,
      combinedHandles,
      2U,
      firstValue,
      firstTag,
      firstSource,
      "combined first-source interaction");

  first.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      firstHandles.interactionClass,
      firstSubscription);
  second.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      secondHandles.interactionClass,
      secondSubscription);
  combined.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      combinedHandles.interactionClass,
      combinedSubscription);
  disjoint.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      disjointHandles.interactionClass,
      disjointSubscription);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().deleteRegion(sourceFirst);
  publisher.rtiAmbassador().deleteRegion(sourceSecond);
  first.rtiAmbassador().deleteRegion(firstRegion);
  second.rtiAmbassador().deleteRegion(secondRegion);
  combined.rtiAmbassador().deleteRegion(combinedFirstRegion);
  combined.rtiAmbassador().deleteRegion(combinedSecondRegion);
  disjoint.rtiAmbassador().deleteRegion(disjointRegion);
  disjoint.resign(rti::NO_ACTION);
  combined.resign(rti::NO_ACTION);
  second.resign(rti::NO_ACTION);
  first.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  disjoint.disconnect();
  combined.disconnect();
  second.disconnect();
  first.disconnect();
  publisher.disconnect();
}

void scenarioMultiRegionInteractionRoutingContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioMultiRegionInteractionRouting(options, model);
}

void scenarioRegionalInteractionEmptySubscriptionSets(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional interaction empty subscription-set semantics require an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(
      options,
      "regional-interaction-empty-subscription-sets");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "regional interaction empty subscription sets");
  require(
      publisherHandles.interactionClass == subscriberHandles.interactionClass &&
          publisherHandles.parameter == subscriberHandles.parameter,
      "regional interaction empty subscription-set members resolved different declaration handles");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const subscriptionRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const subscriptionRegionSet = rti::RegionHandleSet{subscriptionRegion};

  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);

  std::vector<std::uint8_t> const valueBytes{0x52U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));

  auto send = [&](std::vector<std::uint8_t> const& tagBytes) {
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendInteractionWithRegions(
        publisherHandles.interactionClass,
        parameters,
        sourceRegionSet,
        tag);
  };

  auto pumpSubscriber = [&] {
    for (int pass = 0; pass != 8; ++pass) {
      subscriber.pump();
    }
  };

  auto verifyInteraction = [&](std::size_t index,
                                std::vector<std::uint8_t> const& expectedTag,
                                std::string const& description) {
    auto const records = subscriber.recorder().interactions();
    require(
        records.size() > index,
        description + " did not produce the expected callback");
    auto const& record = records.at(index);
    require(
        record.interaction == subscriberHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(subscriberHandles.parameter) == 1U &&
            copyBytes(record.parameters.at(subscriberHandles.parameter)) == valueBytes,
        description + " changed the interaction class, parameter, or value");
    require(
        record.tag == expectedTag &&
            record.producer == publisher.federateHandle() &&
            record.transportation.isValid(),
        description + " changed ordinary interaction metadata");
    require(
        record.regions.has_value() &&
            record.regions->size() == 1U &&
            record.regions->count(sourceRegion) == 1U,
        description + " did not convey the source-region designator set");
  };

  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{},
      true);
  send(std::vector<std::uint8_t>{0x45U, 0x53U, 0x55U});
  pumpSubscriber();
  require(
      subscriber.recorder().interactions().empty(),
      "an empty regional interaction subscription created an eligible route");

  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      subscriptionRegionSet,
      true);
  auto const subscribedTag = std::vector<std::uint8_t>{0x53U, 0x55U, 0x42U};
  send(subscribedTag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interactions().size() >= 1U; },
      options,
      "regional interaction delivery after non-empty subscription");
  require(
      subscriber.recorder().interactions().size() == 1U,
      "non-empty regional interaction subscription delivered a duplicate callback");
  verifyInteraction(
      0U,
      subscribedTag,
      "regional interaction delivery after non-empty subscription");

  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{});
  auto const emptyUnsubscribeTag =
      std::vector<std::uint8_t>{0x45U, 0x55U, 0x4EU};
  send(emptyUnsubscribeTag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interactions().size() >= 2U; },
      options,
      "regional interaction delivery after empty unsubscription");
  require(
      subscriber.recorder().interactions().size() == 2U,
      "empty regional interaction unsubscription changed the active route unexpectedly");
  verifyInteraction(
      1U,
      emptyUnsubscribeTag,
      "regional interaction delivery after empty unsubscription");

  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      subscriptionRegionSet);
  auto const unsubscribedTag =
      std::vector<std::uint8_t>{0x55U, 0x4EU, 0x53U};
  send(unsubscribedTag);
  pumpSubscriber();
  require(
      subscriber.recorder().interactions().size() == 2U,
      "non-empty regional interaction unsubscription failed to remove the route");

  subscriber.rtiAmbassador().deleteRegion(subscriptionRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  subscriber.disconnect();
  publisher.disconnect();
}

void scenarioRegionalInteractionEmptySubscriptionSetsContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalInteractionEmptySubscriptionSets(options, model);
}

void scenarioRegionalInteractionSourceRegionSnapshot(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional interaction source-region snapshot requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(
      options,
      "regional-interaction-source-region-snapshot");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "regional interaction source-region snapshot");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const subscriberRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const subscriberRegionSet = rti::RegionHandleSet{subscriberRegion};

  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      subscriberRegionSet,
      true);

  std::vector<std::uint8_t> const valueBytes{0x2CU, 0x01U};
  std::vector<std::uint8_t> const tagBytes{0x53U, 0x4EU, 0x50U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData const tag(tagBytes.data(), tagBytes.size());

  auto assertInteraction = [&](InteractionRecord const& record,
                               std::string const& description) {
    require(
        record.interaction == subscriberHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(subscriberHandles.parameter) == 1U &&
            copyBytes(record.parameters.at(subscriberHandles.parameter)) == valueBytes,
        description + " returned the wrong class, parameter, or value");
    require(
        record.tag == tagBytes &&
            record.producer == publisher.federateHandle() &&
            record.transportation.isValid(),
        description + " did not preserve ordinary metadata");
    require(
        record.regions.has_value() &&
            record.regions->size() == 1U &&
            record.regions->count(sourceRegion) == 1U,
        description + " did not preserve the send-time source region");
  };

  // Admission overlaps the subscriber's committed region. In evoked mode the
  // callback remains queued while the source region is changed; in immediate
  // mode delivery completes before the same mutation. Both paths must expose
  // the source-region realization captured at send time.
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag);
  if (model == rti::HLA_EVOKED) {
    require(
        !subscriber.recorder().interaction().present,
        "evoked regional interaction was delivered before callback servicing");
  }
  if (model == rti::HLA_EVOKED) {
    publisher.rtiAmbassador().setRangeBounds(
        sourceRegion,
        publisherHandles.firstDimension,
        rti::RangeBounds(16UL, 20UL));
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
  }
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction send-time source-region snapshot");
  assertInteraction(
      subscriber.recorder().interaction(),
      "regional interaction send-time source-region snapshot");

  subscriber.recorder().clearInteraction();
  if (model == rti::HLA_IMMEDIATE) {
    publisher.rtiAmbassador().setRangeBounds(
        sourceRegion,
        publisherHandles.firstDimension,
        rti::RangeBounds(16UL, 20UL));
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
  }

  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag);
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      !subscriber.recorder().interaction().present,
      "disjoint regional interaction source mutation did not suppress delivery");

  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension,
      rti::RangeBounds(0UL, 10UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceRegion});
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction delivery after source-region restoration");
  assertInteraction(
      subscriber.recorder().interaction(),
      "regional interaction delivery after source-region restoration");

  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      subscriberRegionSet);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  subscriber.rtiAmbassador().deleteRegion(subscriberRegion);

  publisher.resign(rti::NO_ACTION);
  subscriber.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  subscriber.disconnect();
}

void scenarioRegionalInteractionSourceRegionSnapshotContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalInteractionSourceRegionSnapshot(options, model);
}

void scenarioRegionalInteractionSubscriptionFiltering(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional interaction subscription filtering requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(
      options,
      "regional-interaction-subscription-filtering");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "regional interaction subscription filtering");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const subscriberRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      2UL,
      6UL,
      2UL,
      6UL);

  std::vector<std::uint8_t> const parameterBytes{0x2CU, 0x01U};
  std::vector<std::uint8_t> const tagBytes{0x7AU, 0x19U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData const tag(tagBytes.data(), tagBytes.size());

  auto assertInteraction = [&](InteractionRecord const& record, bool expectRegions) {
    require(
        record.interaction == subscriberHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(subscriberHandles.parameter) == 1U &&
            copyBytes(record.parameters.at(subscriberHandles.parameter)) == parameterBytes,
        "regional interaction filtering returned the wrong class or parameter");
    require(
        record.tag == tagBytes &&
            record.producer == publisher.federateHandle() &&
            record.transportation.isValid(),
        "regional interaction filtering did not preserve ordinary metadata");
    if (expectRegions) {
      require(
          record.regions.has_value() &&
              record.regions->size() == 1U &&
              record.regions->count(sourceRegion) == 1U,
          "regional interaction filtering did not convey the source region");
    } else {
      require(
          !record.regions.has_value(),
          "regional interaction filtering unexpectedly conveyed a source region");
    }
  };
  auto drainSubscriber = [&] {
    for (int pass = 0; pass != 8; ++pass) {
      subscriber.pump();
    }
  };

  // An ordinary declaration remains independent from an explicit regional
  // declaration, and an empty regional declaration does not create a default
  // subscription or turn an explicitly regional send into an ordinary send.
  subscriber.rtiAmbassador().subscribeInteractionClass(
      subscriberHandles.interactionClass);
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{},
      true);
  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{});
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteraction(
      publisherHandles.interactionClass,
      parameters,
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "ordinary interaction through the ordinary subscription");
  auto const ordinaryInteraction = subscriber.recorder().interaction();
  assertInteraction(ordinaryInteraction, false);

  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{},
      tag);
  drainSubscriber();
  require(
      !subscriber.recorder().interaction().present,
      "an explicitly empty regional interaction send used the ordinary subscription");

  // Removing only the ordinary declaration makes the committed regional
  // declaration the complete routing filter.
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{subscriberRegion},
      true);
  subscriber.rtiAmbassador().unsubscribeInteractionClass(
      subscriberHandles.interactionClass);
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction through the explicit subscription");
  assertInteraction(subscriber.recorder().interaction(), false);

  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      subscriber.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "regional interaction receiver did not enable region designator callbacks");
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction with conveyed source region");
  assertInteraction(subscriber.recorder().interaction(), true);

  // A queued regional interaction is rechecked against the committed
  // subscription region at callback entry. Immediate delivery completes
  // before the later region movement and therefore cannot be replayed.
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  if (model == rti::HLA_EVOKED) {
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.firstDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.secondDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{subscriberRegion});
    drainSubscriber();
    require(
        !subscriber.recorder().interaction().present,
        "evoked regional interaction ignored a moved subscription region");
  } else {
    waitFor(
        subscriber,
        [&] { return subscriber.recorder().interaction().present; },
        options,
        "immediate regional interaction delivery before region movement");
    assertInteraction(subscriber.recorder().interaction(), true);
    subscriber.recorder().clearInteraction();
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.firstDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.secondDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{subscriberRegion});
    drainSubscriber();
    require(
        !subscriber.recorder().interaction().present,
        "immediate regional interaction was replayed after region movement");
  }

  subscriber.rtiAmbassador().setRangeBounds(
      subscriberRegion,
      subscriberHandles.firstDimension,
      rti::RangeBounds(2UL, 6UL));
  subscriber.rtiAmbassador().setRangeBounds(
      subscriberRegion,
      subscriberHandles.secondDimension,
      rti::RangeBounds(2UL, 6UL));
  subscriber.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{subscriberRegion});
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction after subscription-region restoration");
  assertInteraction(subscriber.recorder().interaction(), true);

  // Standard service-boundary failures for foreign, uncommitted, and
  // incompatible regions are distinct from ordinary no-send behavior.
  requireException(
      [&] {
        publisher.rtiAmbassador().sendInteractionWithRegions(
            publisherHandles.interactionClass,
            parameters,
            rti::RegionHandleSet{subscriberRegion},
            tag);
      },
      L"RegionNotCreatedByThisFederate",
      "regional interaction send with a foreign region");
  requireException(
      [&] {
        subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
            subscriberHandles.interactionClass,
            rti::RegionHandleSet{sourceRegion},
            true);
      },
      L"RegionNotCreatedByThisFederate",
      "regional interaction subscription with a foreign region");

  auto const uncommittedRegion = subscriber.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{
          subscriberHandles.firstDimension,
          subscriberHandles.secondDimension});
  requireException(
      [&] {
        subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
            subscriberHandles.interactionClass,
            rti::RegionHandleSet{uncommittedRegion},
            true);
      },
      L"InvalidRegion",
      "regional interaction subscription with an uncommitted region");

  auto const wrongContextDimension = ddmUnrelatedDimensionHandle(subscriber, options);
  auto const wrongContextRegion = subscriber.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{wrongContextDimension});
  subscriber.rtiAmbassador().setRangeBounds(
      wrongContextRegion,
      wrongContextDimension,
      rti::RangeBounds(0UL, 1UL));
  subscriber.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{wrongContextRegion});
  requireException(
      [&] {
        subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
            subscriberHandles.interactionClass,
            rti::RegionHandleSet{wrongContextRegion},
            true);
      },
      L"InvalidRegionContext",
      "regional interaction subscription with an incompatible region context");

  auto const publisherWrongContextDimension =
      ddmUnrelatedDimensionHandle(publisher, options);
  auto const publisherWrongContextRegion = publisher.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{publisherWrongContextDimension});
  publisher.rtiAmbassador().setRangeBounds(
      publisherWrongContextRegion,
      publisherWrongContextDimension,
      rti::RangeBounds(0UL, 1UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{publisherWrongContextRegion});
  requireException(
      [&] {
        publisher.rtiAmbassador().sendInteractionWithRegions(
            publisherHandles.interactionClass,
            parameters,
            rti::RegionHandleSet{publisherWrongContextRegion},
            tag);
      },
      L"InvalidRegionContext",
      "regional interaction send with an incompatible region context");

  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{},
      tag);
  drainSubscriber();
  require(
      !subscriber.recorder().interaction().present,
      "empty regional interaction send produced a callback after filtering");

  requireException(
      [&] { subscriber.rtiAmbassador().deleteRegion(subscriberRegion); },
      L"RegionInUseForUpdateOrSubscription",
      "deletion of a region used by a regional interaction subscription");
  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{subscriberRegion});
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  subscriber.rtiAmbassador().deleteRegion(subscriberRegion);
  subscriber.rtiAmbassador().deleteRegion(uncommittedRegion);
  subscriber.rtiAmbassador().deleteRegion(wrongContextRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  publisher.rtiAmbassador().deleteRegion(publisherWrongContextRegion);

  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  subscriber.disconnect();
}

void scenarioAllowRelaxedDdm(Options const& options, rti::CallbackModel model) {
  require(!options.ddmFom.empty(),
          "Allow Relaxed DDM requires an adapter-supplied dimensional FOM");
  require(!options.switchesFom.empty(),
          "Allow Relaxed DDM requires an adapter-supplied switch-declaration FOM");

  auto modulesFor = [&](bool enabled) {
    std::vector<std::wstring> modules{options.ddmFom.wstring()};
    if (enabled) {
      modules.push_back(options.switchesFom.wstring());
    }
    return modules;
  };

  auto runObject = [&](bool enabled) {
    Session publisher(options, model, enabled ? "relaxed-object-enabled" : "relaxed-object-strict");
    Session subscriber(options, model, enabled ? "relaxed-object-member-enabled" : "relaxed-object-member-strict");
    auto const federation = federationName(
        options,
        enabled ? "allow-relaxed-ddm-object-enabled" : "allow-relaxed-ddm-object-strict");
    publisher.connect();
    subscriber.connect();
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        modulesFor(enabled),
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    subscriber.join(
        options.memberFederateName,
        options.federateType,
        federation);

    require(
        publisher.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled &&
            subscriber.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled,
        "Allow Relaxed DDM object composition did not match the adapter switch FOM");
    auto const publisherHandles = ddmHandles(publisher, options);
    auto const subscriberHandles = ddmHandles(subscriber, options);
    verifyDdmClassDimensions(
        publisher,
        options,
        publisherHandles,
        "Allow Relaxed DDM object publisher");
    publisher.rtiAmbassador().publishObjectClassAttributes(
        publisherHandles.objectClass,
        rti::AttributeHandleSet{publisherHandles.attribute});

    auto const sourceRegion = createDdmRegion(
        publisher,
        publisherHandles,
        0UL,
        2UL,
        0UL,
        2UL);
    auto const subscriptionRegion = createDdmRegion(
        subscriber,
        subscriberHandles,
        2UL,
        3UL,
        2UL,
        3UL);
    rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
        rti::AttributeHandleSet{publisherHandles.attribute},
        rti::RegionHandleSet{sourceRegion},
    }};
    rti::AttributeHandleSetRegionHandleSetPairVector const subscriptionPair{{
        rti::AttributeHandleSet{subscriberHandles.attribute},
        rti::RegionHandleSet{subscriptionRegion},
    }};
    subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
    subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
        subscriberHandles.objectClass,
        subscriptionPair,
        true,
        L"");

    auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
        publisherHandles.objectClass,
        sourcePair);
    require(object.isValid(), "Allow Relaxed DDM object registration returned an invalid handle");
    if (enabled) {
      waitFor(
          subscriber,
          [&] { return subscriber.recorder().hasDiscovery(object); },
          options,
          "Allow Relaxed DDM touching object discovery");
      auto const discovery = subscriber.recorder().discovery();
      require(
          discovery.object == object && discovery.objectClass == subscriberHandles.objectClass,
          "Allow Relaxed DDM object discovery returned the wrong identity");
    } else {
      for (int pass = 0; pass != 8; ++pass) {
        subscriber.pump();
      }
      require(
          !subscriber.recorder().discovery().present,
          "strict DDM unexpectedly discovered a touching object");
    }

    std::vector<std::uint8_t> valueBytes{0x41U, 0x52U, 0x44U};
    std::vector<std::uint8_t> tagBytes{0x4FU, 0x42U};
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherHandles.attribute,
        rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().updateAttributeValues(object, values, tag);
    if (enabled) {
      waitFor(
          subscriber,
          [&] { return subscriber.recorder().reflection().present; },
          options,
          "Allow Relaxed DDM touching object reflection");
      auto const reflection = subscriber.recorder().reflection();
      require(
          reflection.object == object && reflection.tag == tagBytes &&
              reflection.values.size() == 1U &&
              reflection.values.count(subscriberHandles.attribute) == 1U &&
              copyBytes(reflection.values.at(subscriberHandles.attribute)) == valueBytes,
          "Allow Relaxed DDM object reflection changed the delivered data");
      require(
          reflection.regions.has_value() &&
              reflection.regions->count(sourceRegion) == 1U,
          "Allow Relaxed DDM object reflection omitted the source region");
    } else {
      for (int pass = 0; pass != 8; ++pass) {
        subscriber.pump();
      }
      require(
          !subscriber.recorder().reflection().present,
          "strict DDM unexpectedly reflected a touching object update");
    }

    subscriber.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
        subscriberHandles.objectClass,
        subscriptionPair);
    publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
    subscriber.rtiAmbassador().deleteRegion(subscriptionRegion);
    publisher.rtiAmbassador().deleteRegion(sourceRegion);
    subscriber.resign(rti::NO_ACTION);
    publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    subscriber.disconnect();
    publisher.disconnect();
  };

  auto runInteraction = [&](bool enabled) {
    Session publisher(options, model, enabled ? "relaxed-interaction-enabled" : "relaxed-interaction-strict");
    Session subscriber(options, model, enabled ? "relaxed-interaction-member-enabled" : "relaxed-interaction-member-strict");
    auto const federation = federationName(
        options,
        enabled ? "allow-relaxed-ddm-interaction-enabled" : "allow-relaxed-ddm-interaction-strict");
    publisher.connect();
    subscriber.connect();
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        modulesFor(enabled),
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    subscriber.join(
        options.memberFederateName,
        options.federateType,
        federation);

    require(
        publisher.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled &&
            subscriber.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled,
        "Allow Relaxed DDM interaction composition did not match the adapter switch FOM");
    auto const publisherHandles = ddmHandles(publisher, options);
    auto const subscriberHandles = ddmHandles(subscriber, options);
    verifyDdmClassDimensions(
        publisher,
        options,
        publisherHandles,
        "Allow Relaxed DDM interaction publisher");
    publisher.rtiAmbassador().publishInteractionClass(publisherHandles.interactionClass);

    auto const sourceRegion = createDdmRegion(
        publisher,
        publisherHandles,
        0UL,
        2UL,
        0UL,
        2UL);
    auto const subscriptionRegion = createDdmRegion(
        subscriber,
        subscriberHandles,
        2UL,
        3UL,
        2UL,
        3UL);
    auto const sourceRegions = rti::RegionHandleSet{sourceRegion};
    auto const subscriptionRegions = rti::RegionHandleSet{subscriptionRegion};
    subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
    subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
        subscriberHandles.interactionClass,
        subscriptionRegions,
        true);

    std::vector<std::uint8_t> parameterBytes{0x49U, 0x4EU, 0x54U};
    std::vector<std::uint8_t> tagBytes{0x52U, 0x58U};
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherHandles.parameter,
        rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendInteractionWithRegions(
        publisherHandles.interactionClass,
        parameters,
        sourceRegions,
        tag);
    if (enabled) {
      waitFor(
          subscriber,
          [&] { return subscriber.recorder().interaction().present; },
          options,
          "Allow Relaxed DDM touching interaction delivery");
      auto const interaction = subscriber.recorder().interaction();
      require(
          interaction.interaction == subscriberHandles.interactionClass &&
              interaction.tag == tagBytes && interaction.producer == publisher.federateHandle() &&
              interaction.parameters.size() == 1U &&
              interaction.parameters.count(subscriberHandles.parameter) == 1U &&
              copyBytes(interaction.parameters.at(subscriberHandles.parameter)) == parameterBytes,
          "Allow Relaxed DDM interaction changed the delivered data");
      require(
          interaction.regions.has_value() &&
              interaction.regions->count(sourceRegion) == 1U,
          "Allow Relaxed DDM interaction omitted the source region");
    } else {
      for (int pass = 0; pass != 8; ++pass) {
        subscriber.pump();
      }
      require(
          !subscriber.recorder().interaction().present,
          "strict DDM unexpectedly delivered a touching interaction");
    }

    subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
        subscriberHandles.interactionClass,
        subscriptionRegions);
    publisher.rtiAmbassador().unpublishInteractionClass(publisherHandles.interactionClass);
    subscriber.rtiAmbassador().deleteRegion(subscriptionRegion);
    publisher.rtiAmbassador().deleteRegion(sourceRegion);
    subscriber.resign(rti::NO_ACTION);
    publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    subscriber.disconnect();
    publisher.disconnect();
  };

  runObject(false);
  runObject(true);
  runInteraction(false);
  runInteraction(true);
}

void scenarioRegionalMultiAttributeUpdate(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.multiAttributeFom.empty(),
      "Multi-attribute regional testing requires an adapter-supplied FOM");

  Session publisher(options, model, "multi-attribute-publisher");
  Session flavor(options, model, "multi-attribute-flavor");
  Session organic(options, model, "multi-attribute-organic");
  auto const federation = federationName(
      options,
      "regional-multi-attribute-update");
  publisher.connect();
  flavor.connect();
  organic.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-multi-attribute-publisher",
      options.federateType,
      federation);
  flavor.join(
      options.memberFederateName + L"-multi-attribute-flavor",
      options.federateType,
      federation);
  organic.join(
      options.memberFederateName + L"-multi-attribute-organic",
      options.federateType,
      federation);

  auto const publisherHandles = multiAttributeDdmHandles(publisher, options);
  auto const flavorHandles = multiAttributeDdmHandles(flavor, options);
  auto const organicHandles = multiAttributeDdmHandles(organic, options);
  verifyDdmObjectClassDimensions(
      publisher,
      options,
      publisherHandles.objectClass,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      "multi-attribute regional publisher");

  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{
          publisherHandles.firstAttribute,
          publisherHandles.secondAttribute});

  auto const sourceFlavor = createDdmRegionForDimensions(
      publisher,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const sourceOrganic = createDdmRegionForDimensions(
      publisher,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      5UL,
      7UL,
      5UL,
      7UL);
  auto const flavorRegion = createDdmRegionForDimensions(
      flavor,
      flavorHandles.firstDimension,
      flavorHandles.secondDimension,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const organicRegion = createDdmRegionForDimensions(
      organic,
      organicHandles.firstDimension,
      organicHandles.secondDimension,
      5UL,
      7UL,
      5UL,
      7UL);

  flavor.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  organic.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePairs{
      {rti::AttributeHandleSet{publisherHandles.firstAttribute},
       rti::RegionHandleSet{sourceFlavor}},
      {rti::AttributeHandleSet{publisherHandles.secondAttribute},
       rti::RegionHandleSet{sourceOrganic}}};
  rti::AttributeHandleSetRegionHandleSetPairVector const flavorPairs{
      {rti::AttributeHandleSet{flavorHandles.firstAttribute},
       rti::RegionHandleSet{flavorRegion}}};
  rti::AttributeHandleSetRegionHandleSetPairVector const organicPairs{
      {rti::AttributeHandleSet{organicHandles.secondAttribute},
       rti::RegionHandleSet{organicRegion}}};
  flavor.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      flavorHandles.objectClass,
      flavorPairs);
  organic.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      organicHandles.objectClass,
      organicPairs);

  auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
      publisherHandles.objectClass,
      sourcePairs);
  require(
      object.isValid(),
      "multi-attribute regional registration returned an invalid handle");
  waitFor(
      flavor,
      organic,
      [&] {
        return flavor.recorder().hasDiscovery(object) &&
            organic.recorder().hasDiscovery(object);
      },
      options,
      "multi-attribute regional object discovery");
  require(
      flavor.recorder().discovery().objectClass == flavorHandles.objectClass &&
          organic.recorder().discovery().objectClass == organicHandles.objectClass,
      "multi-attribute regional discovery returned the wrong class");

  auto sendValues = [&](std::vector<std::uint8_t> firstValue,
                        std::vector<std::uint8_t> secondValue,
                        std::vector<std::uint8_t> tag) {
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherHandles.firstAttribute,
        rti::VariableLengthData(firstValue.data(), firstValue.size()));
    values.emplace(
        publisherHandles.secondAttribute,
        rti::VariableLengthData(secondValue.data(), secondValue.size()));
    publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData(tag.data(), tag.size()));
  };

  sendValues(
      {0x46U, 0x31U},
      {0x4FU, 0x31U},
      {0x49U, 0x31U});
  waitFor(
      flavor,
      organic,
      [&] {
        return flavor.recorder().reflectionCount() >= 1U &&
            organic.recorder().reflectionCount() >= 1U;
      },
      options,
      "multi-attribute regional initial reflection");
  auto assertReflection = [&](Session& subscriber,
                              rti::AttributeHandle const& expectedAttribute,
                              rti::RegionHandle const& expectedRegion,
                              std::vector<std::uint8_t> const& expectedValue,
                              std::vector<std::uint8_t> const& expectedTag,
                              std::string const& description) {
    auto const reflection = subscriber.recorder().reflection();
    require(
        reflection.object == object &&
            reflection.values.size() == 1U &&
            reflection.values.count(expectedAttribute) == 1U &&
            copyBytes(reflection.values.at(expectedAttribute)) == expectedValue,
        description + " returned the wrong projected attribute value");
    require(
        reflection.tag == expectedTag &&
            reflection.producer == publisher.federateHandle() &&
            reflection.transportation.isValid(),
        description + " returned the wrong metadata");
    require(
        reflection.regions.has_value() &&
            reflection.regions->size() == 1U &&
            reflection.regions->count(expectedRegion) == 1U,
        description + " omitted the source region designator");
  };
  assertReflection(
      flavor,
      flavorHandles.firstAttribute,
      sourceFlavor,
      {0x46U, 0x31U},
      {0x49U, 0x31U},
      "multi-attribute regional Flavor reflection");
  assertReflection(
      organic,
      organicHandles.secondAttribute,
      sourceOrganic,
      {0x4FU, 0x31U},
      {0x49U, 0x31U},
      "multi-attribute regional Organic reflection");

  auto const flavorReflections = flavor.recorder().reflectionCount();
  auto const organicReflections = organic.recorder().reflectionCount();
  publisher.rtiAmbassador().setRangeBounds(
      sourceFlavor,
      publisherHandles.firstDimension,
      rti::RangeBounds(8UL, 9UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceFlavor});
  sendValues(
      {0x46U, 0x58U},
      {0x4FU, 0x58U},
      {0x58U, 0x31U});
  waitFor(
      organic,
      [&] { return organic.recorder().reflectionCount() > organicReflections; },
      options,
      "multi-attribute regional surviving Organic reflection");
  require(
      flavor.recorder().reflectionCount() == flavorReflections,
      "multi-attribute regional X-only source mutation leaked Flavor delivery");
  assertReflection(
      organic,
      organicHandles.secondAttribute,
      sourceOrganic,
      {0x4FU, 0x58U},
      {0x58U, 0x31U},
      "multi-attribute regional X-only Organic reflection");

  publisher.rtiAmbassador().setRangeBounds(
      sourceOrganic,
      publisherHandles.secondDimension,
      rti::RangeBounds(8UL, 9UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceOrganic});
  auto const flavorBeforeDisjoint = flavor.recorder().reflectionCount();
  auto const organicBeforeDisjoint = organic.recorder().reflectionCount();
  sendValues(
      {0x46U, 0x4EU},
      {0x4FU, 0x4EU},
      {0x4EU, 0x31U});
  for (int pass = 0; pass != 16; ++pass) {
    flavor.pump();
    organic.pump();
  }
  require(
      flavor.recorder().reflectionCount() == flavorBeforeDisjoint &&
          organic.recorder().reflectionCount() == organicBeforeDisjoint,
      "multi-attribute regional disjoint source mutation was delivered");

  publisher.rtiAmbassador().setRangeBounds(
      sourceFlavor,
      publisherHandles.firstDimension,
      rti::RangeBounds(0UL, 2UL));
  publisher.rtiAmbassador().setRangeBounds(
      sourceOrganic,
      publisherHandles.secondDimension,
      rti::RangeBounds(5UL, 7UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceFlavor, sourceOrganic});
  auto const flavorBeforeRestore = flavor.recorder().reflectionCount();
  auto const organicBeforeRestore = organic.recorder().reflectionCount();
  sendValues(
      {0x46U, 0x52U},
      {0x4FU, 0x52U},
      {0x52U, 0x31U});
  waitFor(
      flavor,
      organic,
      [&] {
        return flavor.recorder().reflectionCount() > flavorBeforeRestore &&
            organic.recorder().reflectionCount() > organicBeforeRestore;
      },
      options,
      "multi-attribute regional restored reflections");
  assertReflection(
      flavor,
      flavorHandles.firstAttribute,
      sourceFlavor,
      {0x46U, 0x52U},
      {0x52U, 0x31U},
      "multi-attribute regional restored Flavor reflection");
  assertReflection(
      organic,
      organicHandles.secondAttribute,
      sourceOrganic,
      {0x4FU, 0x52U},
      {0x52U, 0x31U},
      "multi-attribute regional restored Organic reflection");

  flavor.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      flavorHandles.objectClass,
      flavorPairs);
  organic.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      organicHandles.objectClass,
      organicPairs);
  publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePairs);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{
          publisherHandles.firstAttribute,
          publisherHandles.secondAttribute});
  flavor.rtiAmbassador().deleteRegion(flavorRegion);
  organic.rtiAmbassador().deleteRegion(organicRegion);
  publisher.rtiAmbassador().deleteRegion(sourceFlavor);
  publisher.rtiAmbassador().deleteRegion(sourceOrganic);
  flavor.resign(rti::NO_ACTION);
  organic.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  flavor.disconnect();
  organic.disconnect();
  publisher.disconnect();
}

void scenarioRegionalThreeDimensionalOverlap(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.threeDimensionalFom.empty(),
      "Three-dimensional regional testing requires an adapter-supplied FOM");

  Session publisher(options, model, "three-dimensional-publisher");
  Session subscriber(options, model, "three-dimensional-subscriber");
  auto const federation = federationName(
      options,
      "regional-three-dimensional-overlap");
  publisher.connect();
  subscriber.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.threeDimensionalFom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-three-dimensional-publisher",
      options.federateType,
      federation);
  subscriber.join(
      options.memberFederateName + L"-three-dimensional-subscriber",
      options.federateType,
      federation);

  auto const publisherHandles = threeDimensionalDdmHandles(publisher, options);
  auto const subscriberHandles = threeDimensionalDdmHandles(subscriber, options);
  verifyThreeDimensionalObjectClassDimensions(
      publisher,
      options,
      publisherHandles,
      "three-dimensional regional publisher");

  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});

  auto const sourceRegion = createDdmRegionForDimensions(
      publisher,
      publisherHandles.dimensions.at(0),
      publisherHandles.dimensions.at(1),
      publisherHandles.dimensions.at(2),
      0UL,
      5UL,
      0UL,
      2UL,
      0UL,
      1UL);
  auto const subscriberRegion = createDdmRegionForDimensions(
      subscriber,
      subscriberHandles.dimensions.at(0),
      subscriberHandles.dimensions.at(1),
      subscriberHandles.dimensions.at(2),
      0UL,
      5UL,
      0UL,
      2UL,
      0UL,
      1UL);
  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
      rti::AttributeHandleSet{publisherHandles.attribute},
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const subscriberPair{{
      rti::AttributeHandleSet{subscriberHandles.attribute},
      rti::RegionHandleSet{subscriberRegion},
  }};
  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      subscriberPair);
  auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
      publisherHandles.objectClass,
      sourcePair);
  require(
      object.isValid(),
      "three-dimensional regional registration returned an invalid handle");
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().hasDiscovery(object); },
      options,
      "three-dimensional regional object discovery");
  require(
      subscriber.recorder().discovery().objectClass ==
          subscriberHandles.objectClass,
      "three-dimensional regional discovery returned the wrong class");

  auto update = [&](std::vector<std::uint8_t> value,
                    std::vector<std::uint8_t> tag) {
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherHandles.attribute,
        rti::VariableLengthData(value.data(), value.size()));
    publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData(tag.data(), tag.size()));
  };
  auto assertReflection = [&](std::vector<std::uint8_t> const& expectedValue,
                              std::vector<std::uint8_t> const& expectedTag,
                              std::string const& description) {
    auto const reflection = subscriber.recorder().reflection();
    require(
        reflection.object == object &&
            reflection.values.size() == 1U &&
            reflection.values.count(subscriberHandles.attribute) == 1U &&
            copyBytes(reflection.values.at(subscriberHandles.attribute)) ==
                expectedValue,
        description + " returned the wrong attribute value");
    require(
        reflection.tag == expectedTag &&
            reflection.producer == publisher.federateHandle() &&
            reflection.transportation.isValid(),
        description + " returned the wrong metadata");
    require(
        reflection.regions.has_value() &&
            reflection.regions->size() == 1U &&
            reflection.regions->count(sourceRegion) == 1U,
        description + " omitted the source region designator");
  };

  update({0x10U}, {0x49U, 0x31U});
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().reflectionCount() >= 1U; },
      options,
      "three-dimensional regional initial reflection");
  assertReflection(
      {0x10U},
      {0x49U, 0x31U},
      "three-dimensional regional initial reflection");
  auto const reflectedCount = subscriber.recorder().reflectionCount();

  auto expectSuppressed = [&](rti::DimensionHandle const& dimension,
                              rti::RangeBounds const& disjoint,
                              rti::RangeBounds const& restored,
                              std::string const& dimensionDescription) {
    publisher.rtiAmbassador().setRangeBounds(sourceRegion, dimension, disjoint);
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
    update({0x20U}, {0x53U, 0x50U});
    for (int pass = 0; pass != 16; ++pass) {
      subscriber.pump();
    }
    require(
        subscriber.recorder().reflectionCount() == reflectedCount,
        "three-dimensional regional " + dimensionDescription +
            " disjoint source mutation was delivered");
    publisher.rtiAmbassador().setRangeBounds(sourceRegion, dimension, restored);
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
  };
  expectSuppressed(
      publisherHandles.dimensions.at(0),
      rti::RangeBounds(6UL, 8UL),
      rti::RangeBounds(0UL, 5UL),
      "first-dimension");
  expectSuppressed(
      publisherHandles.dimensions.at(1),
      rti::RangeBounds(3UL, 4UL),
      rti::RangeBounds(0UL, 2UL),
      "second-dimension");
  expectSuppressed(
      publisherHandles.dimensions.at(2),
      rti::RangeBounds(2UL, 3UL),
      rti::RangeBounds(0UL, 1UL),
      "third-dimension");

  update({0x30U}, {0x52U, 0x31U});
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().reflectionCount() > reflectedCount; },
      options,
      "three-dimensional regional restored reflection");
  assertReflection(
      {0x30U},
      {0x52U, 0x31U},
      "three-dimensional regional restored reflection");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      subscriberPair);
  publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});
  subscriber.rtiAmbassador().deleteRegion(subscriberRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  subscriber.disconnect();
  publisher.disconnect();
}

void scenarioRegionalInteractionSubscriptionFilteringContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalInteractionSubscriptionFiltering(options, model);
}

void scenarioRegionalInteractionRegionValidation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.modelFom.empty(),
      "Regional interaction region validation requires an adapter-supplied model FOM");

  auto runInvalidSend = [&] {
    Session publisher(options, model, "owner");
    Session subscriber(options, model, "member");
    auto const federation = federationName(
        options,
        "regional-interaction-region-validation-send");
    connectAndJoin(publisher, subscriber, options, federation, options.modelFom);

    auto const publisherHandles = modelRegionalInteractionHandles(publisher, options);
    auto const subscriberHandles = modelRegionalInteractionHandles(subscriber, options);
    require(
        publisherHandles.interactionClass == subscriberHandles.interactionClass &&
            publisherHandles.parameter == subscriberHandles.parameter,
        "regional interaction validation members resolved different declaration handles");
    publisher.rtiAmbassador().publishInteractionClass(
        publisherHandles.interactionClass);
    subscriber.rtiAmbassador().subscribeInteractionClass(
        subscriberHandles.interactionClass);
    subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);

    auto const validRegion = publisher.rtiAmbassador().createRegion(
        rti::DimensionHandleSet{
            publisherHandles.firstDimension,
            publisherHandles.secondDimension});
    auto const unrelatedRegion = publisher.rtiAmbassador().createRegion(
        rti::DimensionHandleSet{publisherHandles.unrelatedDimension});
    require(
        validRegion.isValid() && unrelatedRegion.isValid(),
        "regional interaction validation returned an invalid source region handle");
    publisher.rtiAmbassador().setRangeBounds(
        validRegion,
        publisherHandles.firstDimension,
        rti::RangeBounds(0UL, 10UL));
    publisher.rtiAmbassador().setRangeBounds(
        validRegion,
        publisherHandles.secondDimension,
        rti::RangeBounds(0UL, 10UL));
    publisher.rtiAmbassador().setRangeBounds(
        unrelatedRegion,
        publisherHandles.unrelatedDimension,
        rti::RangeBounds(0UL, 4UL));
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{validRegion, unrelatedRegion});

    std::vector<std::uint8_t> const parameterBytes{0x01U};
    std::vector<std::uint8_t> const invalidTagBytes{
        0x6dU,
        0x69U,
        0x78U,
        0x65U,
        0x64U};
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherHandles.parameter,
        rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
    rti::VariableLengthData const invalidTag(
        invalidTagBytes.data(),
        invalidTagBytes.size());

    requireException(
        [&] {
          publisher.rtiAmbassador().sendInteractionWithRegions(
              publisherHandles.interactionClass,
              parameters,
              rti::RegionHandleSet{validRegion, unrelatedRegion},
              invalidTag);
        },
        L"InvalidRegionContext",
        "regional interaction send with an unavailable dimension");
    for (int pass = 0; pass != 8; ++pass) {
      subscriber.pump();
    }
    require(
        subscriber.recorder().interactions().empty(),
        "invalid regional interaction send left a partial delivery behind");

    std::vector<std::uint8_t> const validTagBytes{
        0x76U,
        0x61U,
        0x6cU,
        0x69U,
        0x64U};
    rti::VariableLengthData const validTag(
        validTagBytes.data(),
        validTagBytes.size());
    publisher.rtiAmbassador().sendInteractionWithRegions(
        publisherHandles.interactionClass,
        parameters,
        rti::RegionHandleSet{validRegion},
        validTag);
    waitFor(
        subscriber,
        [&] { return subscriber.recorder().interactions().size() >= 1U; },
        options,
        "valid regional interaction after rejected mixed region set");
    auto const interactions = subscriber.recorder().interactions();
    require(
        interactions.size() == 1U,
        "valid regional interaction after rejected mixed region set duplicated delivery");
    auto const& interaction = interactions.front();
    require(
        interaction.interaction == subscriberHandles.interactionClass &&
            interaction.parameters.size() == 1U &&
            interaction.parameters.count(subscriberHandles.parameter) == 1U &&
            copyBytes(interaction.parameters.at(subscriberHandles.parameter)) == parameterBytes &&
            interaction.tag == validTagBytes &&
            interaction.producer == publisher.federateHandle() &&
            interaction.transportation.isValid(),
        "valid regional interaction changed the delivered payload or metadata");
    require(
        interaction.regions.has_value() && interaction.regions->size() == 1U,
        "valid regional interaction did not convey exactly one source region");

    subscriber.rtiAmbassador().unsubscribeInteractionClass(
        subscriberHandles.interactionClass);
    publisher.rtiAmbassador().unpublishInteractionClass(
        publisherHandles.interactionClass);
    publisher.rtiAmbassador().deleteRegion(unrelatedRegion);
    publisher.rtiAmbassador().deleteRegion(validRegion);
    subscriber.resign(rti::NO_ACTION);
    publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    subscriber.disconnect();
    publisher.disconnect();
  };

  auto runInvalidSubscription = [&] {
    Session publisher(options, model, "owner");
    Session subscriber(options, model, "member");
    auto const federation = federationName(
        options,
        "regional-interaction-region-validation-subscription");
    connectAndJoin(publisher, subscriber, options, federation, options.modelFom);

    auto const publisherHandles = modelRegionalInteractionHandles(publisher, options);
    auto const subscriberHandles = modelRegionalInteractionHandles(subscriber, options);
    require(
        publisherHandles.interactionClass == subscriberHandles.interactionClass &&
            publisherHandles.parameter == subscriberHandles.parameter,
        "regional subscription validation members resolved different declaration handles");
    publisher.rtiAmbassador().publishInteractionClass(
        publisherHandles.interactionClass);
    subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);

    auto const sourceRegion = publisher.rtiAmbassador().createRegion(
        rti::DimensionHandleSet{
            publisherHandles.firstDimension,
            publisherHandles.secondDimension});
    auto const validSubscriptionRegion = subscriber.rtiAmbassador().createRegion(
        rti::DimensionHandleSet{
            subscriberHandles.firstDimension,
            subscriberHandles.secondDimension});
    auto const unrelatedSubscriptionRegion = subscriber.rtiAmbassador().createRegion(
        rti::DimensionHandleSet{subscriberHandles.unrelatedDimension});
    require(
        sourceRegion.isValid() && validSubscriptionRegion.isValid() &&
            unrelatedSubscriptionRegion.isValid(),
        "regional subscription validation returned an invalid region handle");
    publisher.rtiAmbassador().setRangeBounds(
        sourceRegion,
        publisherHandles.firstDimension,
        rti::RangeBounds(0UL, 2UL));
    publisher.rtiAmbassador().setRangeBounds(
        sourceRegion,
        publisherHandles.secondDimension,
        rti::RangeBounds(0UL, 2UL));
    subscriber.rtiAmbassador().setRangeBounds(
        validSubscriptionRegion,
        subscriberHandles.firstDimension,
        rti::RangeBounds(0UL, 2UL));
    subscriber.rtiAmbassador().setRangeBounds(
        validSubscriptionRegion,
        subscriberHandles.secondDimension,
        rti::RangeBounds(0UL, 2UL));
    subscriber.rtiAmbassador().setRangeBounds(
        unrelatedSubscriptionRegion,
        subscriberHandles.unrelatedDimension,
        rti::RangeBounds(0UL, 2UL));
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
    subscriber.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{
            validSubscriptionRegion,
            unrelatedSubscriptionRegion});

    std::vector<std::uint8_t> const parameterBytes{0x01U};
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherHandles.parameter,
        rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
    auto send = [&](std::vector<std::uint8_t> const& tagBytes) {
      rti::VariableLengthData const tag(tagBytes.data(), tagBytes.size());
      publisher.rtiAmbassador().sendInteractionWithRegions(
          publisherHandles.interactionClass,
          parameters,
          rti::RegionHandleSet{sourceRegion},
          tag);
      for (int pass = 0; pass != 8; ++pass) {
        subscriber.pump();
      }
    };

    requireException(
        [&] {
          subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
              subscriberHandles.interactionClass,
              rti::RegionHandleSet{unrelatedSubscriptionRegion});
        },
        L"InvalidRegionContext",
        "regional interaction subscription with an unavailable dimension");
    send({0x61U, 0x66U, 0x74U, 0x65U, 0x72U});
    require(
        subscriber.recorder().interactions().empty(),
        "rejected regional interaction subscription left a partial declaration behind");

    subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
        subscriberHandles.interactionClass,
        rti::RegionHandleSet{validSubscriptionRegion});
    std::vector<std::uint8_t> const validTagBytes{
        0x76U,
        0x61U,
        0x6cU,
        0x69U,
        0x64U,
        0x2dU,
        0x73U,
        0x75U,
        0x62U};
    send(validTagBytes);
    waitFor(
        subscriber,
        [&] { return subscriber.recorder().interactions().size() >= 1U; },
        options,
        "valid regional interaction after rejected subscription");
    auto const interactions = subscriber.recorder().interactions();
    require(
        interactions.size() == 1U,
        "valid regional interaction after rejected subscription duplicated delivery");
    auto const& interaction = interactions.front();
    require(
        interaction.interaction == subscriberHandles.interactionClass &&
            interaction.parameters.size() == 1U &&
            interaction.parameters.count(subscriberHandles.parameter) == 1U &&
            copyBytes(interaction.parameters.at(subscriberHandles.parameter)) == parameterBytes &&
            interaction.tag == validTagBytes &&
            interaction.producer == publisher.federateHandle() &&
            interaction.transportation.isValid(),
        "valid regional subscription changed the delivered payload or metadata");
    require(
        interaction.regions.has_value() && interaction.regions->size() == 1U,
        "valid regional subscription did not convey exactly one source region");

    subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
        subscriberHandles.interactionClass,
        rti::RegionHandleSet{validSubscriptionRegion});
    publisher.rtiAmbassador().unpublishInteractionClass(
        publisherHandles.interactionClass);
    subscriber.rtiAmbassador().deleteRegion(unrelatedSubscriptionRegion);
    subscriber.rtiAmbassador().deleteRegion(validSubscriptionRegion);
    publisher.rtiAmbassador().deleteRegion(sourceRegion);
    subscriber.resign(rti::NO_ACTION);
    publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    subscriber.disconnect();
    publisher.disconnect();
  };

  runInvalidSend();
  runInvalidSubscription();
}

void scenarioRegionalInteractionRegionValidationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalInteractionRegionValidation(options, model);
}

void scenarioTimestampedRegionalInteraction(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session immediate(options, model, "member");
  Session constrained(options, model, "constrained");
  Session disjoint(options, model, "passive");
  auto const federation = federationName(options, "timestamped-regional-interaction");
  connectAndJoin(owner, immediate, options, federation, options.ddmFom);
  constrained.connect();
  constrained.join(
      options.memberFederateName + L"-regional-constrained",
      options.federateType,
      federation);
  disjoint.connect();
  disjoint.join(
      options.memberFederateName + L"-regional-timestamped-disjoint",
      options.federateType,
      federation);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const immediateHandles = ddmHandles(immediate, options);
  auto const constrainedHandles = ddmHandles(constrained, options);
  auto const disjointHandles = ddmHandles(disjoint, options);
  verifyDdmClassDimensions(
      owner,
      options,
      ownerHandles,
      "timestamped regional interaction");

  owner.rtiAmbassador().publishInteractionClass(ownerHandles.interactionClass);
  owner.rtiAmbassador().changeInteractionOrderType(
      ownerHandles.interactionClass, rti::TIMESTAMP);
  auto const sourceRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 1UL, 5UL);
  auto const immediateRegion =
      createDdmRegion(immediate, immediateHandles, 2UL, 6UL, 2UL, 6UL);
  auto const constrainedRegion =
      createDdmRegion(constrained, constrainedHandles, 2UL, 6UL, 2UL, 6UL);
  auto const disjointRegion =
      createDdmRegion(disjoint, disjointHandles, 7UL, 9UL, 7UL, 9UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const immediateRegionSet = rti::RegionHandleSet{immediateRegion};
  auto const constrainedRegionSet = rti::RegionHandleSet{constrainedRegion};
  auto const disjointRegionSet = rti::RegionHandleSet{disjointRegion};
  immediate.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  constrained.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  disjoint.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  immediate.rtiAmbassador().subscribeInteractionClassWithRegions(
      immediateHandles.interactionClass, immediateRegionSet, true);
  constrained.rtiAmbassador().subscribeInteractionClassWithRegions(
      constrainedHandles.interactionClass, constrainedRegionSet, true);
  disjoint.rtiAmbassador().subscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet, true);

  auto ownerTime = makeTimeContext(owner);
  auto constrainedTime = makeTimeContext(constrained);
  require(
      ownerTime.factory->getName() == constrainedTime.factory->getName(),
      "timestamped regional interaction members selected different logical-time factories");
  enableTimestampedRoles(
      owner,
      constrained,
      ownerTime,
      constrainedTime,
      options,
      "timestamped regional interaction");

  auto assertInteraction = [&](TimedInteractionRecord const& record,
                               rti::InteractionClassHandle const& expectedInteraction,
                               rti::ParameterHandle const& expectedParameter,
                               std::vector<std::uint8_t> const& expectedValue,
                               std::vector<std::uint8_t> const& expectedTag,
                               std::vector<std::uint8_t> const& expectedTime,
                               rti::OrderType expectedReceivedOrder,
                               Session& inspector) {
    require(record.interaction == expectedInteraction,
            "timestamped regional interaction returned the wrong class handle");
    require(record.parameters.size() == 1U &&
                record.parameters.count(expectedParameter) == 1U,
            "timestamped regional interaction returned the wrong parameter set");
    require(copyBytes(record.parameters.at(expectedParameter)) == expectedValue,
            "timestamped regional interaction returned the wrong parameter value");
    require(record.tag == expectedTag && record.time == expectedTime,
            "timestamped regional interaction did not preserve user data");
    require(record.producer == owner.federateHandle() && record.timeText.size() != 0U,
            "timestamped regional interaction returned the wrong producer or time text");
    require(record.transportation.isValid() &&
                !inspector.rtiAmbassador().getTransportationTypeName(
                    record.transportation).empty(),
            "timestamped regional interaction returned an unresolvable transport");
    require(record.sentOrder == rti::TIMESTAMP &&
                record.receivedOrder == expectedReceivedOrder,
            "timestamped regional interaction returned the wrong order metadata");
    require(record.regions.has_value() && record.regions->size() == 1U &&
                record.regions->count(sourceRegion) == 1U,
            "timestamped regional interaction omitted the source region designator set");
  };

  auto firstTime = timeAfter(
      *ownerTime.factory,
      *ownerTime.initial,
      *ownerTime.epsilon,
      3U);
  auto firstConstrainedTime = timeAfter(
      *constrainedTime.factory,
      *constrainedTime.initial,
      *constrainedTime.epsilon,
      3U);
  std::vector<std::uint8_t> firstValue{0x01U, 0x02U, 0x03U};
  std::vector<std::uint8_t> firstTag{0x51U, 0x31U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(firstValue.data(), firstValue.size()));
  rti::VariableLengthData firstUserTag(firstTag.data(), firstTag.size());
  auto const firstRetraction = owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      firstParameters,
      sourceRegionSet,
      firstUserTag,
      *firstTime);
  require(firstRetraction.isValid(),
          "timestamped regional interaction returned an invalid retraction handle");
  waitFor(
      immediate,
      [&] { return immediate.recorder().timedInteractions().size() >= 1U; },
      options,
      "immediate timestamped regional interaction delivery");
  auto const firstImmediate = immediate.recorder().timedInteractions();
  require(firstImmediate.size() == 1U,
          "immediate regional receiver received duplicate timestamped interactions");
  assertInteraction(
      firstImmediate.front(),
      immediateHandles.interactionClass,
      immediateHandles.parameter,
      firstValue,
      firstTag,
      encodeTime(*firstTime),
      rti::RECEIVE,
      immediate);
  require(firstImmediate.front().retractionPresent &&
              firstImmediate.front().retraction == copyBytes(firstRetraction.encode()),
          "immediate regional interaction omitted its retraction handle");
  require(constrained.recorder().timedInteractions().empty(),
          "constrained regional receiver delivered before its time grant");
  for (int pass = 0; pass != 8; ++pass) {
    disjoint.pump();
  }
  require(disjoint.recorder().timedInteractions().empty(),
          "disjoint regional receiver received a timestamped interaction");

  owner.rtiAmbassador().retract(firstRetraction);
  waitFor(
      immediate,
      [&] { return immediate.recorder().retractions().size() >= 1U; },
      options,
      "timestamped regional interaction retraction callback");
  auto const immediateRetractions = immediate.recorder().retractions();
  require(immediateRetractions.size() == 1U && immediateRetractions.front().valid &&
              immediateRetractions.front().encoded == copyBytes(firstRetraction.encode()),
          "timestamped regional interaction retraction returned the wrong handle");
  require(constrained.recorder().retractions().empty(),
          "pending constrained regional interaction produced a retraction callback");

  constrained.rtiAmbassador().timeAdvanceRequest(*firstConstrainedTime);
  owner.rtiAmbassador().timeAdvanceRequest(*firstTime);
  waitFor(
      owner,
      constrained,
      [&] {
        return owner.recorder().timeAdvanceGrants().size() >= 1U &&
            constrained.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "first timestamped regional interaction grants");
  for (int pass = 0; pass != 8; ++pass) {
    constrained.pump();
  }
  require(constrained.recorder().timedInteractions().empty(),
          "retracted constrained regional interaction was delivered at its grant");

  auto secondTime = timeAfter(
      *ownerTime.factory,
      *firstTime,
      *ownerTime.epsilon,
      3U);
  auto secondConstrainedTime = timeAfter(
      *constrainedTime.factory,
      *firstConstrainedTime,
      *constrainedTime.epsilon,
      3U);
  std::vector<std::uint8_t> secondValue{0x21U, 0x22U};
  std::vector<std::uint8_t> secondTag{0x51U, 0x32U};
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(secondValue.data(), secondValue.size()));
  rti::VariableLengthData secondUserTag(secondTag.data(), secondTag.size());
  auto const secondRetraction = owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      secondParameters,
      sourceRegionSet,
      secondUserTag,
      *secondTime);
  require(secondRetraction.isValid(),
          "second timestamped regional interaction returned an invalid retraction handle");
  waitFor(
      immediate,
      [&] { return immediate.recorder().timedInteractions().size() >= 2U; },
      options,
      "second immediate timestamped regional interaction delivery");
  auto const secondImmediate = immediate.recorder().timedInteractions();
  require(secondImmediate.size() == 2U,
          "immediate regional receiver received duplicate second interactions");
  assertInteraction(
      secondImmediate.at(1),
      immediateHandles.interactionClass,
      immediateHandles.parameter,
      secondValue,
      secondTag,
      encodeTime(*secondTime),
      rti::RECEIVE,
      immediate);
  require(secondImmediate.at(1).retractionPresent &&
              secondImmediate.at(1).retraction == copyBytes(secondRetraction.encode()),
          "second immediate regional interaction omitted its retraction handle");

  constrained.rtiAmbassador().timeAdvanceRequest(*secondConstrainedTime);
  owner.rtiAmbassador().timeAdvanceRequest(*secondTime);
  waitFor(
      owner,
      constrained,
      [&] {
        return owner.recorder().timeAdvanceGrants().size() >= 2U &&
            constrained.recorder().timeAdvanceGrants().size() >= 2U &&
            constrained.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "second timestamped regional interaction delivery and grants");
  auto const constrainedInteractions = constrained.recorder().timedInteractions();
  require(constrainedInteractions.size() == 1U,
          "constrained regional receiver received the wrong interaction count");
  assertInteraction(
      constrainedInteractions.front(),
      constrainedHandles.interactionClass,
      constrainedHandles.parameter,
      secondValue,
      secondTag,
      encodeTime(*secondTime),
      rti::TIMESTAMP,
      constrained);
  require(constrainedInteractions.front().retractionPresent &&
              constrainedInteractions.front().retraction ==
                  copyBytes(secondRetraction.encode()),
          "constrained regional interaction omitted its retraction handle");
  requireException(
      [&] { owner.rtiAmbassador().retract(secondRetraction); },
      L"MessageCanNoLongerBeRetracted",
      "retraction after constrained regional interaction delivery");

  constrained.rtiAmbassador().disableTimeConstrained();
  owner.rtiAmbassador().disableTimeRegulation();
  immediate.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      immediateHandles.interactionClass, immediateRegionSet);
  constrained.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      constrainedHandles.interactionClass, constrainedRegionSet);
  disjoint.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet);
  owner.rtiAmbassador().unpublishInteractionClass(ownerHandles.interactionClass);
  owner.rtiAmbassador().deleteRegion(sourceRegion);
  immediate.rtiAmbassador().deleteRegion(immediateRegion);
  constrained.rtiAmbassador().deleteRegion(constrainedRegion);
  disjoint.rtiAmbassador().deleteRegion(disjointRegion);

  owner.resign(rti::NO_ACTION);
  immediate.resign(rti::NO_ACTION);
  constrained.resign(rti::NO_ACTION);
  disjoint.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  immediate.disconnect();
  constrained.disconnect();
  disjoint.disconnect();
}

void scenarioTimestampedRegionalInteractionContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioTimestampedRegionalInteraction(options, model);
}

void scenarioTimestampedRegionalInteractionRegulationReenable(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction regulation re-enable requires an adapter-supplied logical-time implementation");
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction regulation re-enable requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-regulation-reenable");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction regulation re-enable");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);
  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timestamped regional interaction regulation re-enable");

  auto const interactionTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const changedLookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto changedLookahead = publisherTime.factory->makeZero();
  require(
      changedLookahead != nullptr,
      "timestamped regional interaction regulation re-enable could not allocate the changed lookahead");
  changedLookahead->setToDifference(
      *changedLookaheadTime,
      *publisherTime.initial);

  std::vector<std::uint8_t> parameterBytes{0xC7U, 0x19U};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x47U, 0x43U, 0x48U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *interactionTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction regulation re-enable send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction regulation re-enable delivered before its grant");

  // Move the live source out of overlap after admission. The queued passel
  // must retain its invocation-time source-region snapshot.
  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension,
      rti::RangeBounds(7UL, 9UL));
  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.secondDimension,
      rti::RangeBounds(7UL, 9UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceRegion});

  publisher.rtiAmbassador().disableTimeRegulation();
  publisher.rtiAmbassador().enableTimeRegulation(*changedLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 2U; },
      options,
      "timestamped regional interaction regulation re-enable callback");
  auto queriedLookahead = publisherTime.factory->makeZero();
  require(
      queriedLookahead != nullptr,
      "timestamped regional interaction regulation re-enable could not allocate a lookahead query");
  publisher.rtiAmbassador().queryLookahead(*queriedLookahead);
  require(
      *queriedLookahead == *changedLookahead,
      "timestamped regional interaction regulation re-enable did not expose the changed lookahead");

  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();
  receiver.rtiAmbassador().timeAdvanceRequest(*interactionTime);
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction regulation re-enable delivered while the producer boundary was pending");
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitFor(
      publisher,
      receiver,
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "timestamped regional interaction regulation re-enable delivery");

  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U &&
          publisher.recorder().timeRegulationEnabled().size() == 2U,
      "timestamped regional interaction regulation re-enable returned the wrong callback counts");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction regulation re-enable delivered after its grant");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverHandles.parameter)) == parameterBytes,
      "timestamped regional interaction regulation re-enable returned the wrong class or parameter");
  require(
      interaction.tag == tagBytes &&
          interaction.time == encodeTime(*interactionTime) &&
          !interaction.timeText.empty(),
      "timestamped regional interaction regulation re-enable did not preserve value metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped regional interaction regulation re-enable returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped regional interaction regulation re-enable returned an unresolvable transport");
  require(
      interaction.regions.has_value() &&
          interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegion) == 1U,
      "timestamped regional interaction regulation re-enable did not preserve the source region snapshot");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped regional interaction regulation re-enable omitted the retraction handle");
  require(
      publisher.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*publisherTarget),
      "timestamped regional interaction regulation re-enable returned the wrong producer grant");
  require(
      receiver.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*interactionTime),
      "timestamped regional interaction regulation re-enable returned the wrong receiver grant");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction regulation re-enable retraction after delivery");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionRegulationReenableContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioTimestampedRegionalInteractionRegulationReenable(options, model);
}

void scenarioTimestampedRegionalInteractionAlternateAdvances(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction alternate advances require an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction alternate advances require an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session flushQueue(options, model, "member");
  Session timeAdvanceAvailable(options, model, "member");
  Session nextMessageAvailable(options, model, "member");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-alternate-advances");
  connectAndJoin(publisher, flushQueue, options, federation, options.ddmFom);
  timeAdvanceAvailable.connect();
  timeAdvanceAvailable.join(
      options.memberFederateName + L"-regional-interaction-tara",
      options.federateType,
      federation);
  nextMessageAvailable.connect();
  nextMessageAvailable.join(
      options.memberFederateName + L"-regional-interaction-nmra",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const flushQueueHandles = ddmHandles(flushQueue, options);
  auto const timeAdvanceAvailableHandles = ddmHandles(timeAdvanceAvailable, options);
  auto const nextMessageAvailableHandles = ddmHandles(nextMessageAvailable, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction alternate advances");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const flushQueueRegion = createDdmRegion(
      flushQueue,
      flushQueueHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const timeAdvanceAvailableRegion = createDdmRegion(
      timeAdvanceAvailable,
      timeAdvanceAvailableHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const nextMessageAvailableRegion = createDdmRegion(
      nextMessageAvailable,
      nextMessageAvailableHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const flushQueueRegionSet = rti::RegionHandleSet{flushQueueRegion};
  auto const timeAdvanceAvailableRegionSet =
      rti::RegionHandleSet{timeAdvanceAvailableRegion};
  auto const nextMessageAvailableRegionSet =
      rti::RegionHandleSet{nextMessageAvailableRegion};
  flushQueue.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  timeAdvanceAvailable.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  nextMessageAvailable.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      flushQueue.rtiAmbassador().getConveyRegionDesignatorSetsSwitch() &&
          timeAdvanceAvailable.rtiAmbassador().getConveyRegionDesignatorSetsSwitch() &&
          nextMessageAvailable.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timestamped regional interaction alternate recipients did not enable region designator callbacks");
  flushQueue.rtiAmbassador().subscribeInteractionClassWithRegions(
      flushQueueHandles.interactionClass,
      flushQueueRegionSet,
      true);
  timeAdvanceAvailable.rtiAmbassador().subscribeInteractionClassWithRegions(
      timeAdvanceAvailableHandles.interactionClass,
      timeAdvanceAvailableRegionSet,
      true);
  nextMessageAvailable.rtiAmbassador().subscribeInteractionClassWithRegions(
      nextMessageAvailableHandles.interactionClass,
      nextMessageAvailableRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto flushQueueTime = makeTimeContext(flushQueue);
  auto timeAdvanceAvailableTime = makeTimeContext(timeAdvanceAvailable);
  auto nextMessageAvailableTime = makeTimeContext(nextMessageAvailable);
  require(
      publisherTime.factory->getName() == flushQueueTime.factory->getName() &&
          publisherTime.factory->getName() == timeAdvanceAvailableTime.factory->getName() &&
          publisherTime.factory->getName() == nextMessageAvailableTime.factory->getName(),
      "timestamped regional interaction alternate members selected different logical-time factories");
  for (auto* member :
       std::vector<Session*>{&flushQueue, &timeAdvanceAvailable, &nextMessageAvailable}) {
    member->rtiAmbassador().enableTimeConstrained();
    waitFor(
        *member,
        [&] { return member->recorder().timeConstrainedEnabled().size() >= 1U; },
        options,
        "timestamped regional interaction alternate time-constrained callback");
  }
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction alternate time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const requestBoundary = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  std::vector<std::uint8_t> parameterBytes{0x61U, 0x62U, 0x63U};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x49U, 0x41U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction alternate send returned an invalid retraction handle");
  require(
      flushQueue.recorder().timedInteractions().empty() &&
          timeAdvanceAvailable.recorder().timedInteractions().empty() &&
          nextMessageAvailable.recorder().timedInteractions().empty(),
      "timestamped regional interaction alternate recipient received an interaction before its request");
  flushQueue.recorder().clearCallbackOrder();
  timeAdvanceAvailable.recorder().clearCallbackOrder();
  nextMessageAvailable.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();

  flushQueue.rtiAmbassador().flushQueueRequest(*requestBoundary);
  timeAdvanceAvailable.rtiAmbassador().timeAdvanceRequestAvailable(*messageTime);
  nextMessageAvailable.rtiAmbassador().nextMessageRequestAvailable(*requestBoundary);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);

  waitForSessions(
      {&publisher, &flushQueue, &timeAdvanceAvailable, &nextMessageAvailable},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            flushQueue.recorder().timedInteractions().size() >= 1U &&
            flushQueue.recorder().flushQueueGrants().size() >= 1U &&
            timeAdvanceAvailable.recorder().timedInteractions().size() >= 1U &&
            timeAdvanceAvailable.recorder().timeAdvanceGrants().size() >= 1U &&
            nextMessageAvailable.recorder().timedInteractions().size() >= 1U &&
            nextMessageAvailable.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction alternate delivery and grants");

  require(
      publisher.recorder().timeAdvanceGrants().size() == 1U,
      "timestamped regional interaction alternate publisher received the wrong grant count");
  require(
      flushQueue.recorder().timedInteractions().size() == 1U &&
          flushQueue.recorder().flushQueueGrants().size() == 1U &&
          flushQueue.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction Flush Queue Request returned the wrong callback pair");
  require(
      timeAdvanceAvailable.recorder().timedInteractions().size() == 1U &&
          timeAdvanceAvailable.recorder().timeAdvanceGrants().size() == 1U &&
          timeAdvanceAvailable.recorder().flushQueueGrants().empty(),
      "timestamped regional interaction Time Advance Request Available returned the wrong callback pair");
  require(
      nextMessageAvailable.recorder().timedInteractions().size() == 1U &&
          nextMessageAvailable.recorder().timeAdvanceGrants().size() == 1U &&
          nextMessageAvailable.recorder().flushQueueGrants().empty(),
      "timestamped regional interaction Next Message Request Available returned the wrong callback pair");
  require(
      flushQueue.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "flush-grant"},
      "timestamped regional interaction Flush Queue Request granted before delivery");
  require(
      timeAdvanceAvailable.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction Time Advance Request Available granted before delivery");
  require(
      nextMessageAvailable.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction Next Message Request Available granted before delivery");

  auto assertInteraction = [&](TimedInteractionRecord const& record,
                               rti::InteractionClassHandle const& expectedInteraction,
                               rti::ParameterHandle const& expectedParameter,
                               Session& inspector) {
    require(
        record.interaction == expectedInteraction &&
            record.parameters.size() == 1U &&
            record.parameters.count(expectedParameter) == 1U,
        "timestamped regional interaction alternate callback returned the wrong class or parameters");
    require(
        copyBytes(record.parameters.at(expectedParameter)) == parameterBytes &&
            record.tag == tagBytes,
        "timestamped regional interaction alternate callback did not preserve parameter or tag data");
    require(
        record.producer == publisher.federateHandle() &&
            record.time == encodeTime(*messageTime) &&
            !record.timeText.empty(),
        "timestamped regional interaction alternate callback returned the wrong producer or time");
    require(
        record.transportation.isValid() &&
            !inspector.rtiAmbassador().getTransportationTypeName(record.transportation).empty(),
        "timestamped regional interaction alternate callback returned an unresolvable transport");
    require(
        record.sentOrder == rti::TIMESTAMP && record.receivedOrder == rti::TIMESTAMP,
        "timestamped regional interaction alternate callback returned the wrong order metadata");
    require(
        record.regions.has_value() && record.regions->size() == 1U &&
            record.regions->count(sourceRegion) == 1U,
        "timestamped regional interaction alternate callback omitted the source region designator");
    require(
        record.retractionPresent && record.retraction == copyBytes(retraction.encode()),
        "timestamped regional interaction alternate callback omitted the retraction handle");
  };
  assertInteraction(
      flushQueue.recorder().timedInteractions().front(),
      flushQueueHandles.interactionClass,
      flushQueueHandles.parameter,
      flushQueue);
  assertInteraction(
      timeAdvanceAvailable.recorder().timedInteractions().front(),
      timeAdvanceAvailableHandles.interactionClass,
      timeAdvanceAvailableHandles.parameter,
      timeAdvanceAvailable);
  assertInteraction(
      nextMessageAvailable.recorder().timedInteractions().front(),
      nextMessageAvailableHandles.interactionClass,
      nextMessageAvailableHandles.parameter,
      nextMessageAvailable);

  require(
      publisher.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*publisherTarget),
      "timestamped regional interaction alternate publisher received the wrong grant time");
  auto const flushGrants = flushQueue.recorder().flushQueueGrants();
  require(
      flushGrants.front().optimisticTime == encodeTime(*messageTime),
      "timestamped regional interaction Flush Queue Grant returned the wrong optimistic time");
  require(
      !flushGrants.front().time.empty() && !flushGrants.front().timeText.empty() &&
          !flushGrants.front().optimisticTimeText.empty(),
      "timestamped regional interaction Flush Queue Grant returned incomplete time metadata");
  auto actualFlushTime = decodeTime(*flushQueueTime.factory, flushGrants.front().time);
  auto optimisticFlushTime =
      decodeTime(*flushQueueTime.factory, flushGrants.front().optimisticTime);
  require(
      actualFlushTime != nullptr && optimisticFlushTime != nullptr &&
          !(*actualFlushTime < *flushQueueTime.initial) &&
          !(*requestBoundary < *actualFlushTime) &&
          !(*optimisticFlushTime < *actualFlushTime),
      "timestamped regional interaction Flush Queue Grant returned time outside standard bounds");
  require(
      timeAdvanceAvailable.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*messageTime) &&
          nextMessageAvailable.recorder().timeAdvanceGrants().front().encoded ==
              encodeTime(*messageTime),
      "timestamped regional interaction alternate grants returned the wrong logical time");

  auto queriedFlushQueue = flushQueueTime.factory->makeInitial();
  flushQueue.rtiAmbassador().queryLogicalTime(*queriedFlushQueue);
  require(
      encodeTime(*queriedFlushQueue) == flushGrants.front().time,
      "timestamped regional interaction Flush Queue Request query did not match its grant");
  auto queriedTimeAdvanceAvailable = timeAdvanceAvailableTime.factory->makeInitial();
  timeAdvanceAvailable.rtiAmbassador().queryLogicalTime(*queriedTimeAdvanceAvailable);
  requireTimeEquals(
      *queriedTimeAdvanceAvailable,
      *messageTime,
      "timestamped regional interaction Time Advance Request Available logical-time query");
  auto queriedNextMessageAvailable = nextMessageAvailableTime.factory->makeInitial();
  nextMessageAvailable.rtiAmbassador().queryLogicalTime(*queriedNextMessageAvailable);
  requireTimeEquals(
      *queriedNextMessageAvailable,
      *messageTime,
      "timestamped regional interaction Next Message Request Available logical-time query");

  auto const pastFlushQueueTime = timeAfter(
      *flushQueueTime.factory,
      *flushQueueTime.initial,
      *flushQueueTime.epsilon,
      1U);
  auto const pastTimeAdvanceAvailableTime = timeAfter(
      *timeAdvanceAvailableTime.factory,
      *timeAdvanceAvailableTime.initial,
      *timeAdvanceAvailableTime.epsilon,
      1U);
  auto const pastNextMessageAvailableTime = timeAfter(
      *nextMessageAvailableTime.factory,
      *nextMessageAvailableTime.initial,
      *nextMessageAvailableTime.epsilon,
      1U);
  requireException(
      [&] { flushQueue.rtiAmbassador().flushQueueRequest(*pastFlushQueueTime); },
      L"LogicalTimeAlreadyPassed",
      "timestamped regional interaction Flush Queue Request before current time");
  requireException(
      [&] {
        timeAdvanceAvailable.rtiAmbassador().timeAdvanceRequestAvailable(
            *pastTimeAdvanceAvailableTime);
      },
      L"LogicalTimeAlreadyPassed",
      "timestamped regional interaction Time Advance Request Available before current time");
  requireException(
      [&] {
        nextMessageAvailable.rtiAmbassador().nextMessageRequestAvailable(
            *pastNextMessageAvailableTime);
      },
      L"LogicalTimeAlreadyPassed",
      "timestamped regional interaction Next Message Request Available before current time");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction alternate retraction after delivery");

  flushQueue.rtiAmbassador().disableTimeConstrained();
  timeAdvanceAvailable.rtiAmbassador().disableTimeConstrained();
  nextMessageAvailable.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  flushQueue.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      flushQueueHandles.interactionClass,
      flushQueueRegionSet);
  timeAdvanceAvailable.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      timeAdvanceAvailableHandles.interactionClass,
      timeAdvanceAvailableRegionSet);
  nextMessageAvailable.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      nextMessageAvailableHandles.interactionClass,
      nextMessageAvailableRegionSet);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  flushQueue.rtiAmbassador().deleteRegion(flushQueueRegion);
  timeAdvanceAvailable.rtiAmbassador().deleteRegion(timeAdvanceAvailableRegion);
  nextMessageAvailable.rtiAmbassador().deleteRegion(nextMessageAvailableRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  nextMessageAvailable.resign(rti::NO_ACTION);
  timeAdvanceAvailable.resign(rti::NO_ACTION);
  flushQueue.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  nextMessageAvailable.disconnect();
  timeAdvanceAvailable.disconnect();
  flushQueue.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionAlternateAdvancesContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioTimestampedRegionalInteractionAlternateAdvances(options, model);
}

void scenarioTimestampedRegionalInteractionNoOverlap(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction no-overlap requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction no-overlap requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "passive");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-no-overlap");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction no-overlap");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const publisherRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      7UL,
      9UL,
      7UL,
      9UL);
  auto const publisherRegionSet = rti::RegionHandleSet{publisherRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "timestamped regional interaction no-overlap members selected different logical-time factories");
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction no-overlap time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction no-overlap time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const publisherAdvance = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      1U);
  std::vector<std::uint8_t> parameterBytes{0x4EU, 0x4FU};
  std::vector<std::uint8_t> tagBytes{0x4FU, 0x56U, 0x45U, 0x52U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const retractable = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      publisherRegionSet,
      tag,
      *messageTime);
  require(
      retractable.isValid(),
      "timestamped regional interaction no-overlap send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction no-overlap receiver received a filtered interaction");
  publisher.rtiAmbassador().retract(retractable);
  requireException(
      [&] { publisher.rtiAmbassador().retract(retractable); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction no-overlap second retraction");

  auto const expired = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      publisherRegionSet,
      tag,
      *messageTime);
  require(
      expired.isValid(),
      "timestamped regional interaction no-overlap second send returned an invalid retraction handle");
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherAdvance);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeAdvanceGrants().size() >= 1U; },
      options,
      "timestamped regional interaction no-overlap producer advance");
  requireException(
      [&] { publisher.rtiAmbassador().retract(expired); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction no-overlap expired retraction");
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction no-overlap receiver received a later filtered interaction");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  publisher.rtiAmbassador().deleteRegion(publisherRegion);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionNoOverlapContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioTimestampedRegionalInteractionNoOverlap(options, model);
}

void scenarioTimestampedRegionalInteractionSubscriptionReplacement(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction subscription replacement requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction subscription replacement requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-subscription-replacement");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction subscription replacement");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegionA = createDdmRegion(
      publisher,
      publisherHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const sourceRegionB = createDdmRegion(
      publisher,
      publisherHandles,
      2UL,
      3UL,
      2UL,
      3UL);
  auto const receiverRegionA = createDdmRegion(
      receiver,
      receiverHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const receiverRegionB = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      3UL,
      2UL,
      3UL);
  auto const sourceRegionSetA = rti::RegionHandleSet{sourceRegionA};
  auto const sourceRegionSetB = rti::RegionHandleSet{sourceRegionB};
  auto const receiverRegionSetA = rti::RegionHandleSet{receiverRegionA};
  auto const receiverRegionSetB = rti::RegionHandleSet{receiverRegionB};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      receiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timestamped regional interaction subscription replacement did not enable region designator callbacks");
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetA,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "timestamped regional interaction subscription replacement members selected different logical-time factories");
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction subscription replacement time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction subscription replacement time-regulation callback");
  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();

  auto const firstTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const firstPublisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  std::vector<std::uint8_t> firstParameterBytes{0x49U, 0x52U, 0x31U};
  std::vector<std::uint8_t> secondParameterBytes{0x49U, 0x52U, 0x32U};
  std::vector<std::uint8_t> firstTagBytes{0x53U, 0x55U, 0x42U, 0x31U};
  std::vector<std::uint8_t> secondTagBytes{0x53U, 0x55U, 0x42U, 0x32U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(
          firstParameterBytes.data(),
          firstParameterBytes.size()));
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(
          secondParameterBytes.data(),
          secondParameterBytes.size()));
  rti::VariableLengthData firstTag(firstTagBytes.data(), firstTagBytes.size());
  rti::VariableLengthData secondTag(secondTagBytes.data(), secondTagBytes.size());

  auto const firstRetraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      firstParameters,
      sourceRegionSetA,
      firstTag,
      *firstTime);
  require(
      firstRetraction.isValid(),
      "timestamped regional interaction subscription replacement first send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction subscription replacement delivered before its grant");

  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetA);
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetB,
      true);
  receiver.rtiAmbassador().timeAdvanceRequest(*firstTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*firstPublisherTarget);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction subscription replacement first grant");
  require(
      receiver.recorder().timeAdvanceGrants().size() == 1U &&
          receiver.recorder().timedInteractions().empty() &&
          receiver.recorder().retractions().empty(),
      "timestamped regional interaction subscription replacement retargeted the first passel");
  require(
      receiver.recorder().callbackOrder() == std::vector<std::string>{"grant"},
      "timestamped regional interaction subscription replacement returned an unexpected first callback order");
  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();

  auto const secondTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      7U);
  auto const secondPublisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto const secondRetraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      secondParameters,
      sourceRegionSetB,
      secondTag,
      *secondTime);
  require(
      secondRetraction.isValid(),
      "timestamped regional interaction subscription replacement second send returned an invalid retraction handle");
  receiver.rtiAmbassador().timeAdvanceRequest(*secondTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*secondPublisherTarget);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 2U &&
            receiver.recorder().timeAdvanceGrants().size() >= 2U &&
            receiver.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "timestamped regional interaction subscription replacement second delivery");

  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U && receiver.recorder().retractions().empty(),
      "timestamped regional interaction subscription replacement returned the wrong delivery count");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverHandles.parameter)) ==
              secondParameterBytes,
      "timestamped regional interaction subscription replacement returned the wrong class or parameter");
  require(
      interaction.tag == secondTagBytes &&
          interaction.time == encodeTime(*secondTime) &&
          !interaction.timeText.empty(),
      "timestamped regional interaction subscription replacement did not preserve second metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped regional interaction subscription replacement returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped regional interaction subscription replacement returned an unresolvable transport");
  require(
      interaction.regions.has_value() && interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegionB) == 1U,
      "timestamped regional interaction subscription replacement did not carry the replacement source region");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(secondRetraction.encode()),
      "timestamped regional interaction subscription replacement omitted the second retraction handle");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction subscription replacement delivered after its grant");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetB);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  receiver.rtiAmbassador().deleteRegion(receiverRegionB);
  receiver.rtiAmbassador().deleteRegion(receiverRegionA);
  publisher.rtiAmbassador().deleteRegion(sourceRegionB);
  publisher.rtiAmbassador().deleteRegion(sourceRegionA);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionSubscriptionReplacementContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioTimestampedRegionalInteractionSubscriptionReplacement(options, model);
}

void scenarioTimestampedRegionalInteractionSourceResignation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction source resignation requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction source resignation requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  Session clock(options, model, "source-resignation-clock");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-source-resignation");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);
  clock.connect();
  clock.join(
      options.memberFederateName + L"-timestamped-regional-resignation-clock",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction source resignation");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  auto clockTime = makeTimeContext(clock);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName() &&
          publisherTime.factory->getName() == clockTime.factory->getName(),
      "timestamped regional interaction source resignation members selected different logical-time factories");

  auto makeLookahead = [](TimeContext const& time, std::size_t steps) {
    auto target = timeAfter(*time.factory, *time.initial, *time.epsilon, steps);
    auto result = time.factory->makeZero();
    require(
        result != nullptr,
        "timestamped regional interaction source resignation could not allocate a lookahead interval");
    result->setToDifference(*target, *time.initial);
    return result;
  };
  auto publisherLookahead = makeLookahead(publisherTime, 5U);
  auto clockLookahead = makeLookahead(clockTime, 5U);

  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation publisher time-regulation callback");
  clock.rtiAmbassador().enableTimeRegulation(*clockLookahead);
  waitFor(
      clock,
      [&] { return clock.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation clock time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const receiverTarget = timeAfter(
      *receiverTime.factory,
      *receiverTime.initial,
      *receiverTime.epsilon,
      6U);
  auto const clockTarget = timeAfter(
      *clockTime.factory,
      *clockTime.initial,
      *clockTime.epsilon,
      2U);
  std::vector<std::uint8_t> parameterBytes{0x52U, 0x45U, 0x47U, 0x53U};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x45U, 0x53U, 0x49U, 0x47U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction source resignation send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty() &&
          receiver.recorder().retractions().empty(),
      "timestamped regional interaction source resignation delivered before the recipient frontier");

  receiver.rtiAmbassador().timeAdvanceRequest(*receiverTarget);
  require(
      receiver.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction source resignation granted before an independent frontier");
  publisher.resign(rti::NO_ACTION);
  require(
      receiver.recorder().timedInteractions().empty() &&
          receiver.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction source resignation released the queued passel too early");

  clock.rtiAmbassador().timeAdvanceRequest(*clockTarget);
  waitFor(
      clock,
      [&] { return clock.recorder().timeAdvanceGrants().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation clock frontier");
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().timedInteractions().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction source resignation delivery and grant");

  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U,
      "timestamped regional interaction source resignation delivered a duplicate passel");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U,
      "timestamped regional interaction source resignation returned the wrong class or parameter set");
  require(
      copyBytes(interaction.parameters.at(receiverHandles.parameter)) == parameterBytes &&
          interaction.tag == tagBytes && interaction.time == encodeTime(*messageTime),
      "timestamped regional interaction source resignation did not preserve payload or time");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP &&
          !interaction.timeText.empty(),
      "timestamped regional interaction source resignation returned the wrong producer or order metadata");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped regional interaction source resignation returned an unresolvable transport");
  require(
      interaction.regions.has_value() && interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegion) == 1U,
      "timestamped regional interaction source resignation omitted the source region snapshot");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped regional interaction source resignation omitted its retraction handle");
  auto const grants = receiver.recorder().timeAdvanceGrants();
  require(
      grants.size() == 1U && grants.front().encoded == encodeTime(*receiverTarget),
      "timestamped regional interaction source resignation returned the wrong recipient grant");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction source resignation delivered after its grant");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"FederateNotExecutionMember",
      "timestamped regional interaction source resignation post-resignation retraction");

  receiver.rtiAmbassador().disableTimeConstrained();
  clock.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  receiver.resign(rti::NO_ACTION);
  clock.resign(rti::NO_ACTION);
  receiver.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  receiver.disconnect();
  clock.disconnect();
}

void scenarioTimestampedRegionalInteractionSourceResignationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioTimestampedRegionalInteractionSourceResignation(options, model);
}

void scenarioTimestampedRegionalInteractionTarNmr(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction TAR/NMR requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction TAR/NMR requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session tar(options, model, "member");
  Session nmr(options, model, "next-message-member");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-tar-nmr");
  connectAndJoin(publisher, tar, options, federation, options.ddmFom);
  nmr.connect();
  nmr.join(
      options.memberFederateName + L"-timestamped-regional-nmr",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const tarHandles = ddmHandles(tar, options);
  auto const nmrHandles = ddmHandles(nmr, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction TAR/NMR");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const tarRegion = createDdmRegion(
      tar,
      tarHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const nmrRegion = createDdmRegion(
      nmr,
      nmrHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const tarRegionSet = rti::RegionHandleSet{tarRegion};
  auto const nmrRegionSet = rti::RegionHandleSet{nmrRegion};
  tar.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  nmr.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  tar.rtiAmbassador().subscribeInteractionClassWithRegions(
      tarHandles.interactionClass,
      tarRegionSet,
      true);
  nmr.rtiAmbassador().subscribeInteractionClassWithRegions(
      nmrHandles.interactionClass,
      nmrRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto tarTime = makeTimeContext(tar);
  auto nmrTime = makeTimeContext(nmr);
  require(
      publisherTime.factory->getName() == tarTime.factory->getName() &&
          publisherTime.factory->getName() == nmrTime.factory->getName(),
      "timestamped regional interaction TAR/NMR members selected different logical-time factories");

  auto makeLookahead = [](TimeContext const& time, std::size_t steps) {
    auto target = timeAfter(*time.factory, *time.initial, *time.epsilon, steps);
    auto result = time.factory->makeZero();
    require(
        result != nullptr,
        "timestamped regional interaction TAR/NMR could not allocate a lookahead interval");
    result->setToDifference(*target, *time.initial);
    return result;
  };
  auto publisherLookahead = makeLookahead(publisherTime, 5U);

  tar.rtiAmbassador().enableTimeConstrained();
  waitFor(
      tar,
      [&] { return tar.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction TAR/NMR TAR time-constrained callback");
  nmr.rtiAmbassador().enableTimeConstrained();
  waitFor(
      nmr,
      [&] { return nmr.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction TAR/NMR NMR time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction TAR/NMR publisher time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      7U);
  auto const tarTarget = timeAfter(
      *tarTime.factory,
      *tarTime.initial,
      *tarTime.epsilon,
      7U);
  auto const nmrTarget = timeAfter(
      *nmrTime.factory,
      *nmrTime.initial,
      *nmrTime.epsilon,
      10U);
  std::vector<std::uint8_t> parameterBytes{0x54U, 0x41U, 0x52U, 0x2DU, 0x4EU};
  std::vector<std::uint8_t> tagBytes{0x54U, 0x41U, 0x52U, 0x2DU, 0x4DU};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction TAR/NMR send returned an invalid retraction handle");
  require(
      tar.recorder().timedInteractions().empty() &&
          nmr.recorder().timedInteractions().empty(),
      "timestamped regional interaction TAR/NMR delivered before either request");

  tar.rtiAmbassador().timeAdvanceRequest(*tarTarget);
  nmr.rtiAmbassador().nextMessageRequest(*nmrTarget);
  require(
      tar.recorder().timeAdvanceGrants().empty() &&
          nmr.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction TAR/NMR granted before the publisher frontier");
  publisher.rtiAmbassador().timeAdvanceRequest(
      *timeAfter(
          *publisherTime.factory,
          *publisherTime.initial,
          *publisherTime.epsilon,
          2U));
  waitForSessions(
      {&publisher, &tar, &nmr},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            tar.recorder().timedInteractions().size() >= 1U &&
            tar.recorder().timeAdvanceGrants().size() >= 1U &&
            nmr.recorder().timedInteractions().size() >= 1U &&
            nmr.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction TAR/NMR deliveries and grants");

  auto assertRegionalInteraction = [&](Session& receiver,
                                       DdmHandles const& receiverHandles,
                                       TimedInteractionRecord const& record) {
    require(
        record.interaction == receiverHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(receiverHandles.parameter) == 1U,
        "timestamped regional interaction TAR/NMR returned the wrong class or parameter set");
    require(
        copyBytes(record.parameters.at(receiverHandles.parameter)) == parameterBytes &&
            record.tag == tagBytes && record.time == encodeTime(*messageTime),
        "timestamped regional interaction TAR/NMR did not preserve payload or time");
    require(
        record.producer == publisher.federateHandle() &&
            record.sentOrder == rti::TIMESTAMP &&
            record.receivedOrder == rti::TIMESTAMP &&
            !record.timeText.empty(),
        "timestamped regional interaction TAR/NMR returned the wrong producer or order metadata");
    require(
        record.transportation.isValid() &&
            !receiver.rtiAmbassador().getTransportationTypeName(
                record.transportation).empty(),
        "timestamped regional interaction TAR/NMR returned an unresolvable transport");
    require(
        record.regions.has_value() && record.regions->size() == 1U &&
            record.regions->count(sourceRegion) == 1U,
        "timestamped regional interaction TAR/NMR omitted the source region designator");
    require(
        record.retractionPresent &&
            record.retraction == copyBytes(retraction.encode()),
        "timestamped regional interaction TAR/NMR omitted its retraction handle");
  };

  auto const tarInteractions = tar.recorder().timedInteractions();
  auto const nmrInteractions = nmr.recorder().timedInteractions();
  require(tarInteractions.size() == 1U && nmrInteractions.size() == 1U,
          "timestamped regional interaction TAR/NMR delivered duplicate callbacks");
  assertRegionalInteraction(tar, tarHandles, tarInteractions.front());
  assertRegionalInteraction(nmr, nmrHandles, nmrInteractions.front());
  require(
      tar.recorder().timeAdvanceGrants().size() == 1U &&
          tar.recorder().timeAdvanceGrants().front().encoded == encodeTime(*tarTarget),
      "timestamped regional interaction TAR/NMR returned the wrong TAR grant");
  require(
      nmr.recorder().timeAdvanceGrants().size() == 1U &&
          nmr.recorder().timeAdvanceGrants().front().encoded == encodeTime(*messageTime),
      "timestamped regional interaction TAR/NMR returned the wrong NMR grant");
  require(
      tar.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"} &&
          nmr.recorder().callbackOrder() ==
              std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction TAR/NMR delivered after its grant");

  auto tarLogicalTime = tarTime.factory->makeInitial();
  auto nmrLogicalTime = nmrTime.factory->makeInitial();
  require(
      tarLogicalTime != nullptr && nmrLogicalTime != nullptr,
      "timestamped regional interaction TAR/NMR could not allocate query times");
  tar.rtiAmbassador().queryLogicalTime(*tarLogicalTime);
  nmr.rtiAmbassador().queryLogicalTime(*nmrLogicalTime);
  require(
      *tarLogicalTime == *tarTarget && *nmrLogicalTime == *messageTime,
      "timestamped regional interaction TAR/NMR query returned the wrong logical time");

  tar.rtiAmbassador().disableTimeConstrained();
  nmr.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  tar.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      tarHandles.interactionClass,
      tarRegionSet);
  nmr.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      nmrHandles.interactionClass,
      nmrRegionSet);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  tar.rtiAmbassador().deleteRegion(tarRegion);
  nmr.rtiAmbassador().deleteRegion(nmrRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  nmr.resign(rti::NO_ACTION);
  tar.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  nmr.disconnect();
  tar.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionTarNmrContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioTimestampedRegionalInteractionTarNmr(options, model);
}

void scenarioRegionalBoundaries(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session foreign(options, model, "member");
  auto const federation = federationName(options, "regional-boundaries");
  connectAndJoin(owner, foreign, options, federation, options.ddmFom);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const foreignHandles = ddmHandles(foreign, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "regional boundaries");

  auto const emptyRegion = owner.rtiAmbassador().createRegion(rti::DimensionHandleSet{});
  require(emptyRegion.isValid(), "zero-dimensional region creation returned an invalid handle");
  require(owner.rtiAmbassador().getDimensionHandleSet(emptyRegion).empty(),
          "zero-dimensional region reported unexpected dimensions");
  owner.rtiAmbassador().commitRegionModifications(rti::RegionHandleSet{emptyRegion});
  owner.rtiAmbassador().deleteRegion(emptyRegion);

  auto const uncommittedRegion = owner.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{
          ownerHandles.firstDimension,
          ownerHandles.secondDimension});
  requireException(
      [&] {
        static_cast<void>(owner.rtiAmbassador().getRangeBounds(
            uncommittedRegion, ownerHandles.firstDimension));
      },
      L"InvalidRegion",
      "range lookup for an uncommitted region");
  requireException(
      [&] {
        owner.rtiAmbassador().commitRegionModifications(
            rti::RegionHandleSet{uncommittedRegion});
      },
      L"InvalidRegion",
      "commit of a region with missing range bounds");
  owner.rtiAmbassador().setRangeBounds(
      uncommittedRegion,
      ownerHandles.firstDimension,
      rti::RangeBounds(1UL, 5UL));
  owner.rtiAmbassador().setRangeBounds(
      uncommittedRegion,
      ownerHandles.secondDimension,
      rti::RangeBounds(1UL, 5UL));
  owner.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{uncommittedRegion});

  auto const wrongContextDimension = ddmUnrelatedDimensionHandle(owner, options);
  auto const wrongContextRegion = owner.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{wrongContextDimension});
  owner.rtiAmbassador().setRangeBounds(
      wrongContextRegion,
      wrongContextDimension,
      rti::RangeBounds(1UL, 5UL));
  owner.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{wrongContextRegion});

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);
  rti::AttributeHandleSetRegionHandleSetPairVector const wrongObjectPair{{
      ownerAttributes,
      rti::RegionHandleSet{wrongContextRegion},
  }};
  requireException(
      [&] {
        static_cast<void>(owner.rtiAmbassador().registerObjectInstanceWithRegions(
            ownerHandles.objectClass, wrongObjectPair));
      },
      L"InvalidRegionContext",
      "object registration with an incompatible region context");

  owner.rtiAmbassador().publishInteractionClass(ownerHandles.interactionClass);
  std::vector<std::uint8_t> interactionValue{0x42U};
  std::vector<std::uint8_t> interactionTag{0x42U, 0x44U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(interactionValue.data(), interactionValue.size()));
  rti::VariableLengthData userSuppliedTag(interactionTag.data(), interactionTag.size());
  requireException(
      [&] {
        owner.rtiAmbassador().sendInteractionWithRegions(
            ownerHandles.interactionClass,
            parameters,
            rti::RegionHandleSet{wrongContextRegion},
            userSuppliedTag);
      },
      L"InvalidRegionContext",
      "interaction send with an incompatible region context");

  auto const foreignRegion = createDdmRegion(
      foreign,
      foreignHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  requireException(
      [&] { owner.rtiAmbassador().deleteRegion(foreignRegion); },
      L"RegionNotCreatedByThisFederate",
      "deletion of a region created by another federate");
  requireException(
      [&] {
        owner.rtiAmbassador().commitRegionModifications(
            rti::RegionHandleSet{foreignRegion});
      },
      L"RegionNotCreatedByThisFederate",
      "commit of a region created by another federate");

  auto const subscriptionRegion = createDdmRegion(
      owner,
      ownerHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const subscriptionRegionSet = rti::RegionHandleSet{subscriptionRegion};
  owner.rtiAmbassador().subscribeInteractionClassWithRegions(
      ownerHandles.interactionClass,
      subscriptionRegionSet,
      false);
  requireException(
      [&] { owner.rtiAmbassador().deleteRegion(subscriptionRegion); },
      L"RegionInUseForUpdateOrSubscription",
      "deletion of a region used by a passive subscription");
  owner.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      ownerHandles.interactionClass,
      subscriptionRegionSet);
  owner.rtiAmbassador().deleteRegion(subscriptionRegion);

  auto const objectRegion = createDdmRegion(
      owner,
      ownerHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const objectPair{{
      ownerAttributes,
      rti::RegionHandleSet{objectRegion},
  }};
  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass, objectPair);
  require(object.isValid(), "boundary object registration returned an invalid handle");
  requireException(
      [&] { owner.rtiAmbassador().deleteRegion(objectRegion); },
      L"RegionInUseForUpdateOrSubscription",
      "deletion of a region used by an object update association");
  owner.rtiAmbassador().deleteObjectInstance(object, rti::VariableLengthData{});
  owner.rtiAmbassador().deleteRegion(objectRegion);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);
  owner.rtiAmbassador().unpublishInteractionClass(ownerHandles.interactionClass);

  owner.rtiAmbassador().deleteRegion(wrongContextRegion);
  owner.rtiAmbassador().deleteRegion(uncommittedRegion);
  foreign.rtiAmbassador().deleteRegion(foreignRegion);

  owner.resign(rti::NO_ACTION);
  foreign.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  foreign.disconnect();
}

void scenarioSynchronizationPoints(Options const& options, rti::CallbackModel model) {
  Session lifecycle(options, model, "synchronization-lifecycle");
  rti::VariableLengthData const emptyTag;
  rti::FederateHandleSet const emptySynchronizationSet;
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-global-before-connect",
            emptyTag);
      },
      L"NotConnected",
      "global synchronization-point registration before connect");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-explicit-before-connect",
            emptyTag,
            emptySynchronizationSet);
      },
      L"NotConnected",
      "explicit synchronization-point registration before connect");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().synchronizationPointAchieved(
            L"tck-lifecycle-achieved-before-connect");
      },
      L"NotConnected",
      "synchronization-point achievement before connect");
  lifecycle.connect();
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-global-before-join",
            emptyTag);
      },
      L"FederateNotExecutionMember",
      "global synchronization-point registration before joining an execution");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-explicit-before-join",
            emptyTag,
            emptySynchronizationSet);
      },
      L"FederateNotExecutionMember",
      "explicit synchronization-point registration before joining an execution");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().synchronizationPointAchieved(
            L"tck-lifecycle-achieved-before-join");
      },
      L"FederateNotExecutionMember",
      "synchronization-point achievement before joining an execution");
  lifecycle.disconnect();

  Session first(options, model, "owner");
  Session second(options, model, "member");
  Session third(options, model, "late");
  auto const federation = federationName(options, "synchronization-points");

  first.connect();
  second.connect();
  third.connect();
  first.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  first.join(options.ownerFederateName, options.federateType, federation);
  second.join(options.memberFederateName, options.federateType, federation);

  std::vector<std::uint8_t> tagBytes{0x53U, 0x59U, 0x4EU, 0x43U};
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  std::wstring const globalLabel = L"tck-global-synchronization";
  first.rtiAmbassador().registerFederationSynchronizationPoint(globalLabel, tag);
  waitForSessions(
      {&first, &second},
      [&] {
        return first.synchronizationPointRegistrations().size() >= 1U &&
            first.synchronizationPointAnnouncements().size() >= 1U &&
            second.synchronizationPointAnnouncements().size() >= 1U;
      },
      options,
      "global synchronization-point registration and announcement");

  auto const registration = first.synchronizationPointRegistrations().front();
  require(registration.succeeded && registration.label == globalLabel,
          "synchronization-point registration did not succeed for the requested label");
  for (auto* session : {&first, &second}) {
    auto const announcements = session->synchronizationPointAnnouncements();
    require(announcements.front().label == globalLabel,
            "synchronization-point announcement returned the wrong label");
    require(announcements.front().tag == tagBytes,
            "synchronization-point announcement returned the wrong tag");
  }

  // A default synchronization set includes a member that joins after the
  // point is registered, so the late member receives the pending
  // announcement and participates in the completion barrier.
  third.join(L"tck-third", options.federateType, federation);
  waitFor(
      third,
      [&] { return third.synchronizationPointAnnouncements().size() >= 1U; },
      options,
      "late synchronization-point announcement");
  require(
      third.synchronizationPointRegistrations().empty(),
      "late synchronization member received a registration-success callback");
  auto const lateAnnouncements = third.synchronizationPointAnnouncements();
  require(lateAnnouncements.front().label == globalLabel &&
              lateAnnouncements.front().tag == tagBytes,
          "late synchronization-point announcement returned the wrong label or tag");

  // Registration is one-shot by label.  A duplicate is reported to the
  // requesting federate and does not replace the already announced point.
  second.rtiAmbassador().registerFederationSynchronizationPoint(globalLabel, tag);
  waitFor(
      second,
      [&] { return second.synchronizationPointRegistrations().size() >= 1U; },
      options,
      "duplicate synchronization-point registration result");
  auto const duplicate = second.synchronizationPointRegistrations().back();
  require(!duplicate.succeeded && duplicate.label == globalLabel &&
              duplicate.failureReason.has_value() &&
              duplicate.failureReason.value() ==
                  rti::SYNCHRONIZATION_POINT_LABEL_NOT_UNIQUE,
          "duplicate synchronization-point registration returned the wrong result");

  first.rtiAmbassador().synchronizationPointAchieved(globalLabel, true);
  second.rtiAmbassador().synchronizationPointAchieved(globalLabel, false);
  third.rtiAmbassador().synchronizationPointAchieved(globalLabel, true);
  waitForSessions(
      {&first, &second, &third},
      [&] {
        return first.federationSynchronized().size() >= 1U &&
            second.federationSynchronized().size() >= 1U &&
            third.federationSynchronized().size() >= 1U;
      },
      options,
      "synchronization-point completion");
  for (auto* session : {&first, &second, &third}) {
    auto const completions = session->federationSynchronized();
    require(completions.front().label == globalLabel,
            "federation synchronized callback returned the wrong label");
    require(completions.front().failedToSyncSet.count(second.federateHandle()) == 1U,
            "federation synchronized callback omitted the unsuccessful federate");
  }
  requireException(
      [&] { first.rtiAmbassador().synchronizationPointAchieved(globalLabel); },
      L"SynchronizationPointLabelNotAnnounced",
      "re-achieving a completed synchronization point");

  // An explicit synchronization set excludes the third member, which gives
  // the portable test a second registration form without relying on provider
  // membership reports or private synchronization state.
  std::wstring const explicitLabel = L"tck-explicit-synchronization";
  rti::FederateHandleSet invalidExplicitSet{rti::FederateHandle{}};
  requireException(
      [&] {
        first.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-invalid-explicit-synchronization",
            tag,
            invalidExplicitSet);
      },
      L"InvalidFederateHandle",
      "explicit synchronization set with an invalid federate handle");
  rti::FederateHandleSet explicitSet{
      first.federateHandle(),
      second.federateHandle()};
  first.rtiAmbassador().registerFederationSynchronizationPoint(
      explicitLabel,
      tag,
      explicitSet);
  waitForSessions(
      {&first, &second},
      [&] {
        return first.synchronizationPointRegistrations().size() >= 2U &&
            first.synchronizationPointAnnouncements().size() >= 2U &&
            second.synchronizationPointAnnouncements().size() >= 2U;
      },
      options,
      "explicit synchronization-set registration and announcement");
  for (int pass = 0; pass != 8; ++pass) {
    third.pump();
  }
  require(third.synchronizationPointAnnouncements().size() == 1U,
          "explicit synchronization set announced to an excluded federate");

  first.rtiAmbassador().synchronizationPointAchieved(explicitLabel);
  second.rtiAmbassador().synchronizationPointAchieved(explicitLabel);
  waitForSessions(
      {&first, &second},
      [&] {
        return first.federationSynchronized().size() >= 2U &&
            second.federationSynchronized().size() >= 2U;
      },
      options,
      "explicit synchronization-set completion");
  require(third.federationSynchronized().size() == 1U,
          "excluded federate received explicit synchronization completion");
  for (auto* session : {&first, &second}) {
    auto const completions = session->federationSynchronized();
    require(completions.back().label == explicitLabel &&
                completions.back().failedToSyncSet.empty(),
            "explicit synchronization completion returned an unexpected failure set");
  }

  third.resign(rti::NO_ACTION);
  second.resign(rti::NO_ACTION);
  first.resign(rti::NO_ACTION);
  first.rtiAmbassador().destroyFederationExecution(federation);
  third.disconnect();
  second.disconnect();
  first.disconnect();
}

void scenarioSynchronizationPointExplicitSetLateJoin(
    Options const& options,
    rti::CallbackModel model) {
  Session registrar(options, model, "synchronization-explicit-set-registrar");
  Session late(options, model, "synchronization-explicit-set-late-member");
  auto const federation = federationName(
      options,
      "synchronization-explicit-set-late-join");

  registrar.connect();
  late.connect();
  registrar.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  registrar.join(options.ownerFederateName, options.federateType, federation);

  std::wstring const label = L"tck-explicit-set-late-join";
  std::vector<std::uint8_t> tagBytes{0x53U, 0x45U, 0x54U};
  rti::VariableLengthData const tag(tagBytes.data(), tagBytes.size());
  rti::FederateHandleSet const synchronizationSet{registrar.federateHandle()};
  registrar.rtiAmbassador().registerFederationSynchronizationPoint(
      label,
      tag,
      synchronizationSet);
  waitFor(
      registrar,
      [&] {
        return registrar.synchronizationPointRegistrations().size() == 1U &&
            registrar.synchronizationPointAnnouncements().size() == 1U;
      },
      options,
      "explicit synchronization-set registration before late join");
  auto const registration = registrar.synchronizationPointRegistrations().front();
  auto const announcement = registrar.synchronizationPointAnnouncements().front();
  require(
      registration.succeeded && registration.label == label,
      "explicit synchronization-set registration returned the wrong result");
  require(
      announcement.label == label && announcement.tag == tagBytes,
      "explicit synchronization-set announcement returned the wrong label or tag");

  late.join(L"tck-explicit-set-late-member", options.federateType, federation);
  requireException(
      [&] { late.rtiAmbassador().synchronizationPointAchieved(label); },
      L"SynchronizationPointLabelNotAnnounced",
      "late joiner outside an explicit synchronization set achieved its label");

  registrar.rtiAmbassador().synchronizationPointAchieved(label);
  waitFor(
      registrar,
      [&] { return registrar.federationSynchronized().size() == 1U; },
      options,
      "single-member explicit synchronization-set completion");
  auto const completion = registrar.federationSynchronized().front();
  require(
      completion.label == label && completion.failedToSyncSet.empty(),
      "explicit synchronization-set completion returned the wrong label or failed set");

  late.resign(rti::NO_ACTION);
  registrar.resign(rti::NO_ACTION);
  registrar.rtiAmbassador().destroyFederationExecution(federation);
  late.disconnect();
  registrar.disconnect();
}

void scenarioAsynchronousDelivery(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(options, "asynchronous-delivery");
  connectAndJoin(publisher, receiver, options, federation, options.fom);

  rti::ObjectClassHandle publisherObjectClass;
  rti::AttributeHandle publisherAttribute;
  rti::InteractionClassHandle publisherInteraction;
  rti::ParameterHandle publisherParameter;
  handles(
      publisher,
      options,
      publisherObjectClass,
      publisherAttribute,
      publisherInteraction,
      publisherParameter);
  rti::ObjectClassHandle receiverObjectClass;
  rti::AttributeHandle receiverAttribute;
  rti::InteractionClassHandle receiverInteraction;
  rti::ParameterHandle receiverParameter;
  handles(
      receiver,
      options,
      receiverObjectClass,
      receiverAttribute,
      receiverInteraction,
      receiverParameter);
  require(publisherParameter == receiverParameter,
          "asynchronous-delivery parameter handles did not retain identity");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction);
  auto const receiverTime = makeTimeContext(receiver);
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "asynchronous-delivery time-constrained callback");

  std::vector<std::uint8_t> valueBytes{0xA5U, 0x51U};
  std::vector<std::uint8_t> firstTagBytes{0x41U, 0x53U, 0x59U, 0x31U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData firstTag(firstTagBytes.data(), firstTagBytes.size());

  // Receive-order callbacks are held for a time-constrained federate while
  // asynchronous delivery is disabled.  The assertion is intentionally made
  // before callback servicing in evoked mode and after a bounded drain in both
  // models, so it checks retention rather than timing luck.
  publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      firstTag);
  if (model == rti::HLA_EVOKED) {
    require(!receiver.recorder().interaction().present,
            "evoked receive-order callback arrived before callback servicing");
  }
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(!receiver.recorder().interaction().present,
          "receive-order callback bypassed disabled asynchronous delivery");

  receiver.rtiAmbassador().enableAsynchronousDelivery();
  requireException(
      [&] { receiver.rtiAmbassador().enableAsynchronousDelivery(); },
      L"AsynchronousDeliveryAlreadyEnabled",
      "enabling asynchronous delivery twice");
  if (model == rti::HLA_EVOKED) {
    static_cast<void>(receiver.evokeMultipleCallbacks(0.0, 0.0));
  }
  waitFor(
      receiver,
      [&] { return receiver.recorder().interaction().present; },
      options,
      "asynchronous receive-order callback release");
  auto const firstReceived = receiver.recorder().interaction();
  require(firstReceived.interaction == receiverInteraction &&
              firstReceived.parameters.size() == 1U &&
              firstReceived.parameters.find(receiverParameter) !=
                  firstReceived.parameters.end() &&
              firstReceived.tag == firstTagBytes,
          "released asynchronous interaction did not preserve application data");

  receiver.recorder().clearInteraction();
  receiver.rtiAmbassador().disableAsynchronousDelivery();
  requireException(
      [&] { receiver.rtiAmbassador().disableAsynchronousDelivery(); },
      L"AsynchronousDeliveryAlreadyDisabled",
      "disabling asynchronous delivery twice");
  std::vector<std::uint8_t> secondTagBytes{0x41U, 0x53U, 0x59U, 0x32U};
  rti::VariableLengthData secondTag(secondTagBytes.data(), secondTagBytes.size());
  publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      secondTag);
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(!receiver.recorder().interaction().present,
          "disabled asynchronous delivery did not retain the second interaction");

  auto const nextTime = timeAfter(
      *receiverTime.factory,
      *receiverTime.initial,
      *receiverTime.epsilon,
      1U);
  receiver.rtiAmbassador().timeAdvanceRequest(*nextTime);
  waitFor(
      receiver,
      [&] { return receiver.recorder().interaction().present; },
      options,
      "time-advance release of a retained receive-order callback");
  auto const secondReceived = receiver.recorder().interaction();
  require(secondReceived.tag == secondTagBytes,
          "time-advance release delivered the wrong retained interaction");
  requireException(
      [&] { receiver.rtiAmbassador().disableAsynchronousDelivery(); },
      L"AsynchronousDeliveryAlreadyDisabled",
      "disabling asynchronous delivery after time-advance release");

  receiver.rtiAmbassador().disableTimeConstrained();
  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}











