void requireValue(int& index, int argc, char** argv, std::string const& option) {
  if (index + 1 >= argc) {
    throw std::runtime_error("Missing value for " + option);
  }
}

Options parseOptions(int argc, char** argv) {
  Options options;
  for (int index = 1; index < argc; ++index) {
    auto const argument = std::string(argv[index]);
    if (argument == "--help") {
      printHelp();
      std::exit(0);
    }
    if (argument == "--fom") {
      requireValue(index, argc, argv, argument);
      options.fom = argv[++index];
    } else if (argument == "--model-fom") {
      requireValue(index, argc, argv, argument);
      options.modelFom = argv[++index];
    } else if (argument == "--fom-custom-transportation") {
      requireValue(index, argc, argv, argument);
      options.fomCustomTransportationName = toWide(argv[++index]);
    } else if (argument == "--fom-additional-transportation") {
      requireValue(index, argc, argv, argument);
      options.fomAdditionalTransportationName = toWide(argv[++index]);
    } else if (argument == "--fom-dimension") {
      requireValue(index, argc, argv, argument);
      options.fomDimensionName = toWide(argv[++index]);
    } else if (argument == "--fom-additional-dimension") {
      requireValue(index, argc, argv, argument);
      options.fomAdditionalDimensionName = toWide(argv[++index]);
    } else if (argument == "--fom-additional-dimension-object-class") {
      requireValue(index, argc, argv, argument);
      options.fomAdditionalDimensionObjectClassName = toWide(argv[++index]);
    } else if (argument == "--fom-additional-dimension-attribute") {
      requireValue(index, argc, argv, argument);
      options.fomAdditionalDimensionAttributeName = toWide(argv[++index]);
    } else if (argument == "--rate-fom") {
      requireValue(index, argc, argv, argument);
      options.rateFom = argv[++index];
    } else if (argument == "--ddm-fom") {
      requireValue(index, argc, argv, argument);
      options.ddmFom = argv[++index];
    } else if (argument == "--multi-attribute-fom") {
      requireValue(index, argc, argv, argument);
      options.multiAttributeFom = argv[++index];
    } else if (argument == "--three-dimensional-fom") {
      requireValue(index, argc, argv, argument);
      options.threeDimensionalFom = argv[++index];
    } else if (argument == "--mim-fom") {
      requireValue(index, argc, argv, argument);
      options.mimFom = argv[++index];
    } else if (argument == "--switches-fom") {
      requireValue(index, argc, argv, argument);
      options.switchesFom = argv[++index];
    } else if (argument == "--auto-provide-fom") {
      requireValue(index, argc, argv, argument);
      options.autoProvideFom = argv[++index];
    } else if (argument == "--known-class-fom") {
      requireValue(index, argc, argv, argument);
      options.knownClassFom = argv[++index];
    } else if (argument == "--known-class-disabled-fom") {
      requireValue(index, argc, argv, argument);
      options.knownClassDisabledFom = argv[++index];
    } else if (argument == "--ddm-dimension") {
      requireValue(index, argc, argv, argument);
      if (!options.ddmDimensionsConfigured) {
        options.ddmDimensionNames.clear();
        options.ddmDimensionsConfigured = true;
      }
      options.ddmDimensionNames.push_back(toWide(argv[++index]));
    } else if (argument == "--ddm-unrelated-dimension") {
      requireValue(index, argc, argv, argument);
      options.ddmUnrelatedDimensionName = toWide(argv[++index]);
    } else if (argument == "--three-dimensional-dimension") {
      requireValue(index, argc, argv, argument);
      if (!options.threeDimensionalDimensionsConfigured) {
        options.threeDimensionalDimensionNames.clear();
        options.threeDimensionalDimensionsConfigured = true;
      }
      options.threeDimensionalDimensionNames.push_back(toWide(argv[++index]));
    } else if (argument == "--additional-fom") {
      requireValue(index, argc, argv, argument);
      options.additionalFomModules.emplace_back(argv[++index]);
    } else if (argument == "--invalid-fom") {
      requireValue(index, argc, argv, argument);
      options.invalidFomModules.emplace_back(argv[++index]);
    } else if (argument == "--standard-invalid-fom") {
      requireValue(index, argc, argv, argument);
      options.standardInvalidFomModules.emplace_back(argv[++index]);
    } else if (argument == "--scenario") {
      requireValue(index, argc, argv, argument);
      options.scenarios.emplace_back(argv[++index]);
    } else if (argument == "--callback-model") {
      requireValue(index, argc, argv, argument);
      options.callbackModel = argv[++index];
    } else if (argument == "--provider-id") {
      requireValue(index, argc, argv, argument);
      options.providerId = argv[++index];
    } else if (argument == "--results") {
      requireValue(index, argc, argv, argument);
      options.results = argv[++index];
    } else if (argument == "--junit") {
      requireValue(index, argc, argv, argument);
      options.junit = argv[++index];
    } else if (argument == "--connection-loss-server-managed") {
      options.connectionLossServerManaged = true;
    } else if (argument == "--connection-loss-marker") {
      requireValue(index, argc, argv, argument);
      options.connectionLossMarker = argv[++index];
    } else if (argument == "--connection-loss-ready-marker") {
      requireValue(index, argc, argv, argument);
      options.connectionLossReadyMarker = argv[++index];
    } else if (argument == "--federation-prefix") {
      requireValue(index, argc, argv, argument);
      options.federationPrefix = argv[++index];
    } else if (argument == "--federation-name") {
      requireValue(index, argc, argv, argument);
      options.federationOverride = toWide(argv[++index]);
    } else if (argument == "--owner-name") {
      requireValue(index, argc, argv, argument);
      options.ownerFederateName = toWide(argv[++index]);
    } else if (argument == "--member-name") {
      requireValue(index, argc, argv, argument);
      options.memberFederateName = toWide(argv[++index]);
    } else if (argument == "--federate-type") {
      requireValue(index, argc, argv, argument);
      options.federateType = toWide(argv[++index]);
    } else if (argument == "--configuration-name") {
      requireValue(index, argc, argv, argument);
      options.configurationName = argv[++index];
    } else if (argument == "--owner-configuration-name") {
      requireValue(index, argc, argv, argument);
      options.ownerConfigurationName = argv[++index];
    } else if (argument == "--member-configuration-name") {
      requireValue(index, argc, argv, argument);
      options.memberConfigurationName = argv[++index];
    } else if (argument == "--rti-address") {
      requireValue(index, argc, argv, argument);
      options.rtiAddress = argv[++index];
    } else if (argument == "--additional-settings") {
      requireValue(index, argc, argv, argument);
      options.additionalSettings = argv[++index];
    } else if (argument == "--service-report-directory") {
      requireValue(index, argc, argv, argument);
      options.serviceReportDirectory = argv[++index];
    } else if (argument == "--object-class") {
      requireValue(index, argc, argv, argument);
      options.objectClassName = toWide(argv[++index]);
    } else if (argument == "--attribute") {
      requireValue(index, argc, argv, argument);
      options.attributeName = toWide(argv[++index]);
    } else if (argument == "--secondary-attribute") {
      requireValue(index, argc, argv, argument);
      options.secondaryAttributeName = toWide(argv[++index]);
    } else if (argument == "--object-class-third-attribute") {
      requireValue(index, argc, argv, argument);
      options.objectClassThirdAttributeName = toWide(argv[++index]);
    } else if (argument == "--auto-provide-object-class") {
      requireValue(index, argc, argv, argument);
      options.autoProvideObjectClassName = toWide(argv[++index]);
    } else if (argument == "--auto-provide-first") {
      requireValue(index, argc, argv, argument);
      options.autoProvideFirstAttributeName = toWide(argv[++index]);
    } else if (argument == "--auto-provide-second") {
      requireValue(index, argc, argv, argument);
      options.autoProvideSecondAttributeName = toWide(argv[++index]);
    } else if (argument == "--multi-attribute-object-class") {
      requireValue(index, argc, argv, argument);
      options.multiAttributeObjectClassName = toWide(argv[++index]);
    } else if (argument == "--multi-attribute-first") {
      requireValue(index, argc, argv, argument);
      options.multiAttributeFirstName = toWide(argv[++index]);
    } else if (argument == "--multi-attribute-second") {
      requireValue(index, argc, argv, argument);
      options.multiAttributeSecondName = toWide(argv[++index]);
    } else if (argument == "--rate-object-class") {
      requireValue(index, argc, argv, argument);
      options.rateObjectClassName = toWide(argv[++index]);
    } else if (argument == "--rate-reliable-attribute") {
      requireValue(index, argc, argv, argument);
      options.rateReliableAttributeName = toWide(argv[++index]);
    } else if (argument == "--rate-best-effort-attribute") {
      requireValue(index, argc, argv, argument);
      options.rateBestEffortAttributeName = toWide(argv[++index]);
    } else if (argument == "--rate-designator") {
      requireValue(index, argc, argv, argument);
      options.rateDesignatorName = toWide(argv[++index]);
    } else if (argument == "--fom-update-rate") {
      requireValue(index, argc, argv, argument);
      options.fomUpdateRateName = toWide(argv[++index]);
    } else if (argument == "--fom-additional-update-rate") {
      requireValue(index, argc, argv, argument);
      options.fomAdditionalUpdateRateName = toWide(argv[++index]);
    } else if (argument == "--three-dimensional-object-class") {
      requireValue(index, argc, argv, argument);
      options.threeDimensionalObjectClassName = toWide(argv[++index]);
    } else if (argument == "--three-dimensional-attribute") {
      requireValue(index, argc, argv, argument);
      options.threeDimensionalAttributeName = toWide(argv[++index]);
    } else if (argument == "--custom-regional-object-class") {
      requireValue(index, argc, argv, argument);
      options.customRegionalObjectClassName = toWide(argv[++index]);
    } else if (argument == "--custom-regional-attribute") {
      requireValue(index, argc, argv, argument);
      options.customRegionalAttributeName = toWide(argv[++index]);
    } else if (argument == "--custom-regional-interaction-class") {
      requireValue(index, argc, argv, argument);
      options.customRegionalInteractionClassName = toWide(argv[++index]);
    } else if (argument == "--custom-regional-parameter") {
      requireValue(index, argc, argv, argument);
      options.customRegionalParameterName = toWide(argv[++index]);
    } else if (argument == "--interaction-class") {
      requireValue(index, argc, argv, argument);
      options.interactionClassName = toWide(argv[++index]);
    } else if (argument == "--secondary-directed-object-class") {
      requireValue(index, argc, argv, argument);
      options.secondaryDirectedObjectClassName = toWide(argv[++index]);
    } else if (argument == "--secondary-directed-interaction-class") {
      requireValue(index, argc, argv, argument);
      options.secondaryDirectedInteractionClassName = toWide(argv[++index]);
    } else if (argument == "--parameter") {
      requireValue(index, argc, argv, argument);
      options.parameterName = toWide(argv[++index]);
    } else if (argument == "--known-class-object-class") {
      requireValue(index, argc, argv, argument);
      options.knownClassObjectClassName = toWide(argv[++index]);
    } else if (argument == "--known-class-derived-object-class") {
      requireValue(index, argc, argv, argument);
      options.knownClassDerivedObjectClassName = toWide(argv[++index]);
    } else if (argument == "--known-class-known-attribute") {
      requireValue(index, argc, argv, argument);
      options.knownClassKnownAttributeName = toWide(argv[++index]);
    } else if (argument == "--known-class-derived-attribute") {
      requireValue(index, argc, argv, argument);
      options.knownClassDerivedAttributeName = toWide(argv[++index]);
    } else if (argument == "--time-implementation") {
      requireValue(index, argc, argv, argument);
      options.logicalTimeImplementationName = toWide(argv[++index]);
    } else if (argument == "--timeout-ms") {
      requireValue(index, argc, argv, argument);
      options.timeoutMilliseconds = std::stoi(argv[++index]);
    } else {
      throw std::runtime_error("Unknown option: " + argument);
    }
  }
  if (options.fom.empty()) {
    throw std::runtime_error("--fom is required");
  }
  if (!std::filesystem::is_regular_file(options.fom)) {
    throw std::runtime_error("FOM file does not exist: " + options.fom.string());
  }
  if (!options.modelFom.empty() && !std::filesystem::is_regular_file(options.modelFom)) {
    throw std::runtime_error("FOM model file does not exist: " + options.modelFom.string());
  }
  if (!options.ddmFom.empty() && !std::filesystem::is_regular_file(options.ddmFom)) {
    throw std::runtime_error("DDM FOM file does not exist: " + options.ddmFom.string());
  }
  if (!options.multiAttributeFom.empty() &&
      !std::filesystem::is_regular_file(options.multiAttributeFom)) {
    throw std::runtime_error(
        "Multi-attribute DDM FOM file does not exist: " +
        options.multiAttributeFom.string());
  }
  if (!options.threeDimensionalFom.empty() &&
      !std::filesystem::is_regular_file(options.threeDimensionalFom)) {
    throw std::runtime_error(
        "Three-dimensional DDM FOM file does not exist: " +
        options.threeDimensionalFom.string());
  }
  if (!options.mimFom.empty() && !std::filesystem::is_regular_file(options.mimFom)) {
    throw std::runtime_error("MIM FOM file does not exist: " + options.mimFom.string());
  }
  if (!options.switchesFom.empty() && !std::filesystem::is_regular_file(options.switchesFom)) {
    throw std::runtime_error("Switch-declaration FOM file does not exist: " + options.switchesFom.string());
  }
  if (!options.autoProvideFom.empty() &&
      !std::filesystem::is_regular_file(options.autoProvideFom)) {
    throw std::runtime_error(
        "Auto Provide FOM file does not exist: " + options.autoProvideFom.string());
  }
  if (!options.knownClassFom.empty() &&
      !std::filesystem::is_regular_file(options.knownClassFom)) {
    throw std::runtime_error(
        "Known-class advisory FOM file does not exist: " +
        options.knownClassFom.string());
  }
  if (!options.knownClassDisabledFom.empty() &&
      !std::filesystem::is_regular_file(options.knownClassDisabledFom)) {
    throw std::runtime_error(
        "Known-class-disabled advisory FOM file does not exist: " +
        options.knownClassDisabledFom.string());
  }
  if (!options.rateFom.empty() && !std::filesystem::is_regular_file(options.rateFom)) {
    throw std::runtime_error(
        "Attribute relevance rate advisory FOM file does not exist: " +
        options.rateFom.string());
  }
  if (!options.ddmFom.empty() && options.ddmDimensionNames.size() < 2U) {
    throw std::runtime_error("--ddm-fom requires at least two --ddm-dimension values");
  }
  if (!options.threeDimensionalFom.empty() &&
      options.threeDimensionalDimensionNames.size() < 3U) {
    throw std::runtime_error(
        "--three-dimensional-fom requires at least three "
        "--three-dimensional-dimension values");
  }
  for (auto const& path : options.additionalFomModules) {
    if (!std::filesystem::is_regular_file(path)) {
      throw std::runtime_error("Additional FOM file does not exist: " + path.string());
    }
  }
  for (auto const& path : options.invalidFomModules) {
    if (!std::filesystem::is_regular_file(path)) {
      throw std::runtime_error("Invalid FOM file does not exist: " + path.string());
    }
  }
  for (auto const& path : options.standardInvalidFomModules) {
    if (!std::filesystem::is_regular_file(path)) {
      throw std::runtime_error(
          "Standard-invalid FOM file does not exist: " + path.string());
    }
  }
  if (options.callbackModel != "both" && options.callbackModel != "evoked" &&
      options.callbackModel != "immediate") {
    throw std::runtime_error("--callback-model must be both, evoked, or immediate");
  }
  if (options.timeoutMilliseconds <= 0) {
    throw std::runtime_error("--timeout-ms must be positive");
  }
  if (options.scenarios.empty()) {
    options.scenarios = allScenarioIds();
  }
  return options;
}

